  str_skill_desc_300050 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>16 tiles in a radial shape</color> and knocks enemies back.",
  str_skill_desc_320050 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>16 tiles in a radial shape</color> and knocks enemies back. Knocked back enemies suffer 10% reduced DEF.",
  str_skill_desc_300022 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and a <color=#00F6FF>cross shape to the maximum range</color> and knocks enemies back.",
  str_skill_desc_303022 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and a <color=#00F6FF>cross shape to the maximum range</color> and knocks enemies back.",
  str_skill_desc_310022 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and a <color=#00F6FF>cross shape to the maximum range</color> and knocks enemies back.",
  str_skill_desc_313022 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and a <color=#00F6FF>cross shape to the maximum range</color> and knocks enemies back.",
  str_skill_desc_300047 = "Recovers the team's HP by <color=#00F6FF>150%</color> of Zoya's ATK. Each Blue tile on the field increases healing effectiveness by <color=#00F6FF>5%</color>.",
  str_skill_desc_303047 = "Recovers the team's HP by <color=#00F6FF>150%</color> of Zoya's ATK. Each Blue tile on the field increases healing effectiveness by <color=#00F6FF>5%</color>.",
  str_skill_desc_320047 = "Recovers the team's HP by <color=#00F6FF>150%</color> of Zoya's ATK. Each Blue tile on the field increases healing effectiveness by <color=#00F6FF>8%</color>.",
  str_skill_desc_323047 = "Recovers the team's HP by <color=#00F6FF>150%</color> of Zoya's ATK. Each Blue tile on the field increases healing effectiveness by <color=#00F6FF>8%</color>.",
  str_skill_desc_300049 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_303049 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_320049 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and converts all Red tiles within attack range to other elements.",
  str_skill_desc_323049 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and converts all Red tiles within attack range to other elements.",
  str_skill_desc_300051 = "Attacks in any 1 selected direction. Deals <color=#00F6FF>240%</color> damage to the first enemy hit and to enemies within <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_310051 = "Attacks in any 1 selected direction. Deals <color=#00F6FF>240%</color> damage to the first enemy hit and to enemies within <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_320051 = "Attacks in any 1 selected direction. Deals <color=#00F6FF>240%</color> damage to the first enemy hit and enemies within <color=#00F6FF>1 surrounding cluster</color>, and inflicts <link=\"10002\"><#FFAE07><u>Burn</u></color></link> (2 stacks on the first enemy, 1 stack on the rest) for 2 rounds.",
  str_skill_desc_300052 = "Teleports to a selected location within a 3-tile distance. Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>4 tiles in a cross shape</color> at that location.",
  str_skill_desc_310052 = "Teleports to a selected location within a 3-tile distance. Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>4 tiles in a cross shape</color> at that location.",
  str_skill_desc_320052 = "Teleports to a selected location within a 3-tile distance. Deals <color=#00F6FF>{1}%</color> damage to tiles within <color=#00F6FF>1 surrounding cluster</color> of this location.",
  str_skill_desc_300007 = "Deals <color=#00F6FF>{1}%</color> damage <color=#00F6FF>in a cross shape to the maximum range</color>.",
  str_skill_desc_320007 = "Deals <color=#00F6FF>{1}%</color> damage to a <color=#00F6FF>cross-shape area in the maximum range</color>. Doubles the stacks of Poison if the target has been Poisoned. Once the target is inflicted the maximum 5 stacks of Poison, Active Skills deal +<color=#00F6FF>50%</color> damage to the target.",
  str_skill_desc_300008 = "Converts 1 traversable tile to a Red <link=\"30001\"><#FFAE07><u>Prism tile</u></color></link>.",
  str_skill_desc_310008 = "Converts 1 traversable tile to a Red <link=\"30001\"><#FFAE07><u>Prism tile</u></color></link>.",
  str_skill_desc_300032 = "Deals <color=#00F6FF>100%</color> damage <color=#00F6FF>6-10</color> times randomly to enemies on the field. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_310032 = "Deals <color=#00F6FF>100%</color> damage <color=#00F6FF>6-10</color> times randomly to enemies on the field. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_300035 = "Teleports to any tile within <color=#00F6FF>2 surrounding clusters</color> around the unit.",
  str_skill_desc_310035 = "Teleports to any tile within <color=#00F6FF>2 surrounding clusters</color> around the unit.",
  str_skill_desc_320035 = "Teleports to any tile within <color=#00F6FF>2 surrounding clusters</color> around the unit.",
  str_skill_desc_300058 = "Places the banner on 1 selected tile. The closer Amy is to the banner, the higher her DEF increases (up to <color=#00F6FF>100%</color>). The banner disappears when touched by an enemy.",
  str_skill_desc_303058 = "Places the banner on 1 selected tile. The closer Amy is to the banner, the higher her DEF increases (up to <color=#00F6FF>100%</color>). The banner disappears when touched by an enemy.",
  str_skill_desc_310058 = "Places the banner on 1 selected tile. The closer Amy is to the banner, the higher her DEF increases (up to <color=#00F6FF>100%</color>). The banner disappears when touched by an enemy.",
  str_skill_desc_313058 = "Places the banner on 1 selected tile. The closer Amy is to the banner, the higher her DEF increases (up to <color=#00F6FF>100%</color>). The banner disappears when touched by an enemy.",
  str_skill_desc_300053 = "Deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. Damage is increased to <color=#00F6FF>150%</color> if there is only 1 enemy.",
  str_skill_desc_303053 = "Deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. Damage is increased to <color=#00F6FF>150%</color> if there is only 1 enemy. Removes Active Skill cooldown if the target is killed with the skill.",
  str_skill_desc_310053 = "Deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. Damage is increased to <color=#00F6FF>150%</color> if there is only 1 enemy.",
  str_skill_desc_313053 = "Deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. Damage is increased to <color=#00F6FF>150%</color> if there is only 1 enemy. Removes Active Skill cooldown if the target is killed with the skill.",
  str_skill_desc_320053 = "Deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. Damage is increased to <color=#00F6FF>200%</color> if there is only 1 enemy.",
  str_skill_desc_323053 = "Deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. Damage is increased to <color=#00F6FF>200%</color> if there is only 1 enemy. Removes Active Skill cooldown if the target is killed with the skill.",
  str_skill_desc_300074 = "Deals <color=#00F6FF>{1}%</color> damage to a <color=#00F6FF>cross shape to the maximum range</color> and aggros them to the unit.",
  str_skill_desc_310074 = "Deals <color=#00F6FF>{1}%</color> damage to a <color=#00F6FF>cross shape to the maximum range</color> and aggros them to the unit.",
  str_skill_desc_320074 = "Deals <color=#00F6FF>{1}%</color> damage to a <color=#00F6FF>cross shape to the maximum range</color> and aggros them to the unit. For every <color=#00F6FF>1</color> tile aggroed, the enemy takes <color=#00F6FF>10%</color> more final damage.",
