  str_skill_desc_320017 = "Teleports to a selected location. Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and knocks enemies back.",
  str_skill_desc_300040 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> and resets all tiles within the area of attack.",
  str_skill_desc_330040 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> and resets all <color=#00F6FF>non-Red</color> tiles within the area of attack. There is a <color=#00F6FF>small chance</color> to generate Red tiles.",
