  str_skill_desc_302084 = "When used, a Fire Aurorian's Chain Combo will be triggered <color=#00F6FF>2</color> times in this round. For the <color=#00F6FF>second</color> Chain Combo, the ATK of all Fire Aurorians is equal to <color=#00F6FF>70%</color> of Istvan's ATK.",
  str_skill_desc_305084 = "When used, a Fire Aurorian's Chain Combo will be triggered <color=#00F6FF>2</color> times in this round. For the <color=#00F6FF>second</color> Chain Combo, the ATK of all Fire Aurorians is equal to <color=#00F6FF>70%</color> of Istvan's ATK.",
  str_skill_desc_330084 = "When used, a Fire Aurorian's Chain Combo will be triggered <color=#00F6FF>2</color> times in this round. For the <color=#00F6FF>second</color> Chain Combo, the ATK of all Fire Aurorians is equal to <color=#00F6FF>85%</color> of Istvan's ATK.",
  str_skill_desc_332084 = "When used, a Fire Aurorian's Chain Combo will be triggered <color=#00F6FF>2</color> times in this round. For the <color=#00F6FF>second</color> Chain Combo, the ATK of all Fire Aurorians is equal to <color=#00F6FF>85%</color> of Istvan's ATK.",
  str_skill_desc_335084 = "When used, a Fire Aurorian's Chain Combo will be triggered <color=#00F6FF>2</color> times in this round. For the <color=#00F6FF>second</color> Chain Combo, the ATK of all Fire Aurorians is equal to <color=#00F6FF>85%</color> of Istvan's ATK.",
  str_skill_desc_300090 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies and stuns all enemies on Red tiles.",
  str_skill_desc_302090 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies and stuns all enemies on Red tiles.",
  str_skill_desc_320090 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies and stuns all enemies on Red tiles. Enemies on other tiles have a <color=#00F6FF>35%</color> chance of being stunned.",
  str_skill_desc_322090 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies and stuns all enemies on Red tiles. Enemies on other tiles have a <color=#00F6FF>35%</color> chance of being stunned.",
  str_skill_desc_300045 = "Chooses 1 tile as the target, sacrifices <color=#00F6FF>15%</color> of current HP to deal an equal amount of damage to enemies within <color=#00F6FF>9 square tiles</color> (this damage ignores DEF), and inflicts 1 stack of <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> that lasts for 2 rounds.",
  str_skill_desc_320045 = "Chooses 1 tile as the target, sacrifices <color=#00F6FF>15%</color> of current HP to deal an equal amount of damage to enemies within <color=#00F6FF>9 square tiles</color> (this damage ignores DEF), and inflicts <link=\"30004\"><#FFAE07><u>1 stack</u></color></link> of Bleeding that lasts for 2 rounds.",
  str_skill_desc_330045 = "Chooses 1 tile as the target, sacrifices <color=#00F6FF>15%</color> of current HP to deal an equal amount of damage to enemies within <color=#00F6FF>9 square tiles</color> (this damage ignores DEF), and inflicts <link=\"30004\"><#FFAE07><u>1 stack</u></color></link> of Bleeding that lasts for 2 rounds. Nails' basic Max HP increases by <color=#00F6FF>50%</color>.",
  str_skill_desc_300081 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies and aggros all enemies to the unit.",
  str_skill_desc_320081 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies and aggros all enemies to the unit. The final damage increases by <color=#00F6FF>10%</color> for each tile enemies move on.",
  str_skill_desc_300083 = "Selects 1 tile, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>4 tiles in a cross shape</color> and knocking enemies back.",
