  str_skill_desc_330083 = "Selects 1 tile, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and knocking enemies back, as well as decreasing their DEF in proportion to the percentage of the damage dealt for 2 rounds.",
  str_skill_desc_300059 = "Moves to any tile within <color=#00F6FF>1 surrounding cluster</color> around the unit.",
  str_skill_desc_3000591 = "Moves to any tile within <color=#00F6FF>1 surrounding cluster</color> around the unit.",
  str_skill_desc_3000592 = "Moves to any tile in <color=#00F6FF>2 surrounding clusters</color> around the unit.",
  str_skill_desc_3000593 = "Moves to any tile in <color=#00F6FF>3 surrounding clusters</color> around the unit.",
  str_skill_desc_3000594 = "Moves to any tile in <color=#00F6FF>4 surrounding clusters</color> around the unit.",
  str_skill_desc_3000595 = "Moves to any tile in <color=#00F6FF>5 surrounding clusters</color> around the unit.",
  str_skill_desc_300080 = "Throws a can at any selected tile, changing the tile to a Yellow tile. A Lightning Crystal, Meteorite Crystal, Bandage, Attack, or Defense is randomly generated on the tile.",
  str_skill_desc_320080 = "Throws a can at any selected tile, changing the tile to a yellow <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link>. A Lightning Crystal, Meteorite Crystal, Bandage, Attack, or Defense is randomly generated on the tile.",
  str_skill_desc_300093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>{1}%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack.",
  str_skill_desc_306093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>{1}%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack. Removes Active Skill cooldown if the target is killed with the skill (once per round).",
  str_skill_desc_310093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>{1}%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack.",
  str_skill_desc_316093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>{1}%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack. Removes Active Skill cooldown if the target is killed with the skill (once per round).",
  str_skill_desc_320093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>{1}%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack. Final damage increases by <color=#00F6FF>15%</color> for each enemy killed. Stacks up to 10 times.",
  str_skill_desc_326093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>{1}%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack. Final damage increases by <color=#00F6FF>15%</color> for each enemy killed. Stacks up to 10 times. Removes Active Skill cooldown if the target is killed with the skill (once per round).",
  str_skill_desc_330093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>{1}%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack. Final damage increases by <color=#00F6FF>15%</color> for each enemy killed. Stacks up to 10 times.",
  str_skill_desc_336093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>{1}%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack. Final damage increases by <color=#00F6FF>15%</color> for each enemy killed. Stacks up to 10 times. Removes Active Skill cooldown if the target is killed with the skill (once per round).",
  str_skill_desc_300097 = "Teleports to any location and deals damage to enemies in a rectangle shape between the starting point and the destination. The smaller the rectangle, the higher the damage dealt, up to <color=#00F6FF>480%</color> damage.",
  str_skill_desc_302097 = "Teleports to any location and deals damage to enemies in a rectangle shape between the starting point and the destination. The smaller the rectangle, the higher the damage dealt, up to <color=#00F6FF>600%</color> damage.",
  str_skill_desc_300095 = "Selects 1 tile and places 1 mine in it and in adjacent <color=#00F6FF>4 X-shaped tiles</color>. The mines deal <color=#00F6FF>190%</color> damage each when triggered and inflict 1 stack of <link=\"10001\"><#FFAE07><u>Poison</u></color></link> for 2 rounds.",
  str_skill_desc_320095 = "Selects 1 tile and places 1 mine in it and in adjacent <color=#00F6FF>4 X-shaped tiles</color>. The mines deal <color=#00F6FF>190%</color> damage each (double for the chosen tile) when triggered and inflict 1 stack of <link=\"10001\"><#FFAE07><u>Poison</u></color></link> for 2 rounds.",
  str_skill_desc_330095 = "Selects 1 tile and places 1 mine in it and in adjacent <color=#00F6FF>4 X-shaped tiles</color>. The mines deal <color=#00F6FF>190%</color> damage each (double for the chosen tile) when triggered and inflict 1 stack of <link=\"10001\"><#FFAE07><u>Poison</u></color></link> for 2 rounds.",
  str_skill_desc_300062 = "Selects one of the farthest tiles around the unit in all <color=#00F6FF>8</color> directions and dashes to the selected location, dealing <color=#00F6FF>{1}%</color> damage to enemies along the way and on adjacent tiles.",
  str_skill_desc_320062 = "Selects one of the tiles at the edge of the battlefield and dashes to the selected location, dealing <color=#00F6FF>{1}%</color> damage to enemies along the way and on adjacent tiles.",
  str_skill_desc_300024 = "Marks 1 tile. When the number of connected tiles reaches <color=#00F6FF>2</color> times the number of tiles required to trigger a Chain Combo, casts the Chain Combo once at the marked location as well.",
  str_skill_desc_305024 = "Marks 1 tile. When the number of connected tiles reaches <color=#00F6FF>2</color> times the number of tiles required to trigger a Chain Combo, casts the Chain Combo once at the marked location as well.",
  str_skill_desc_320024 = "Marks 1 tile. When the number of connected tiles reaches <color=#00F6FF>2</color> times the number of tiles required to trigger a Chain Combo, casts the Chain Combo once at the marked location as well (increases the final damage of both Chain Combos by <color=#00F6FF>30%</color>).",
  str_skill_desc_325024 = "Marks 1 tile. When the number of connected tiles reaches <color=#00F6FF>2</color> times the number of tiles required to trigger a Chain Combo, casts the Chain Combo once at the marked location as well (increases the final damage of both Chain Combos by <color=#00F6FF>30%</color>).",
  str_skill_desc_330024 = "Marks 1 tile. When the number of connected tiles reaches <color=#00F6FF>1.5</color> times the number of tiles required to trigger a Chain Combo, casts the Chain Combo once at the marked location as well (increases the final damage of both Chain Combos by <color=#00F6FF>30%</color>).",
  str_skill_desc_335024 = "Marks 1 tile. When the number of connected tiles reaches <color=#00F6FF>1.5</color> times the number of tiles required to trigger a Chain Combo, casts the Chain Combo once at the marked location as well (increases the final damage of both Chain Combos by <color=#00F6FF>30%</color>).",
