  str_skill_desc_3061031 = "Converts the <color=#00F6FF>5</color> nearest Blue or Green tiles to Red. If the Active Skill is ready in the last round, increases the tile-converting count by <color=#00F6FF>+1</color> in this round.",
  str_skill_desc_300067 = "Decreases the next damage taken in this round by <color=#00F6FF>30%</color>, up to <color=#00F6FF>2</color> times of Alice's max HP.",
