  str_skill_desc_320067 = "Decreases the next damage taken in this round by <color=#00F6FF>30%</color> and immediately recovers <color=#00F6FF>10%</color> HP lost by the team when taking damage. The damage reduction and recovered HP cannot exceed <color=#00F6FF>2</color> times Alice's max HP.",
  str_skill_desc_324067 = "Decreases the next damage taken in this round by <color=#00F6FF>40%</color> and immediately recovers <color=#00F6FF>10%</color> HP lost by the team when taking damage. The damage reduction and recovered HP cannot exceed <color=#00F6FF>2</color> times Alice's max HP.",
  str_skill_desc_300104 = "Deals <color=#00F6FF>{1}%</color> damage to all enemies.",
  str_skill_desc_310104 = "Deals <color=#00F6FF>{1}%</color> damage to all enemies.",
  str_skill_desc_320104 = "Deals <color=#00F6FF>{1}%</color> damage to all enemies. If the number of enemies hit is 2 or less, the skill will be cast 1 more time this round.",
  str_skill_desc_300030 = "Selects 1 tile from the <color=#00F6FF>4 tiles in a cross shape</color> around and deals <color=#00F6FF>{1}%</color> damage in a fan-shaped area in this direction. (the closer the enemy is, the higher the damage. Can deal up to 2.5x damage).",
  str_skill_desc_306030 = "Selects 1 tile from the <color=#00F6FF>4 tiles in a cross shape</color> and deals <color=#00F6FF>{1}%</color> damage in a fan-shaped area in this direction. (the closer the enemy is, the higher the damage. Can deal up to 2.5x damage).",
  str_skill_desc_320030 = "Selects 1 tile from the <color=#00F6FF>8 tiles in a cross shape</color> in the surrounding area and deals <color=#00F6FF>{1}%</color> damage in a fan-shaped area in this direction (the closer the enemy is to Sinsa, the higher the damage. Can deal up to 2.5x damage). If an an outer tile is selected, Sinsa will move forward 1 tile to cast this skill.",
  str_skill_desc_326030 = "Selects 1 tile from the surrounding <color=#00F6FF>8 tiles in a cross shape</color> and deals <color=#00F6FF>{1}%</color> damage in a fan-shaped area in this direction (the closer the enemy is to Sinsa, the higher the damage. Can deal up to 3x damage). If an outer tile is selected, Sinsa will move forward 1 tile to cast this skill.",
  str_skill_desc_330030 = "Selects 1 tile from the <color=#00F6FF>8 tiles in a cross shape</color> in the surrounding area and deals <color=#00F6FF>{1}%</color> damage in a fan-shaped area in this direction (the closer the enemy is to Sinsa, the higher the damage. Can deal up to 2.5x damage). If an an outer tile is selected, Sinsa will move forward 1 tile to cast this skill.",
  str_skill_desc_336030 = "Selects 1 tile from the surrounding <color=#00F6FF>8 tiles in a cross shape</color> and deals <color=#00F6FF>{1}%</color> damage in a fan-shaped area in this direction (the closer the enemy is to Sinsa, the higher the damage. Can deal up to 3x damage). If an outer tile is selected, Sinsa will move forward 1 tile to cast this skill.",
  str_skill_desc_300071 = "Selects any tile in a <color=#00F6FF>cross shape</color>, converts this tile into a Red Enhanced Tile, and casts Dragonscorch to deal <color=#00F6FF>{1}%</color> damage to tiles along the way. After arriving at the selected tile, Dragonscorch spreads to the <color=#00F6FF>left and right side</color> of this tile to the maximum distance, dealing 80% damage.",
  str_skill_desc_305071 = "Selects any tile in a <color=#00F6FF>cross shape</color>, converts this tile into a Red Enhanced Tile, and casts Dragonscorch to deal <color=#00F6FF>{1}%</color> damage to tiles along the way. After arriving at the selected tile, Dragonscorch spreads to the <color=#00F6FF>left and right side</color> of this tile to the maximum distance, dealing 80% damage and converting the farthest tile on each side into a Red tile.",
  str_skill_desc_320071 = "Selects any tile in a <color=#00F6FF>cross shape</color>, converts this tile into a Red Enhanced Tile, and casts Dragonscorch to deal <color=#00F6FF>{1}%</color> damage to tiles along the way. After arriving at the selected tile, Dragonscorch spreads to the <color=#00F6FF>left and right side</color> of this tile to the maximum distance, dealing 80% damage. Dragonscorch inflicts the target with a Burn Mark before dealing damage.",
  str_skill_desc_325071 = "Selects any tile in a <color=#00F6FF>cross shape</color>, converts this tile into a Red Enhanced Tile, and casts Dragonscorch to deal <color=#00F6FF>{1}%</color> damage to tiles along the way. After arriving at the selected tile, Dragonscorch spreads to the <color=#00F6FF>left and right side</color> of this tile to the maximum distance, dealing 80% damage and converting the farthest tile on each side into a Red tile. Dragonscorch inflicts the target with a Burn Mark before dealing damage.",
  str_skill_desc_300105 = "Selects 1 tile where an enemy is standing and deals <color=#00F6FF>40%</color> damage 20 times to the enemy. Reselects a target after eliminating the current enemy. The Active Skill deals damage 1 additional time for every Yellow tile within <color=#00F6FF>1 surrounding cluster</color> of your current location.",
  str_skill_desc_306105 = "Selects 1 tile where an enemy is standing and deals <color=#00F6FF>40%</color> damage 20 times to the enemy. Reselects a target after eliminating the current enemy. The Active Skill deals damage 1 additional time for every Yellow tile within <color=#00F6FF>2 surrounding clusters</color> of your current location.",
  str_skill_desc_330105 = "Selects 1 tile where an enemy is standing and deals <color=#00F6FF>40%</color> damage 20 times to the enemy, with the damage factor increasing by <color=#00F6FF>0.8%</color> each time. Reselects a target after eliminating the current enemy. The final target of your attack has their DEF reduced by 10% for 1 round. The Active Skill deals damage 1 additional time for every Yellow tile within <color=#00F6FF>1 surrounding cluster</color> of your current location.",
  str_skill_desc_336105 = "Selects 1 tile where an enemy is standing and deals <color=#00F6FF>40%</color> damage 20 times to the enemy, with the damage factor increasing by <color=#00F6FF>0.8%</color> each time. Reselects a target after eliminating the current enemy. The final target of your attack has their DEF reduced by 10% for 1 round. The Active Skill deals damage 1 additional time for every Yellow tile within <color=#00F6FF>2 surrounding clusters</color> of your current location.",
  str_skill_desc_330109 = "Costs <color=#00F6FF>10</color> Vis and clears the remaining Vis to deal <color=#00F6FF><color=#00F6FF>150%</color></color> damage to all enemies in a chosen direction and their adjacent tiles. The final damage increases by <color=#00F6FF>8%</color> for every 1 Vis cleared.",
  str_skill_desc_330110 = "Costs <color=#00F6FF>10</color> Vis and clears the remaining Vis to deal <color=#00F6FF>150%</color> damage to all enemies. The damage increases by <color=#00F6FF>15%</color> for every 1 Vis cleared.",
  str_skill_desc_336110 = "Costs <color=#00F6FF>10</color> Vis and clears the remaining Vis to deal <color=#00F6FF>150%</color> damage to all enemies. For every 1 Vis cleared, the damage increases by <color=#00F6FF>15%</color> and ignores <color=#00F6FF>1%</color> defense.",
  str_skill_desc_330107 = "Costs <color=#00F6FF>10</color> Vis to enter an augmented state in this round: Normal attacks can be launched diagonally, and increases normal attack and chain combo damage by <color=#00F6FF>20%</color> (can be stacked when used more than once).",
  str_skill_desc_333107 = "Costs <color=#00F6FF>10</color> Vis to enter an augmented state in this round: Normal attacks can be launched diagonally, and increases normal attack and chain combo damage by <color=#00F6FF>20%</color> (can be stacked when used more than once). Gains 2 Vis for every 1 enemy killed while in an augmented state.",
  str_skill_desc_336107 = "Costs <color=#00F6FF>10</color> Vis to enter an augmented state in this round: Normal attacks can be launched diagonally, and increases normal attack and chain combo damage by <color=#00F6FF>20%</color> (can be stacked when used more than once). Gains 2 Vis for every 1 enemy killed while in an augmented state.",
  str_skill_desc_330108 = "Costs <color=#00F6FF>10</color> Vis to deal <color=#00F6FF>{1}%</color> damage to 1 selected tile, and deals 50% <link=\"30015\"><#FFAE07><u>Splash</u></color></link> damage to <color=#00F6FF>4 tiles in a cross shape</color> around it. Can be cast multiple times each round.",
  str_skill_desc_333108 = "Costs <color=#00F6FF>10</color> Vis to deal <color=#00F6FF>{1}%</color> damage to 1 selected tile, and deals 50% <link=\"30015\"><#FFAE07><u>Splash</u></color></link> damage to <color=#00F6FF>4 tiles in a cross shape</color> around it. Can be cast multiple times each round.",
  str_skill_desc_336108 = "Costs <color=#00F6FF>10</color> Vis to deal <color=#00F6FF>{1}%</color> damage to 1 selected tile, and deals 50% <link=\"30015\"><#FFAE07><u>Splash</u></color></link> damage to <color=#00F6FF>4 tiles in a cross shape</color> around it. Every cast increases basic ATK by <color=#00F6FF>3%</color>. Can be cast multiple times each round.",
  str_skill_desc_300112 = "Teleports to any tile within <color=#00F6FF>3 surrounding clusters</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> of the target location, and resets all </color>non-Red<color=#00F6FF> tiles within the area of attack.",
  str_skill_desc_301112 = "Teleports to any tile, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> of the target location, and resets all </color>non-red<color=#00F6FF> tiles within the area of attack.",
  str_skill_desc_303112 = "Teleports to any tile, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> of the target location, and resets all </color>non-Red<color=#00F6FF> tiles within the area of attack. Converts 1 or more enemy tiles to Red tiles.",
  str_skill_desc_320112 = "Teleports to any tile within <color=#00F6FF>3 surrounding clusters</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> of the target location, and resets all </color>non-Red<color=#00F6FF> tiles within the area of attack.",
  str_skill_desc_321112 = "Teleports to any tile, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> of the target location, and resets all </color>non-red<color=#00F6FF> tiles within the area of attack.",
  str_skill_desc_323112 = "Teleports to any tile, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> of the target location, and resets all </color>non-Red<color=#00F6FF> tiles within the area of attack. Converts 1 or more enemy tiles to Red tiles.",
  str_skill_desc_330112 = "Teleports to any tile within <color=#00F6FF>3 surrounding clusters</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> of the target location, and resets all </color>non-Red<color=#00F6FF> tiles within the area of attack. After triggering <color=#00F6FF>Manticore's Kiss</color>, the target's Manticore's Mark stacks are cleared.",
  str_skill_desc_331112 = "Teleports to any tile, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> of the target location, and resets all </color>non-Red<color=#00F6FF> tiles within the area of attack. After triggering <color=#00F6FF>Manticore's Kiss</color>, the target's Manticore's Mark stacks are cleared.",
  str_skill_desc_333112 = "Teleports to any tile, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> of the target location, and reset all </color>non-Red<color=#00F6FF> tiles within the area of attack. After triggering <color=#00F6FF>Manticore's Kiss</color>, the target's Manticore's Marks are cleared. At least 1 enemy tile will be converted to Red.",
  str_skill_desc_300113 = "Selects 1 of <color=#00F6FF>4</color> directions around the unit and displaces all non-boss enemies who occupy a single tile in the selected direction, while dealing <color=#00F6FF>{1}%</color> damage to all enemies on the board.",
  str_skill_desc_305113 = "Selects 1 of <color=#00F6FF>4</color> directions around the unit and displaces all non-boss enemies who occupy a single tile in the selected direction, while dealing <color=#00F6FF>{1}%</color> damage to all enemies on the board.",
  str_skill_desc_330113 = "Selects 1 of <color=#00F6FF>4</color> directions around the unit and displaces all non-boss enemies who occupy a single tile in the selected direction, while dealing <color=#00F6FF>{1}%</color> damage to all enemies on the board. If the number of enemies hit is 2 or less, this skill will be cast 1 more time this round.",
  str_skill_desc_335113 = "Selects 1 of <color=#00F6FF>4</color> directions around the unit and displaces all non-boss enemies who occupy a single tile in the selected direction, while dealing <color=#00F6FF>{1}%</color> damage to all enemies on the board. If the number of enemies hit is 2 or less, this skill will be cast 1 more time this round.",
  str_skill_desc_300114 = "Teleports to any location in an L-shape from the current position (1 tile horizontally and 2 tiles vertically or 1 tile vertically and 2 tiles horizontally), dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> of the target location.",
  str_skill_desc_302114 = "Teleports to any location in an L-shape from the current position (1 tile horizontally and 2 tiles vertically or 1 tile vertically and 2 tiles horizontally), dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> of the target location. After using an Active Skill, Chain Combos are effective against all enemies within range in this round.",
  str_skill_desc_305114 = "Teleports to any location in an L-shape from the current position (1 tile horizontally and 2 tiles vertically or 1 tile vertically and 2 tiles horizontally), dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> of the target location. After using an Active Skill, Chain Combos are effective against all enemies within range in this round. When hitting only 1 enemy, this skill can be cast 1 more time this round.",
  str_skill_desc_320114 = "Teleports to any location in an L-shape from the current position (1 tile horizontally and 2 tiles vertically or 1 tile vertically and 2 tiles horizontally), dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> of the target location. After using an Active Skill, Chain Combo range increases by 1 cluster this round.",
  str_skill_desc_322114 = "Teleports to any location in an L-shape from the current position (1 tile horizontally and 2 tiles vertically or 1 tile vertically and 2 tiles horizontally), dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> of the target location. After using an Active Skill, Chain Combo range increases by 1 cluster this round, and Chain Combos are effective against all enemies within range.",
  str_skill_desc_325114 = "Teleports to any location in an L-shape from the current position (1 tile horizontally and 2 tiles vertically or 1 tile vertically and 2 tiles horizontally), dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> of the target location. After using an Active Skill, Chain Combo range increases by 1 cluster this round, and Chain Combos are effective against all enemies within range. When hitting only 1 enemy, this skill can be cast 1 more time this round.",
  str_skill_desc_300127 = "Selects 1 tile (including Abyssal Tiles) and places 1 Paper Crane on it while converting this tile to Green. The Paper Crane will disappear after teammates pass through.",
  str_skill_desc_304127 = "Selects 1 tile (including Abyssal Tiles) and places 1 Paper Crane on it while converting this tile to a Green <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. When teammates pass through the Paper Crane, the Paper Crane will disappear.",
  str_skill_desc_320127 = "Selects 1 tile (including Abyssal Tiles) and places 1 Paper Crane on it while converting this tile to Green. The Paper Crane will disappear after teammates pass through, and converts non-Abyssal tile below it to Green.",
  str_skill_desc_324127 = "Selects 1 tile (including Abyssal Tiles) and places 1 Paper Crane on it while converting this tile to a Green <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>. The Paper Crane will disappear after teammates pass through, and converts non-Abyssal tile below it to Green.",
  str_skill_desc_300117 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location.",
  str_skill_desc_303117 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location.",
  str_skill_desc_306117 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. If the Active Skill was ready in the last round, the teleport range in this round becomes <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_3061171 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. If the Active Skill was ready in the last round, the teleport range in this round becomes <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_320117 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. Deals 1.5× damage to the outer cluster.",
  str_skill_desc_323117 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. Deals 1.5× damage to the outer cluster.",
  str_skill_desc_326117 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. Deals 1.5× damage to the outer cluster. If the Active Skill was ready in the last round, the teleport range in this round becomes <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_3261171 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. Deals 1.5× damage to the outer cluster. If the Active Skill was ready in the last round, the teleport range in this round becomes <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_330117 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. Deals 1.5× damage to the outer cluster.",
  str_skill_desc_333117 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. Deals 1.5× damage to the outer cluster.",
  str_skill_desc_336117 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. Deals 1.5× damage to the outer cluster. If the Active Skill was ready in the last round, the teleport range in this round becomes <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_3361171 = "Teleports to any tile within <color=#00F6FF>12 surrounding tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>20 surrounding tiles</color> of the target location. Deals 1.5× damage to the outer cluster. If the Active Skill was ready in the last round, the teleport range in this round becomes <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_300119 = "Selects 1 of <color=#00F6FF>4</color> directions around the unit and launches 3 thunder waves forward in a 3-column range, dealing <color=#00F6FF>250%</color> damage. After each thunder wave hits a target, subsequent thunder wave damage is reduced by <color=#00F6FF>40%</color>. Can hit up to <color=#00F6FF>3</color> times.",
  str_skill_desc_306119 = "Selects 1 of <color=#00F6FF>4</color> directions around the unit and launches 3 thunder waves forward in a 3-column range, dealing <color=#00F6FF>250%</color> damage. After each thunder wave hits a target, subsequent thunder wave damage is reduced by <color=#00F6FF>20%</color>. Can hit up to <color=#00F6FF>5</color> times.",
  str_skill_desc_300122 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>17 tiles in a radial shape</color> centered on 1 selected tile.",
  str_skill_desc_305122 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>17 tiles in a radial shape</color> centered on 1 selected tile. Clears <color=#00F6FF>broken tile</color> effects from the affected tiles.",
  str_skill_desc_320122 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>17 tiles in a radial shape</color> centered on 1 selected tile. Damage dealt to the selected tile ignores DEF.",
  str_skill_desc_325122 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>17 tiles in a radial shape</color> centered on 1 selected tile. Damage dealt to the selected tile ignores DEF. Clears <color=#00F6FF>broken tile</color> effects from the affected tiles.",
  str_skill_desc_330122 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>17 tiles in a radial shape</color> centered on 1 selected tile. Damage dealt to the selected tile ignores DEF. When Blessing reaches 10 stacks, active skill range becomes the <color=#00F6FF>maximum radial-shaped span</color>.",
  str_skill_desc_3301221 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>17 tiles in a radial shape</color> centered on 1 selected tile. Damage dealt to the selected tile ignores DEF. When Blessing reaches 10 stacks, active skill range becomes the <color=#00F6FF>maximum radial-shaped span</color>.",
  str_skill_desc_335122 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>17 tiles in a radial shape</color> centered on 1 selected tile. Damage dealt to the selected tile ignores DEF. Clears <color=#00F6FF>broken tile</color> effects from tiles in this span. When Blessing reaches 10 stacks, active skill range becomes the <color=#00F6FF>maximum radial-shaped span</color>.",
  str_skill_desc_300121 = "Select 1 tile, then with this tile as the center, select 1 direction in which to extend a vine that creeps to the edge of the battlefield and deals <color=#00F6FF>360%</color> damage within this range, while converting the front <color=#00F6FF>2</color> tiles to <link=\"20001\"><#FFAE07><u>Enhanced Tiles</u></color></link>. For each 1 tile the vine extends across, damage increases by <color=#00F6FF>10%</color>.",
  str_skill_desc_306121 = "Select 1 tile, then with this tile as the center, select 1 direction in which to extend a vine that creeps to the edge of the battlefield and deals <color=#00F6FF>360%</color> damage within this range, while converting the front <color=#00F6FF>3</color> tiles to <link=\"20001\"><#FFAE07><u>Enhanced Tiles</u></color></link>. For each 1 tile the vine extends across, damage increases by <color=#00F6FF>15%</color>.",
  str_skill_desc_320121 = "Select 1 tile, then with this tile as the center, select 1 direction in which to extend a vine that creeps to the edge of the battlefield and deals <color=#00F6FF>360%</color> damage within this range, while converting the front <color=#00F6FF>2</color> tiles to <link=\"20001\"><#FFAE07><u>Enhanced Tiles</u></color></link>. Vines extend <color=#00F6FF>3</color> tiles in a cross-shape after dealing damage. This extension effect can trigger only 1 time for each enemy hit. For each 1 tile the vine extends across, damage increases by <color=#00F6FF>10%</color>.",
  str_skill_desc_326121 = "Select 1 tile, then with this tile as the center, select 1 direction in which to extend a vine that creeps to the edge of the battlefield and deals <color=#00F6FF>360%</color> damage within this range, while converting the front <color=#00F6FF>3</color> tiles to <link=\"20001\"><#FFAE07><u>Enhanced Tiles</u></color></link>. Vines extend <color=#00F6FF>3</color> tiles in a cross-shape after dealing damage. This extension effect can trigger only 1 time for each enemy hit. For each 1 tile the vine extends across, damage increases by <color=#00F6FF>15%</color>.",
  str_skill_desc_300065 = "Teleports to any tile within <color=#00F6FF>2 surrounding clusters</color> or any Blue tile on the battlefield.",
  str_skill_desc_330065 = "Teleports to any tile within <color=#00F6FF>2 surrounding clusters</color> or any Blue tile on the battlefield. Can cast 1 more time after entering Aurora Time.",
  str_skill_desc_300115 = "Teleports to a selected location and <link=\"30020\"><#FFAE07><u>purifies</u></color></link> tiles within <color=#00F6FF>2 surrounding clusters</color> and additionally other tiles at random. <color=#00F6FF>3</color> tiles within the purification range are converted to <link=\"20001\"><#FFAE07><u>Enhanced Tiles</u></color></link>.",
  str_skill_desc_305115 = "Teleports to a selected location and <link=\"30020\"><#FFAE07><u>purifies</u></color></link> tiles within <color=#00F6FF>2 surrounding clusters</color> and additionally other tiles at random. <color=#00F6FF>4</color> tiles within the purification range are converted to <link=\"20001\"><#FFAE07><u>Enhanced Tiles</u></color></link>.",
  str_skill_desc_320115 = "Teleports to a selected location and <link=\"30020\"><#FFAE07><u>purifies</u></color></link> tiles within <color=#00F6FF>3 surrounding clusters</color> and additionally other tiles at random. <color=#00F6FF>4</color> tiles within the purification range are converted to <link=\"20001\"><#FFAE07><u>Enhanced Tiles</u></color></link>.",
  str_skill_desc_325115 = "Teleports to a selected location and <link=\"30020\"><#FFAE07><u>purifies</u></color></link> tiles within <color=#00F6FF>3 surrounding clusters</color> and additionally other tiles at random. <color=#00F6FF>5</color> tiles within the purification range are converted to <link=\"20001\"><#FFAE07><u>Enhanced Tiles</u></color></link>.",
  str_skill_desc_300126 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected traversable tile.",
  str_skill_desc_303126 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected traversable tile.",
  str_skill_desc_306126 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected traversable tile. Can cast 1 more time after entering Aurora Time (can trigger 1 time per wave).",
  str_skill_desc_310126 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected traversable tile.",
  str_skill_desc_313126 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected traversable tile.",
  str_skill_desc_316126 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected traversable tile. Can cast 1 more time after entering Aurora Time (can trigger 1 time per wave).",
  str_skill_desc_320126 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected traversable tile.",
  str_skill_desc_323126 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected traversable tile.",
  str_skill_desc_326126 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected traversable tile. Can cast 1 more time after entering Aurora Time (can trigger 1 time per wave).",
  str_skill_desc_300129 = "Consumes all <link=\"30021\"><#FFAE07><u>Scions</u></color></link> to deal damage to 1 enemy. Each <link=\"30021\"><#FFAE07><u>Scion</u></color></link> deals <color=#00F6FF>40%</color> damage.",
  str_skill_desc_303129 = "Consumes all <link=\"30022\"><#FFAE07><u>Scions</u></color></link> to deal damage to 1 enemy. Each <link=\"30022\"><#FFAE07><u>Scion</u></color></link> deals <color=#00F6FF>50%</color> damage.",
  str_skill_desc_306129 = "Consumes all <link=\"30023\"><#FFAE07><u>Scions</u></color></link> to deal damage to 1 enemy. Each <link=\"30023\"><#FFAE07><u>Scion</u></color></link> deals <color=#00F6FF>50%</color> damage.",
  str_skill_desc_300055 = "Attacks in any 1 selected direction, dealing <color=#00F6FF>160%</color> damage to all enemies in this direction and knocking them back.",
  str_skill_desc_302055 = "Attacks in any 1 selected direction, dealing <color=#00F6FF>160%</color> damage to all enemies in this direction and knocking them back. If your Active Skill was ready in the previous round, the final damage to this round increases by <color=#00F6FF>60%</color>.",
  str_skill_desc_3020551 = "Attacks in any 1 selected direction, dealing <color=#00F6FF>160%</color> damage to all enemies in this direction and knocking them back. If your Active Skill was ready in the previous round, the final damage to this round increases by <color=#00F6FF>60%</color>.",
  str_skill_desc_305055 = "Attacks in any 1 selected direction, dealing <color=#00F6FF>160%</color> damage to all enemies in this direction and knocking them back. For every <color=#00F6FF>1</color> tile enemies are knocked back, final damage increases by <color=#00F6FF>5%</color>. If your Active Skill was ready in the previous round, the final damage to this round increases by <color=#00F6FF>60%</color>.",
  str_skill_desc_3050551 = "Attacks in any 1 selected direction, dealing <color=#00F6FF>160%</color> damage to all enemies in this direction and knocking them back. For every <color=#00F6FF>1</color> tile enemies are knocked back, final damage increases by <color=#00F6FF>5%</color>. If your Active Skill was ready in the previous round, the final damage to this round increases by <color=#00F6FF>60%</color>.",
  str_skill_desc_300120 = "Teleports to a selected location. Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 column</color> and knocks enemies back. Converts tiles in the area of attack to Green.",
  str_skill_desc_16012001 = "Deals a small amount of damage in 1 column and knocks the enemies back. Converts tiles within the area of attack to Green.",
  str_skill_desc_16012002 = "Knocks back enemies in a column while converting tiles within attacking range to Green.",
  str_skill_desc_303120 = "Teleports to a selected location. Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 column</color> and knocks enemies back. Converts tiles in the area of attack to Green.",
  str_skill_desc_300123 = "Deals <color=#00F6FF>{1}%</color> damage to 1 enemy within <color=#00F6FF>1 surrounding cluster</color>. When attacking the same target for the first time, <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> is inflicted for 1 round. When attacking a second time, <color=#00F6FF><color=#00F6FF>Stun</color></color> is inflicted for 1 round.",
  str_skill_desc_302123 = "Deals <color=#00F6FF>{1}%</color> damage to 1 enemy within <color=#00F6FF>1 surrounding cluster</color>. When attacking the same target for the first time, <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> is inflicted for 1 round. When attacking a second time, <color=#00F6FF>Stun</color> is inflicted for 1 round.",
  str_skill_desc_305123 = "Deals <color=#00F6FF>{1}%</color> damage to 1 enemy within <color=#00F6FF>1 surrounding cluster</color>. When attacking the same target for the first 2 times, <color=#00F6FF>Stun</color> is inflicted for 1 round each time.",
  str_skill_desc_320123 = "Deals <color=#00F6FF>{1}%</color> damage to 1 enemy within <color=#00F6FF>1 surrounding cluster</color>. When attacking the same target for the first time, <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> is inflicted for 1 round. When attacking a second time, <color=#00F6FF>Stun</color> is inflicted for 1 round. Active Skill damage increases based on the number of tiles occupied by the target.",
  str_skill_desc_322123 = "Deals <color=#00F6FF>{1}%</color> damage to 1 enemy within <color=#00F6FF>1 surrounding cluster</color>. When attacking the same target for the first time, <link=\"10004\"><#FFAE07><u>Paralyze</u></color></link> is inflicted for 1 round. When attacking a second time, <color=#00F6FF>Stun</color> is inflicted for 1 round. Active Skill damage increases based on the number of tiles occupied by the target.",
  str_skill_desc_325123 = "Deals <color=#00F6FF>{1}%</color> damage to 1 enemy within <color=#00F6FF>1 surrounding cluster</color>. When attacking the same target for the first 2 times, <color=#00F6FF>Stun</color> is inflicted for 1 round each time. Active Skill damage increases based on the number of tiles occupied by the target.",
  str_skill_desc_300015 = "Select a traversable tile on which to summon Gin and determine his direction, then throw 1 grenade in this direction. This grenade can bounce again to the farthest distance possible in Gin's selected direction. The grenade deals <color=#00F6FF>200%</color> damage to enemies it passes along the way.",
  str_skill_desc_330015 = "Select a traversable tile on which to summon Gin and determine his direction, then throw 1 grenade in this direction. This grenade can bounce again to the farthest distance possible in Gin's selected direction. The grenade deals <color=#00F6FF>200%</color> damage to enemies it passes along the way. Gin can be made to face diagonal directions.",
  str_skill_desc_300131 = "Recovers the team's HP by <color=#00F6FF>220%</color> of Novio's ATK and gains shield by <color=#00F6FF>90%</color> of Novio's HP. If there is any excess healing, deals damage to enemies within <color=#00F6FF>12 tiles in a diamond shape</color> equal to the excess recovered value regardless of defense.",
  str_skill_desc_306131 = "Recovers the team's HP by <color=#00F6FF>220%</color> of Novio's ATK and gains shield by <color=#00F6FF>120%</color> of Novio's HP. If there is any excess healing, deals damage to enemies within <color=#00F6FF>12 tiles in a diamond shape</color> equal to the excess recovered value regardless of defense.",
  str_skill_desc_320131 = "Recovers the team's HP by <color=#00F6FF>220%</color> of Novio's ATK and gains shield by <color=#00F6FF>90%</color> of Novio's HP. If there is any excess healing, deals damage to enemies within <color=#00F6FF>2 surrounding clusters</color> equal to the excess recovered value regardless of defense. Upon entering Aurora Time, shield up to MAX HP will convert to HP.",
  str_skill_desc_326131 = "Recovers the team's HP by <color=#00F6FF>220%</color> of Novio's ATK and gains shield by <color=#00F6FF>120%</color> of Novio's HP. If there is any excess healing, deals damage to enemies within <color=#00F6FF>2 surrounding clusters</color> equal to the excess recovered value regardless of defense. Upon entering Aurora Time, shield up to MAX HP will convert to HP.",
  str_skill_desc_300132 = "Deals <color=#00F6FF>{1}%</color> damage to 1 selected enemy. If the enemy is still standing at the end of the round, the HP recovered is equal to the damage inflicted.",
  str_skill_desc_302132 = "Deals <color=#00F6FF>{1}%</color> damage to 1 selected enemy. If the enemy is still standing at the end of the round, the HP recovered is equal to the damage inflicted. When it's recovered, the Active Skill cooldown is also reduced by <color=#00F6FF>1</color> round.",
  str_skill_desc_305132 = "Deals <color=#00F6FF>{1}%</color> damage to 1 selected enemy. If the enemy is still standing at the end of the round, the HP recovered is equal to the damage inflicted. When it's recovered, the Active Skill cooldown is also reduced by <color=#00F6FF>1</color> round.",
  str_skill_desc_320132 = "Deals <color=#00F6FF>{1}%</color> damage to 1 selected enemy. If enemy is still standing at the end of the round, the HP recovered is equal to the damage inflicted. Upon entering Aurora Time, enemies cannot recover HP when the round ends.",
  str_skill_desc_3201321 = "Deals <color=#00F6FF>{1}%</color> damage to 1 selected enemy. If enemy is still standing at the end of the round, the HP recovered is equal to the damage inflicted. Upon entering Aurora Time, enemies cannot recover HP when the round ends.",
  str_skill_desc_322132 = "Deal <color=#00F6FF>{1}%</color> damage to 1 selected enemy. If the enemy is still standing at the end of the round, the HP recovered is equal to the damage inflicted. When it's recovered, the Active Skill cooldown is also reduced by <color=#00F6FF>1</color> round. Upon entering Aurora Time, enemies cannot recover HP when the round ends.",
  str_skill_desc_3221321 = "Deal <color=#00F6FF>{1}%</color> damage to 1 selected enemy. If the enemy is still standing at the end of the round, the HP recovered is equal to the damage inflicted. When it's recovered, the Active Skill cooldown is also reduced by <color=#00F6FF>1</color> round. Upon entering Aurora Time, enemies cannot recover HP when the round ends.",
  str_skill_desc_325132 = "Deal <color=#00F6FF>{1}%</color> damage to 1 selected enemy. If the enemy is still standing at the end of the round, the HP recovered is equal to the damage inflicted. When it's recovered, the Active Skill cooldown is also reduced by <color=#00F6FF>1</color> round. Upon entering Aurora Time, enemies cannot recover HP when the round ends.",
  str_skill_desc_3251321 = "Deal <color=#00F6FF>{1}%</color> damage to 1 selected enemy. If the enemy is still standing at the end of the round, the HP recovered is equal to the damage inflicted. When it's recovered, the Active Skill cooldown is also reduced by <color=#00F6FF>1</color> round. Upon entering Aurora Time, enemies cannot recover HP when the round ends.",
