  str_skill_desc_302133 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color> centered on 1 selected tile and knocks back enemies.",
  str_skill_desc_300137 = "Selects 1 enemy and converts up to <color=#00F6FF>2</color> non-Blue tiles at enemy's feet into Blue.",
