  str_skill_desc_304137 = "Selects 1 enemy and converts up to <color=#00F6FF>3</color> non-Blue tiles at enemy's feet into Blue.",
  str_skill_desc_314137 = "Selects 1 enemy and converts up to <color=#00F6FF>3</color> non-Blue tiles at enemy's feet into Blue.",
  str_skill_desc_300135 = "Selects 1 out of <color=#00F6FF>4</color> directions, and then selects a direction on either side, attacking enemies within <color=#00F6FF>45 degrees</color> and dealing <color=#00F6FF>340%</color> damage in the area. The damage decreases during this sweep to a minimum of 30% of the original value.",
  str_skill_desc_302135 = "Selects 1 out of <color=#00F6FF>4</color> directions, and then selects a direction on either side, attacking enemies within <color=#00F6FF>45 degrees</color> and dealing <color=#00F6FF>340%</color> damage in the area. The damage decreases during this sweep to a minimum of 30% of the original value.",
