  str_skill_desc_320135 = "Selects 1 out of <color=#00F6FF>4</color> directions, and then selects a direction on either side, attacking enemies within <color=#00F6FF>90 degrees</color> and dealing <color=#00F6FF>340%</color> damage in the area. The damage decreases during this sweep to a minimum of 30% of the original value.",
  str_skill_desc_322135 = "Selects 1 out of <color=#00F6FF>4</color> directions, and then selects a direction on either side, attacking enemies within <color=#00F6FF>90 degrees</color> and dealing <color=#00F6FF>340%</color> damage in the area. The damage decreases during this sweep to a minimum of 30% of the original value.",
  str_skill_desc_325135 = "Selects 1 out of <color=#00F6FF>4</color> directions, and then selects a direction on either side, attacking enemies within <color=#00F6FF>90 degrees</color> and dealing <color=#00F6FF>340%</color> damage in the area. The damage decreases during this sweep to a minimum of 40% of the original value.",
  str_skill_desc_300134 = "Select a tile and deal <color=#00F6FF>{1}%</color> damage to enemies along the way and on adjacent tiles, knocking them back as far as possible.",
