  str_skill_desc_323134 = "Selects a tile and deals <color=#00F6FF>{1}%</color> damage to enemies <color=#00F6FF>along the way</color> and on <color=#00F6FF>adjacent</color> tiles, knocking them back as far as possible. Enemies <color=#00F6FF>along the way</color> will receive <color=#00F6FF>1.3×</color> damage.",
  str_skill_desc_300136 = "Deals <color=#00F6FF>{1}%</color> damage to all enemies, and inflicts <link=\"10006\"><#FFAE07><u>Slow</u></color></link> on all enemies on Green tiles for 2 rounds.",
  str_skill_desc_302136 = "Deals <color=#00F6FF>{1}%</color> damage to all enemies, and inflicts <link=\"10006\"><#FFAE07><u>Slow</u></color></link> on all enemies on Green tiles for 2 rounds.",
  str_skill_desc_320136 = "Deals <color=#00F6FF>{1}%</color> damage to all enemies, and inflicts <link=\"10006\"><#FFAE07><u>Slow</u></color></link> on all enemies on Green tiles for 2 rounds. Enemy will be inflicted with <color=#00F6FF>2 stacks</color> of Mortality Mark before Active Skill deals damage.",
  str_skill_desc_322136 = "Deals <color=#00F6FF>{1}%</color> damage to all enemies, and inflicts <link=\"10006\"><#FFAE07><u>Slow</u></color></link> on all enemies on Green tiles for 2 rounds. Enemy will be inflicted with <color=#00F6FF>2 stacks</color> of Mortality Mark before Active Skill deals damage.",
  str_skill_desc_325136 = "Deals <color=#00F6FF>{1}%</color> damage to all enemies, and inflicts <link=\"10006\"><#FFAE07><u>Slow</u></color></link> on all enemies on Green tiles for 2 rounds. Enemy will be inflicted with <color=#00F6FF>3 stacks</color> of Mortality Mark before Active Skill deals damage.",
