  str_skill_passive_desc_410058 = "If the Banner still exists at the end of the round, regenerates the team's HP by <color=#00F6FF>{1}</color> times of Amy's DEF.",
  str_skill_passive_desc_400035 = "After using this movement skill, Eho gains <color=#00F6FF>{1}</color> increased Normal Attack damage for the round.",
  str_skill_passive_desc_410035 = "After using this movement skill, Eho gains <color=#00F6FF>{1}</color> increased Normal Attack damage for the round.",
  str_skill_passive_desc_420035 = "After using this movement skill, Eho gains <color=#00F6FF>{1}</color> increased Normal Attack damage and Chain Combo damage for the round.",
  str_skill_passive_desc_410017 = "Whenever an allied Aurorian knocks back an enemy, Rabbie deals damage equal to <color=#00F6FF>{1}</color> of her ATK to that enemy (this damage ignores DEF).",
  str_skill_passive_desc_430017 = "Whenever an allied Aurorian knocks back an enemy, Rabbie deals damage equal to <color=#00F6FF>{1}</color> of her ATK to that enemy (this damage ignores DEF). Increases DEF-ignoring damage by <color=#00F6FF>10%</color> for every 1 tile the enemy has been knocked back.",
  str_skill_passive_desc_410040 = "Grants 1 stack of Stickiness Mark at the start of each round. Each stack increases the chance of Chain Combo skills inflicting <link=\"10002\"> <#FFAE07><u>Burn</u></color></link> that lasts 2 rounds by <color=#00F6FF>{1}</color>. All stacks are cleared at the start of every wave.",
  str_skill_passive_desc_420040 = "Grants 1 stack of Stickiness Mark at the start of each round. Each stack increases the chance of Chain Combo skills inflicting <link=\"10002\"> <#FFAE07><u>Burn</u></color></link> that lasts 2 rounds by <color=#00F6FF>{1}</color>. All stacks are cleared at the start of every wave.",
  str_skill_passive_desc_410041 = "Increases Blanc's ATK by <color=#00F6FF>{1}</color> when HP is full.",
  str_skill_passive_desc_420041 = "Increases Blanc's ATK by <color=#00F6FF>{1}</color> when HP is above 70%.",
  str_skill_passive_desc_430041 = "Increases Blanc's ATK by <color=#00F6FF>{1}</color> and increases other deployed Water Aurorians' ATK by <color=#00F6FF>{2}</color> of Blanc's ATK when HP is above 70%.",
  str_skill_passive_desc_410021 = "Increases Chain Combo damage by <color=#00F6FF>{1}</color> when the Active Skill is not ready.",
  str_skill_passive_desc_420021 = "Increases Chain Combo damage by <color=#00F6FF>{1}</color> and Normal Attack damage by <color=#00F6FF>{2}</color> when the Active Skill is not ready.",
  str_skill_passive_desc_410004 = "Increases the team's Max HP by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410073 = "Unleashes 1 additional Chain Combo at the beginning of the line, dealing <color=#00F6FF>{1}</color> normal damage.",
  str_skill_passive_desc_430073 = "Unleashes 1 additional Chain Combo at the beginning of the line, deals <color=#00F6FF>{1}</color> normal damage. Increases damage by <color=#00F6FF>100%</color> where the initial and actual combos overlap.",
  str_skill_passive_desc_410061 = "Gains 1 stack of Negativity Mark whenever an Active Skill is used, up to <color=#00F6FF>3</color> stacks. Each stack increases the number of Active Skill attacks by 1 and reduces the final damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420061 = "Gains 1 stack of Negativity Mark whenever an Active Skill is used, up to <color=#00F6FF>5</color> stacks. Each stack increases the number of Active Skill attacks by 1, reducing the final damage by <color=#00F6FF>{1}</color>. Each mark increases Chain Combo damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430061 = "Gains 1 stack of Negativity Mark whenever an Active Skill is used, up to <color=#00F6FF>5</color> stacks. Each stack increases the number of Active Skill attacks by 1, reducing the final damage by <color=#00F6FF>{1}</color>. Each mark increases Chain Combo damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_414061 = "Gains 1 stack of Negativity Mark whenever an Active Skill is used, up to <color=#00F6FF>3</color> stacks. Each stack increases the number of Active Skill attacks by 1 and reduces the final damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_424061 = "Gains 1 stack of Negativity Mark whenever an Active Skill is used, up to <color=#00F6FF>5</color> stacks. Each stack increases the number of Active Skill attacks by 1, reducing the final damage by <color=#00F6FF>{1}</color>. Each mark increases Chain Combo damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_434061 = "Gains 1 stack of Negativity Mark whenever an Active Skill is used, up to <color=#00F6FF>5</color> stacks. Each stack increases the number of Active Skill attacks by 1, reducing the final damage by <color=#00F6FF>{1}</color>. Each mark increases Chain Combo damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410054 = "Whenever a lantern disappears at the end of its duration, it unleashes light that illuminates <color=#00F6FF>1 surrounding cluster</color>, dealing <color=#00F6FF>{1}</color> damage and has a <color=#00F6FF>{2}</color> chance to inflict <link=\"10005\"><#FFAE07><u>Blind</u></color></link> on enemies for 1 round.",
  str_skill_passive_desc_430054 = "While a lantern exists, it unleashes light that illuminates <color=#00F6FF>1 surrounding cluster</color> at the end of each round, dealing <color=#00F6FF>{1}</color> damage and has a <color=#00F6FF>{2}</color> chance to inflict <link=\"10005\"><#FFAE07><u>Blind</u></color></link> on enemies for 1 round.",
  str_skill_passive_desc_410016 = "Gains 1 stack of charge whenever passing through a Yellow tile, up to 99 stacks. Each stack increases Active Skill damage by <color=#00F6FF>{1}</color>. Using the Active Skill clears all stacks.",
  str_skill_passive_desc_410046 = "Each stack of Laughter Mark increases Thunder Aurorians' Normal Attack damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430046 = "Killing enemies with Laughter Mark inflicts <color=#00F6FF>1</color> additional stack to all remaining enemies. Each mark increases Thunder Aurorians' Normal Attack damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410044 = "Whenever Chain Combos deal damage to all enemies, Thunder Aurorians gain <color=#00F6FF>{1}</color> of Vivian's ATK as an attack bonus for the round.",
  str_skill_passive_desc_430044 = "Whenever Chain Combos deal damage to all enemies, Water, Thunder, and Illumina Aurorians gain <color=#00F6FF>{1}</color> of Vivian's ATK as an ATK bonus for 2 rounds.",
  str_skill_passive_desc_410048 = "Increases Dayna's damage against enemies occupying a Yellow tile by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430048 = "Increases Dayna's damage against enemies occupying a Yellow tile by <color=#00F6FF>{1}</color>. Also grants Thunder Aurorian teammates <color=#00F6FF>50%</color> of that bonus.",
  str_skill_passive_desc_410009 = "At the start of each round, there is a <color=#00F6FF>{1}</color> chance to inflict <link=\"10003\"><#FFAE07><u>Fright</u></color></link> on enemies for 1 round.",
  str_skill_passive_desc_420009 = "At the start of each round, enemies have a(n) <color=#00F6FF>{1}</color> chance of being afflicted with <link=\"10003\"><#FFAE07><u>Fright</u></color></link> for 1 round. Triggers an explosion whenever killing a <link=\"10003\"><#FFAE07><u>Frightened</u></color></link> enemy, dealing <color=#00F6FF>10%</color> Max HP as damage to enemies within 1 surrounding cluster.",
  str_skill_passive_desc_410012 = "Each Chain Combo hit grants 1 stack of Judgment Mark. Each stack increases DEF by <color=#00F6FF>{1}</color>. The Mark disappears at the end of the round.",
  str_skill_passive_desc_420012 = "Each Chain Combo hit grants 1 stack of Judgment Mark (2, if Active Skill). Each stack increases DEF by <color=#00F6FF>{1}</color>. Retains 50% of the stacks at the end of the round.",
  str_skill_passive_desc_430012 = "Each Chain Combo hit grants 1 stack of Judgment Mark (Active Skill hit grants 2 stacks). Each stack increases ATK by <color=#00F6FF>3%</color> and DEF by <color=#00F6FF>{1}</color>. Retains 50% of the stacks at the end of the round.",
  str_skill_passive_desc_410013 = "When the shield disappears, converts <color=#00F6FF>{1}</color> of the remaining Shield to HP.",
  str_skill_passive_desc_430013 = "When the shield disappears, converts <color=#00F6FF>{1}</color> of the remaining Shield to HP. Increases Noah's DEF by <color=#00F6FF>50%</color> if a Shield already exists.",
  str_skill_passive_desc_410018 = "Chain Combos deal up to <color=#00F6FF>{1}</color> increased damage. The closer the enemies are, the higher the damage. A distance beyond 3 tiles offers no damage bonuses.",
  str_skill_passive_desc_420018 = "The closer the enemies are, the higher the damage of active skills and chain combos (up to <color=#00F6FF>{1}</color>). A distance beyond 3 clusters offers no damage bonuses.",
  str_skill_passive_desc_430018 = "Increases ATK by <color=#00F6FF>5%</color> for every enemy within <color=#00F6FF>1 surrounding cluster</color>. The closer the enemies are, the higher the damage of Active Skills and Chain Combos (up to <color=#00F6FF>{1}</color>). A distance beyond 3 clusters offers no damage bonuses.",
  str_skill_passive_desc_410033 = "Vice gains 1 stack of Locking Mark whenever she deals damage. Each stack increases damage by <color=#00F6FF>{1}</color>. All stacks are cleared at the end of the round.",
  str_skill_passive_desc_430033 = "Vice gains 1 stack of Locking Mark whenever she deals damage. Each stack increases damage by <color=#00F6FF>{1}</color> and Chain Combo damage by <color=#00F6FF>{2}</color>. All stacks are cleared at the end of the round.",
  str_skill_passive_desc_410036 = "Grants 1 Wolf Mark at the beginning of every round. When attacked for the first time, consumes 1 Mark to deal damage equal to <color=#00F6FF>{1}</color> of Hydrad's ATK back to the target (this damage ignores DEF). All Wolf Marks are cleared at the end of the round.",
  str_skill_passive_desc_420036 = "Grants 1 Wolf Mark at the beginning of every round. When attacked, consumes 1 Mark to deal damage equal to <color=#00F6FF>{1}</color> of Hydrad's ATK back to the target (this damage ignores DEF). Wolf Marks are <color=#00F6FF>not cleared</color> at the end of the round.",
  str_skill_passive_desc_410010 = "When triggering <link=\"30010\"><#FFAE07><u>Aurora Time</u></color></link>, the team's HP immediately recovers by <color=#00F6FF>{1}</color> of Louise's Max HP and increases her DEF by <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_420010 = "When triggering <link=\"30010\"><#FFAE07><u>Aurora Time</u></color></link>, immediately recovers the team's HP by <color=#00F6FF>{1}</color> of Louise's Max HP and increases her DEF by <color=#00F6FF>50%</color> for 2 rounds.",
  str_skill_passive_desc_410014 = "Increases Schwartz's DEF by <color=#00F6FF>{1}</color> for every Thunder or Lumopolis Aurorian deployed.",
  str_skill_passive_desc_430014 = "Increases Schwartz's DEF by {1} for every Thunder or Lumopolis Aurorian deployed (also increases ATK for an amount equal to DEF granted).",
  str_skill_passive_desc_410078 = "Increases Robyn's damage against green-tile occupying enemies by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430078 = "Increases Robyn's damage against enemies occupying a Green tile by <color=#00F6FF>{1}</color>. Also grants Forest Aurorian teammates <color=#00F6FF>50%</color> of that bonus.",
  str_skill_passive_desc_410076 = "After using a Chain Combo, touches <color=#00F6FF>4 adjacent enemies in a cross shape</color> and inflicts <link=\"10003\"><#FFAE07><u>Fright</u></color></link> for 1 round if the enemy's HP is below <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420076 = "After using a Chain Combo, inflicts <link=\"10003\"><#FFAE07><u>Fright</u></color></link> on 1 enemy with the lowest HP (below <color=#00F6FF>{1}</color> HP) within <color=#00F6FF>4 tiles of it in a cross shape</color> for 1 round. Killing a <link=\"10003\"><#FFAE07><u>Frightened</u></color></link> enemy has a <color=#00F6FF>50%</color> chance to inflict <link=\"10003\"><#FFAE07><u>Fright</u></color></link> on enemies within <color=#00F6FF>4 tiles of it in a cross shape</color>.",
  str_skill_passive_desc_410042 = "Normal attacks can now fire diagonally and deal <color=#00F6FF>{1}</color> damage.",
  str_skill_passive_desc_420042 = "Normal attacks can now fire diagonally to deal <color=#00F6FF>{1}</color> damage and inflict 1 Firepower Mark that lasts 2 rounds. Barton's normal attack deals an additional <color=#00F6FF>10%</color> damage to enemies with the mark.",
  str_skill_passive_desc_430042 = "Normal attacks can now fire diagonally to deal <color=#00F6FF>{1}</color> damage and inflict 1 Firepower Mark that lasts 2 rounds. Barton's attack deals an additional <color=#00F6FF>10%</color> <color=#00F6FF>damage</color> to enemies with the mark.",
  str_skill_passive_desc_410001 = "Grants Mirror Mark at the start of the battle. While the Mark exists, Nikinis gains <color=#00F6FF>{1}</color> increased DEF. The Mark disappears once Nikinis loses HP. The Mirror Mark can be refreshed by <color=#00F6FF>using an Active Skill</color>.",
  str_skill_passive_desc_420001 = "Grants Mirror Mark at the start of the battle. While the Mark exists, Nikinis gains <color=#00F6FF>{1}</color> increased DEF. The Mark disappears once Nikinis loses HP. The Mirror Mark can be refreshed by <color=#00F6FF>using an Active Skill or entering Aurora Time</color>.",
  str_skill_passive_desc_410011 = "Normal attacks apply 1 stack of Dragontooth Mark, up to <color=#00F6FF>4</color> stacks. Each stack increases Sharona's final Chain Combo damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430011 = "Normal attacks apply 1 stack of Dragontooth Mark, up to <color=#00F6FF>6</color> stacks. Each stack increases Sharona's <color=#00F6FF>Active Skill damage</color> and final Chain Combo damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_440011 = "Normal attacks apply 1 stack of Dragontooth Mark, up to <color=#00F6FF>7</color> stacks. Each stack increases Sharona's <color=#00F6FF>Active Skill</color> and Chain Combo final damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410019 = "Victoria regenerates <color=#00F6FF>{1}</color> Max HP per stack of <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> whenever her Chain Combo hits an enemy afflicted with <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link>.",
  str_skill_passive_desc_420019 = "Victoria regenerates <color=#00F6FF>{1}</color> Max HP per stack of <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> whenever her Chain Combo hits an enemy afflicted with <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link>.",
  str_skill_passive_desc_430019 = "Victoria regenerates HP equal to <color=#00F6FF>{1}</color> of her Max HP per stack of <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> whenever she hits an enemy afflicted with <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> using a Chain Combo. This recovery effect is increased by <color=#00F6FF>50%</color> if the enemy's HP percentage is higher than the team's.",
  str_skill_passive_desc_410023 = "Gains 1 stack of Shiver Mark when using a Chain Combo, up to <color=#00F6FF>5</color> stacks. Each stack increases Active Skill damage by <color=#00F6FF>{1}</color>. Using an Active Skill inflicts <link=\"10003\"><#FFAE07><u>Frighten</u></color></link> on a number of enemies equivalent to the number of stacks for <color=#00F6FF>1</color> round. Activating the Active Skill <color=#00F6FF>does not clear stacks</color>.",
  str_skill_passive_desc_430023 = "Gains 1 stack of Shiver Mark when using a Chain Combo, up to <color=#00F6FF>5</color> stacks. Each stack increases Active Skill damage by <color=#00F6FF>{1}</color>. Using an Active Skill inflicts <link=\"10003\"><#FFAE07><u>Frighten</u></color></link> on a number of enemies equivalent to the number of stacks for <color=#00F6FF>1</color> round. Activating the Active Skill <color=#00F6FF>does not clear stacks</color>. If she has 5 stacks already before using a Chain Combo, it will deal additional damage to the closest enemy.",
  str_skill_passive_desc_410002 = "Hiiro enters Duel stance at the start of the round. The next normal attack deals <color=#00F6FF>{1}</color> damage to the enemy and <color=#00F6FF>{2}</color> damage to enemies in <color=#00F6FF>4 tiles in a cross shape</color> around.",
  str_skill_passive_desc_420002 = "Hiiro enters Duel stance at the start of the round or whenever passing through an <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link>. The next normal attack deals <color=#00F6FF>{1}</color> damage to the enemy and <color=#00F6FF>{2}</color> damage to enemies in <color=#00F6FF>4 tiles in a cross shape</color> around.",
  str_skill_passive_desc_430002 = "Hiiro enters Duel stance at the start of the round or whenever passing through an <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link>. The next normal attack deals <color=#00F6FF>{1}</color> damage to the enemy and <color=#00F6FF>{2}</color> damage to enemies in <color=#00F6FF>4 tiles in a cross shape</color> around. ATK is increased by <color=#00F6FF>4%</color> in this round per use of One with the Duel, up to a maximum of <color=#00F6FF>20%</color>.",
  str_skill_passive_desc_410005 = "Mia gains 1 stack of Soul upon killing an enemy with her Active Skill, up to 5 stacks. Each stack unleashes a Blast that deals <color=#00F6FF>{1}</color> ATK damage.",
  str_skill_passive_desc_420005 = "Mia gains 1 stack of Soul upon killing an enemy with her Active Skill, up to 5 stacks. Each stack unleashes a Soul Blast that deals <color=#00F6FF>{1}</color> ATK damage and increases Mia's Normal Attack by <color=#00F6FF>3%</color> and Chain Combo damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430005 = "Mia gains 1 stack of Soul for every enemy defeated by <color=#00F6FF>Aurorians</color> on the field with their Active Skills, up to <color=#00F6FF>7</color> stacks. Each stack unleashes a blast that deals <color=#00F6FF>{1}</color> ATK damage to a single target, additionally increasing Mia's Normal Attack by <color=#00F6FF>3%</color>, and Chain Combo damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410006 = "Carleen gains +<color=#00F6FF>{1}</color> basic ATK for every 1 Water tile she moves into or over for the round (up to <color=#00F6FF>{2}</color>).",
  str_skill_passive_desc_420006 = "Carleen gains +<color=#00F6FF>{1}</color> basic ATK for every 1 Blue tile she moves into or over for the round (up to <color=#00F6FF>{2}</color>). The effects double after using an Active Skill.",
  str_skill_passive_desc_430006 = "Carleen gains +<color=#00F6FF>{1}</color> ATK per every 1 Water tile she moves into or over for the round (up to <color=#00F6FF>{2}</color>). The effects double for an Active Skill. Her normal attacks gain Pierce on a Water tile and deal <color=#00F6FF>40%</color> damage to target 1 tile behind the enemy.",
  str_skill_passive_desc_410025 = "Adds DEF-ignoring damage equal to <color=#00F6FF>{1}</color> of ATK to normal attacks.",
  str_skill_passive_desc_430025 = "Normal attacks <color=#00F6FF>can now attack diagonally</color>. Adds DEF-ignoring damage equal to <color=#00F6FF>{1}</color> of ATK to normal attacks.",
  str_skill_passive_desc_410026 = "Each stack of <link=\"10002\"><#FFAE07><u>Burn</u></color></link> increases Fire Aurorians' damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430026 = "At the start of each round, applies 1 stack of <link=\"10002\"><#FFAE07><u>Burn</u></color></link> on enemies occupying a Red tile for 2 rounds. Each stack of <link=\"10002\"><#FFAE07><u>Burn</u></color></link> increases Fire Aurorians' damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410028 = "Each Blue tile generated on the map recovers the team's HP by <color=#00F6FF>{1}</color> of Raphael's Max HP.",
  str_skill_passive_desc_420028 = "Each Blue tile generated on the map recovers the team's HP by <color=#00F6FF>{1}</color> of Raphael's HP. The lower the team's HP, the higher the healing effectiveness, up to an additional <color=#00F6FF>100% bonus</color>.",
  str_skill_passive_desc_410029 = "At least 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> will be generated per <color=#00F6FF>{1}</color> Green tiles passed through in this round.",
  str_skill_passive_desc_430029 = "During this round, at least 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> will be generated per <color=#00F6FF>{1}</color> Green tiles passed through in this round, and Green tiles will be enhanced first.",
  str_skill_passive_desc_410038 = "Grants 1 Magnetic Storm per 3 rounds. The next Chain Combo deals <color=#00F6FF>{1}</color> damage to 1 additional enemy within the area of attack and inflicts <link=\"10004\"><#FFAE07><u>Paralysis</u></color></link> for 1 round.",
  str_skill_passive_desc_420038 = "Grants 1 Magnetic Storm per 3 rounds. The next Chain Combo deals an additional <color=#00F6FF>{1}</color> damage to 1 enemy within the area of attack and inflicts <link=\"10004\"><#FFAE07><u>Paralysis</u></color></link> for 1 round. There is a <color=#00F6FF>50%</color> chance to attack another enemy.",
  str_skill_passive_desc_430038 = "Grants 1 Magnetic Storm per 3 rounds at the start of the battle. The next Chain Combo deals an additional <color=#00F6FF>{1}</color> damage to 1 enemy within the area of attack and inflicts <link=\"10004\"><#FFAE07><u>Paralysis</u></color></link>. Has a <color=#00F6FF>50%</color> chance to attack another enemy.",
  str_skill_passive_desc_410077 = "Aurorians who have used an Active Skill will receive a bonus in this round, equal to <color=#00F6FF>{1}</color> of Bethlehem's basic ATK.",
  str_skill_passive_desc_420077 = "Aurorians who have used an Active Skill in this round will receive a bonus equal to <color=#00F6FF>{1}</color> of Bethlehem's basic ATK. Upon entering Aurora Time, the team will receive a bonus in this round equal to <color=#00F6FF>{2}</color> of Bethlehem's basic ATK.",
  str_skill_passive_desc_430077 = "Aurorians who have used an Active Skill will receive a bonus equal to <color=#00F6FF>{1}</color> of Bethlehem's basic ATK in this round. Bethlehem also gains a <color=#00F6FF>{2}</color> basic ATK bonus. This ATK bonus Bethlehem gains within the same round can be stacked. After entering Aurora Time, the team gains an additional bonus in this round equal to <color=#00F6FF>{2}</color> of Bethlehem's basic ATK.",
  str_skill_passive_desc_400092 = "When a marked enemy dies, gain HP equal to <color=#00F6FF>{1}</color> of the enemy's Max HP and <link=\"30007\"><#FFAE07><u>recovery effects</u></color></link>.",
  str_skill_passive_desc_410092 = "When a marked enemy dies, gain HP equal to <color=#00F6FF>{1}</color> of the enemy's Max HP and <link=\"30007\"><#FFAE07><u>recovery effects</u></color></link>.",
  str_skill_passive_desc_420092 = "When a marked enemy dies, gain HP equal to <color=#00F6FF>{1}</color> of the enemy's Max HP and <link=\"30007\"><#FFAE07><u>recovery effects</u></color></link>. Up to 1 tile where the enemy is located is changed to an <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link>.",
  str_skill_passive_desc_400075 = "Normal Attacks have a <color=#00F6FF>{1}</color> chance of inflicting 1 stack of <link=\"10001\"><#FFAE07><u>Poison</u></color></link> for 2 rounds.",
  str_skill_passive_desc_410075 = "Normal Attacks have a <color=#00F6FF>{1}</color> chance of inflicting 1 stack of <link=\"10001\"><#FFAE07><u>Poison</u></color></link> for 2 rounds.",
  str_skill_passive_desc_430075 = "Normal attacks can target enemies on <color=#00F6FF>diagonal tiles</color> and have a <color=#00F6FF>{1}</color> chance of inflicting 1 stack of <link=\"10001\"><#FFAE07><u>Poison</u></color></link> for 2 rounds.",
  str_skill_passive_desc_400086 = "Recovers HP equal to <color=#00F6FF>{1}</color> of Uriah's DEF when passing through an <link=\"20001\"><#FFAE07><u>enhanced</u></color></link> Green tile.",
  str_skill_passive_desc_410086 = "Recovers HP equal to <color=#00F6FF>{1}</color> of Uriah's DEF when passing through an <link=\"20001\"><#FFAE07><u>enhanced</u></color></link> Green tile.",
  str_skill_passive_desc_400068 = "When an Aurorian teleports, Wendy gains 1 stack of Mark for each cluster between the Aurorian's initial location and their teleport destination. Each stack increases the damage of Wendy's next normal attack by <color=#00F6FF>{1}</color>. Launching normal attacks clears the Mark.",
  str_skill_passive_desc_410068 = "When an Aurorian teleports, Wendy gains 1 stack of Mark for each cluster between the Aurorian's initial location and their teleport destination. Each stack increases the damage of Wendy's next normal attack by <color=#00F6FF>{1}</color>. Launching normal attacks clears the Mark.",
  str_skill_passive_desc_430068 = "When an Aurorian teleports, Wendy gains 1 Mark stack for each cluster between the Aurorian's initial location and their teleport destination. Each stack increases the damage of Wendy's next normal attack by <color=#00F6FF>{1}</color>. Wendy retains <color=#00F6FF>30%</color> of these Mark stacks after launching normal attacks.",
  str_skill_passive_desc_400082 = "Chain Combos have a <color=#00F6FF>{1}</color> chance of inflicting 1 stack of <link=\"10001\"><#FFAE07><u>Poison</u></color></link> for 2 rounds.",
  str_skill_passive_desc_410082 = "Chain Combos have a <color=#00F6FF>{1}</color> chance of inflicting 1 stack of <link=\"10001\"><#FFAE07><u>Poison</u></color></link> for 2 rounds.",
  str_skill_passive_desc_400057 = "At the start of each round, the team recovers HP equal to <color=#00F6FF>{1}</color> of Philyshy's ATK and <color=#00F6FF>{2}</color> of the HP lost by the team.",
  str_skill_passive_desc_410057 = "At the start of each round, the team recovers HP equal to <color=#00F6FF>{1}</color> of Philyshy's ATK and <color=#00F6FF>{2}</color> of the HP lost by the team.",
  str_skill_passive_desc_430057 = "At the start of each round, the team recovers HP equal to <color=#00F6FF>{1}</color> of Philyshy's ATK and <color=#00F6FF>{2}</color> of the HP lost by the team. For every <color=#00F6FF>5%</color> HP lost by the team, Philyshy's ATK increases by <color=#00F6FF>1%</color>.",
  str_skill_passive_desc_400091 = "When using an Active Skill or a Chain Combo, reduces the ATK of enemies in <color=#00F6FF>1 surrounding cluster</color> of the unit by <color=#00F6FF>{1}</color> for 1 round.",
  str_skill_passive_desc_410091 = "When using an Active Skill or a Chain Combo, reduces the ATK of enemies in <color=#00F6FF>1 surrounding cluster</color> of the unit by <color=#00F6FF>{1}</color> for 1 round.",
  str_skill_passive_desc_420091 = "When using an Active Skill or a Chain Combo, reduces the ATK of enemies in <color=#00F6FF>1 surrounding cluster</color> of the unit by <color=#00F6FF>{1}</color> for 1 round.",
  str_skill_passive_desc_430091 = "When using an Active Skill or a Chain Combo, reduces the ATK and DEF of enemies in <color=#00F6FF>2 surrounding clusters</color> of the unit by <color=#00F6FF>{1}</color> for 1 round.",
  str_skill_passive_desc_400079 = "When under attack by a target with higher HP percentage, it converts <color=#00F6FF>{1}</color> of Michenny's ATK to DEF.",
  str_skill_passive_desc_410079 = "When under attack by a target with higher HP percentage, it converts <color=#00F6FF>{1}</color> of Michenny's ATK to DEF.",
  str_skill_passive_desc_420079 = "When under attack by a target with higher HP percentage, it converts <color=#00F6FF>{1}</color> of Michenny's ATK to DEF. When Michenny deals damage, converts the same percentage of Michenny's DEF to ATK.",
  str_skill_passive_desc_400085 = "When an Active Skill deals damage to an enemy, increases the final damage by <color=#00F6FF>10%</color> for every <color=#00F6FF>{1}</color> HP lost by the enemy.",
  str_skill_passive_desc_410085 = "When an Active Skill deals damage to an enemy, increases the final damage by <color=#00F6FF>10%</color> for every <color=#00F6FF>{1}</color> HP lost by the enemy.",
  str_skill_passive_desc_400089 = "Grants 1 Gold Marsh Mark when passing through a <link=\"30001\"><#FFAE07><u>Prism tile</u></color></link>. Each stack of Gold Marsh Mark increases Chain Combo damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410089 = "Grants 1 Gold Marsh Mark when passing through a <link=\"30001\"><#FFAE07><u>Prism tile</u></color></link>. Each stack of Gold Marsh Mark increases Chain Combo damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420089 = "Grants 1 Gold Marsh Mark when passing through a <link=\"30001\"><#FFAE07><u>Prism tile</u></color></link>. Each stack of Gold Marsh Mark increases Chain Combo damage by <color=#00F6FF>{1}</color> and Normal Attack damage by <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_430089 = "Grants 1 Gold Marsh Mark when passing through a <link=\"30001\"><#FFAE07><u>Prism tile</u></color></link>. Each stack of Gold Marsh Mark increases Chain Combo damage by <color=#00F6FF>{1}</color> and Normal Attack damage by <color=#00F6FF>3%</color>. When triggering <link=\"30010\"><#FFAE07><u>Aurora Time</u></color></link>, converts the starting tile to a <link=\"30001\"><#FFAE07><u>Prism tile</u></color></link>.",
  str_skill_passive_desc_400027 = "Grants 1 stack of Silent Thunder Mark at the start of each round. Normal Attacks consume 1 stack of Silent Thunder Mark to deal extra damage equal to <color=#00F6FF>{1}</color> of current HP to the enemy.",
  str_skill_passive_desc_410027 = "Grants 1 stack of Silent Thunder Mark at the start of each round. Normal Attacks consume 1 stack of Silent Thunder Mark to deal extra damage equal to <color=#00F6FF>{1}</color> of current HP to the enemy.",
  str_skill_passive_desc_420027 = "Grants 1 stack of Silent Thunder Mark at the start of each round and when using an Active Skill or Chain Combo. Normal Attacks consume 1 stack of Silent Thunder Mark to deal extra damage equal to <color=#00F6FF>{1}</color> of current HP to the enemy.",
  str_skill_passive_desc_400060 = "When in the Noon state, normal attacks deal <color=#00F6FF>{1}%</color> <link=\"30015\"><#FFAE07><u>splash damage</u></color></link> to all targets in <color=#00F6FF>4 tiles in a cross shape</color> around the enemy.",
  str_skill_passive_desc_410060 = "When in the Noon state, normal attacks deal <color=#00F6FF>{1}%</color> <link=\"30015\"><#FFAE07><u>splash damage</u></color></link> to all targets in <color=#00F6FF>4 tiles in a cross shape</color> around the enemy.",
  str_skill_passive_desc_420060 = "When in the Noon state, increases the damage of normal attacks by <color=#00F6FF>20%</color> and normal attacks deal <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>splash</u></color></link> damage to all targets in <color=#00F6FF>4 tiles in a cross shape</color> around the enemy.",
  str_skill_passive_desc_430060 = "When in the Noon state, increases the damage of normal attacks by <color=#00F6FF>20%</color> and normal attacks deal <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>splash</u></color></link> damage to all targets in <color=#00F6FF>4 tiles in a cross shape</color> around the enemy.",
  str_skill_passive_desc_400064 = "Can <link=\"30008\"><#FFAE07><u>reserve ammo</u></color></link>. Each time a Chain Combo deals damage, 1 Ammo is consumed (up to <color=#00F6FF>3</color> Ammo can be consumed in the Overload state). For each Ammo consumed, final damage increases by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410064 = "Can <link=\"30008\"><#FFAE07><u>reserve ammo</u></color></link>. Each time a Chain Combo deals damage, 1 Ammo is consumed (up to <color=#00F6FF>3</color> Ammo can be consumed in the Overload state). For each Ammo consumed, final damage increases by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430064 = "Can <link=\"30009\"><#FFAE07><u>reserve ammo</u></color></link>. Each time a Chain Combo deals damage, 1 Ammo is consumed (up to <color=#00F6FF>3</color> Ammo can be consumed in the Overload state). For each Ammo consumed, final damage increases by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400070 = "Normal Attacks have a <color=#00F6FF>{1}</color> chance to trigger 1 Red Dragon Attack that deals damage equal to <color=#00F6FF>50%</color> of Leona's Normal Attack damage.",
  str_skill_passive_desc_410070 = "Normal Attacks have a <color=#00F6FF>{1}</color> chance to trigger 1 Red Dragon Attack that deals damage equal to <color=#00F6FF>50%</color> of Leona's Normal Attack damage.",
  str_skill_passive_desc_420070 = "Normal Attacks have a <color=#00F6FF>{1}</color> chance to trigger 1 Red Dragon Attack that deals damage equal to <color=#00F6FF>50%</color> of Leona's Normal Attack damage, and inflicts 1 stack of <link=\"10002\"><#FFAE07><u>Burning</u></color></link> for 2 rounds.",
  str_skill_passive_desc_400088 = "Increases Maggie's Chain Combo damage by <color=#00F6FF>{1}</color> after every <color=#00F6FF>10</color> combos.",
  str_skill_passive_desc_410088 = "Increases Maggie's Chain Combo damage by <color=#00F6FF>{1}</color> after every <color=#00F6FF>10</color> combos.",
  str_skill_passive_desc_420088 = "Increases Maggie's Chain Combo damage by <color=#00F6FF>{1}</color> after every <color=#00F6FF>10</color> combos and reduces the combo-triggering tile count by <color=#00F6FF>1</color>.",
  str_skill_passive_desc_430088 = "Increases Maggie's Chain Combo damage by <color=#00F6FF>{1}</color> after every <color=#00F6FF>8</color> combos and reduces the combo-triggering tile count by <color=#00F6FF>1</color>.",
  str_skill_passive_desc_400084 = "After using a Chain Combo, reduces the ATK of enemies within <color=#00F6FF>1 surrounding cluster</color> of the unit by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410084 = "After using a Chain Combo, reduces the ATK of enemies within <color=#00F6FF>1 surrounding cluster</color> of the unit by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420084 = "After using a Chain Combo, reduces the ATK of enemies within <color=#00F6FF>2 surrounding clusters</color> of the unit by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400090 = "Increases Barbara's damage by <color=#00F6FF>{1}</color> against enemies occupying a Red tile.",
  str_skill_passive_desc_410090 = "Increases Barbara's damage by <color=#00F6FF>{1}</color> against enemies occupying a Red tile.",
  str_skill_passive_desc_430090 = "Increases Barbara's damage against enemies occupying a Red tile by <color=#00F6FF>{1}</color>. Also grants Fire Aurorian teammates <color=#00F6FF>50%</color> of that bonus.",
  str_skill_passive_desc_400045 = "Nails' ATK and DEF increase as his HP percentage decreases, granting a bonus of up to <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410045 = "Nails' ATK and DEF increase as his HP percentage decreases, granting a bonus of up to <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400081 = "After using an Active Skill, increases Fire Aurorians' ATK equal to <color=#00F6FF>{1}</color> of Brock's ATK for every enemy within <color=#00F6FF>1 surrounding cluster</color> of the unit.",
  str_skill_passive_desc_410081 = "After using an Active Skill, increases Fire Aurorians' ATK equal to <color=#00F6FF>{1}</color> of Brock's ATK for every enemy within <color=#00F6FF>1 surrounding cluster</color> of the unit.",
  str_skill_passive_desc_430081 = "After using an Active Skill, increases Fire Aurorians' ATK equal to <color=#00F6FF>{1}</color> of Brock's ATK for every enemy within <color=#00F6FF>2 surrounding clusters</color> of the unit.",
  str_skill_passive_desc_400083 = "Active Skills have a <color=#00F6FF>{1}</color> chance to decrease enemies' movement range by <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_410083 = "Active Skills have a <color=#00F6FF>{1}</color> chance to decrease enemies' movement range by <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_430083 = "Active Skills have a <color=#00F6FF>{1}</color> chance to decrease enemies' movement range by <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_400059 = "Grants up to <color=#00F6FF>{1}</color> stack(s) of <link=\"30002\"><#FFAE07><u>Pepi Mark</u></color></link>. The movement range of the Active Skill becomes a number of clusters around the unit equal to the stacks of the mark. Activating the Active Skill clears all stacks.",
  str_skill_passive_desc_410059 = "Grants up to <color=#00F6FF>{1}</color> stack(s) of <link=\"30002\"><#FFAE07><u>Pepi Mark</u></color></link>. The movement range of the Active Skill becomes a number of clusters around the unit equal to the stacks of the mark. Activating the Active Skill clears all stacks.",
  str_skill_passive_desc_420059 = "Grants up to <color=#00F6FF>{1}</color> stack(s) of <link=\"30003\"><#FFAE07><u>Pepi Mark</u></color></link>. The movement range of the Active Skill becomes a number of clusters around the unit equal to the stacks of the mark. Activating the Active Skill clears all stacks.",
  str_skill_passive_desc_400080 = "When there are no enemies within the Chain Combo range, recovers the teams' HP equal to <color=#00F6FF>{1}</color> of Unimet's ATK.",
  str_skill_passive_desc_410080 = "When there are no enemies within the Chain Combo range, recovers the teams' HP equal to <color=#00F6FF>{1}</color> of Unimet's ATK.",
  str_skill_passive_desc_400093 = "After casting a Chain Combo or an Active Skill, if the target's HP is lower than <color=#00F6FF>{1}</color>, launches 1 more attack dealing DEF-ignoring damage equal to <color=#00F6FF>{2}</color> of ATK.",
  str_skill_passive_desc_410093 = "After casting a Chain Combo or an Active Skill, if the target's HP is lower than <color=#00F6FF>{1}</color>, launches 1 more attack dealing DEF-ignoring damage equal to <color=#00F6FF>{2}</color> of ATK.",
  str_skill_passive_desc_430093 = "After activating a Chain Combo or an Active Skill, if the target's HP is lower than <color=#00F6FF>{1}</color>, launches 1 more attack dealing DEF-ignoring damage equal to <color=#00F6FF>{2}</color> of ATK. If the target's HP is lower than Migard's ATK after the extra attack, it is killed.",
  str_skill_passive_desc_400097 = "Normal attacks become 2-combo attacks that deal <color=#00F6FF>{1}</color> basic damage in each hit.",
  str_skill_passive_desc_410097 = "Normal attacks become 2-combo attacks that deal <color=#00F6FF>{1}</color> basic damage in each hit.",
  str_skill_passive_desc_420097 = "Normal attacks become 2-combo attacks that deal <color=#00F6FF>{1}</color> basic damage in each hit. Each attack has a <color=#00F6FF>20%</color> chance to deal <color=#00F6FF>50%</color> extra damage.",
  str_skill_passive_desc_430097 = "Normal attacks become 2-combo attacks that deal <color=#00F6FF>{1}</color> basic damage in each hit. Each attack has a <color=#00F6FF>20%</color> chance to deal <color=#00F6FF>50%</color> extra damage. Each combo increases the trigger chance by 0.5%, up to 50%.",
  str_skill_passive_desc_400095 = "When dealing damage to a <link=\"10001\"><#FFAE07><u>Poisoned</u></color></link> enemy, each stack of Poison increases the final damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410095 = "When dealing damage to a <link=\"10001\"><#FFAE07><u>Poisoned</u></color></link> enemy, each stack of Poison increases the final damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420095 = "When dealing damage to a <link=\"10001\"><#FFAE07><u>Poisoned</u></color></link> enemy, each stack of Poison increases the final damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430095 = "When dealing damage to a <link=\"10001\"><#FFAE07><u>Poisoned</u></color></link> enemy, each stack of Poison increases the final damage by <color=#00F6FF>{1}</color>. When an Active Skill or a Chain Combo hits a Poisoned target, the unit is inflicted with 1 extra stack of Poison.",
  str_skill_passive_desc_400062 = "When a normal attack, Chain Combo, or Active Skill deals damage to only 1 enemy, this damage ignores <color=#00F6FF>{1}</color> of the target's DEF.",
  str_skill_passive_desc_410062 = "When a normal attack, Chain Combo, or Active Skill deals damage to only 1 enemy, this damage ignores <color=#00F6FF>{1}</color> of the target's DEF.",
  str_skill_passive_desc_430062 = "When Normal Attack, Chain Combo, or Active Skill deals damage to only 1 enemy, this damage ignores <color=#00F6FF>{1}</color> of the target's DEF. When there is only 1 enemy on the board, the Active Skills of other Forest Aurorians in the team also gain 50% of this effect.",
  str_skill_passive_desc_400024 = "Normal attacks deal an extra <color=#00F6FF>{1}</color> damage to enemies occupying Red tiles.",
  str_skill_passive_desc_410024 = "Normal attacks deal an extra <color=#00F6FF>{1}</color> damage to enemies occupying Red tiles.",
  str_skill_passive_desc_400087 = "When a Chain Combo hits a target, it also deals damage to <color=#00F6FF>{1}</color> random target(s) (each target can only be dealt damage once) within <color=#00F6FF>1 surrounding cluster</color> of the target. The damage decreases by <color=#00F6FF>{2}</color> with each hit.",
  str_skill_passive_desc_410087 = "When a Chain Combo hits a target, it also deals damage to <color=#00F6FF>{1}</color> random target(s) (each target can only be dealt damage once) within <color=#00F6FF>1 surrounding cluster</color> of the target. The damage decreases by <color=#00F6FF>{2}</color> with each hit.",
  str_skill_passive_desc_420087 = "When a Chain Combo hits a target, it also deals damage to <color=#00F6FF>{1}</color> random target(s) (each target can only be dealt damage once) within <color=#00F6FF>2 surrounding clusters</color> of the target. The damage decreases by <color=#00F6FF>{2}</color> with each hit.",
  str_skill_passive_desc_400101 = "Increases the damage Ansia deals to enemies along the edge of the battlefield (the damage bonus is the highest when enemies are in the corner), up to a boost of <color=#00F6FF>{1}</color> final damage.",
  str_skill_passive_desc_410101 = "Increases the damage Ansia deals to enemies along the edge of the battlefield (the damage bonus is the highest when enemies are in the corner), up to a boost of <color=#00F6FF>{1}</color> final damage.",
  str_skill_passive_desc_400102 = "Grants 1 Tessa Mark whenever a Thunder Aurorian in the team uses their Active Skill. When using the Active Skill, each mark deals <color=#00F6FF>{1}</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Activating the Active Skill clears all marks.",
  str_skill_passive_desc_410102 = "Grants 1 Tessa Mark whenever a Thunder Aurorian in the team uses their Active Skill. When using the Active Skill, each mark deals <color=#00F6FF>{1}</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Activating the Active Skill clears all marks.",
  str_skill_passive_desc_420102 = "Grants 1 Tessa Mark whenever a Thunder Aurorian in the team uses their Active Skill or when Tessa uses a Chain Combo. When using the Active Skill, each mark deals <color=#00F6FF>{1}</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Activating the Active Skill clears all marks.",
  str_skill_passive_desc_430102 = "Grants 1 Tessa Mark whenever a Thunder Aurorian in the team uses their Active Skill or when Tessa uses a Chain Combo. When using the Active Skill, each mark deals <color=#00F6FF>{1}</color> DEF-ignoring damage to enemies within <color=#00F6FF>2 surrounding clusters</color>. Activating the Active Skill clears all marks.",
  str_skill_passive_desc_400099 = "When controlling the magic sword, normal attacks will penetrate through enemies, dealing <color=#00F6FF>{1}</color> damage to the target 1 tile behind the enemy.",
  str_skill_passive_desc_410099 = "When controlling the magic sword, normal attacks will penetrate through enemies, dealing <color=#00F6FF>{1}</color> damage to the target 1 tile behind the enemy.",
  str_skill_passive_desc_400100 = "When Sikare attacks enemies for the first time, she reaps the soul of the target, dealing damage equal to <color=#00F6FF>{1}</color> of ATK to that enemy (this damage ignores DEF).",
  str_skill_passive_desc_410100 = "When Sikare attacks enemies for the first time, she reaps the soul of the target, dealing damage equal to <color=#00F6FF>{1}</color> of ATK to that enemy (this damage ignores DEF).",
  str_skill_passive_desc_430100 = "When Sikare attacks enemies for the first time, she reaps the soul of the target, dealing damage equal to <color=#00F6FF>{1}</color> of ATK plus DEF-ignoring damage equal to <color=#00F6FF>5%</color> of current HP to that enemy.",
  str_skill_passive_desc_400098 = "When a Chain Combo hits an enemy, inflicts 1 stack of Dismember Mark. Stacks up to 5 times. Each stack of Dismember Mark increases Cuscuta's damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410098 = "When a Chain Combo hits an enemy, inflicts 1 stack of Dismember Mark. Stacks up to 5 times. Each stack of Dismember Mark increases Cuscuta's damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420098 = "When a Chain Combo hits an enemy, inflicts 1 stack of Dismember Mark. Stacks up to 5 times. Each stack of Dismember Mark increases Cuscuta's damage by <color=#00F6FF>{1}</color>. Normal attacks have a <color=#00F6FF>30%</color> chance to inflict 1 stack of Dismember Mark.",
  str_skill_passive_desc_4200981 = "When a Chain Combo hits an enemy, inflicts 1 stack of Dismember Mark. Stacks up to 10 times. Each stack of Dismember Mark increases Cuscuta's damage by <color=#00F6FF>6%</color>. Normal attacks have a <color=#00F6FF>30%</color> chance to inflict 1 stack of Dismember Mark.",
  str_skill_passive_desc_400094 = "After a Chain Combo hits the target, reduces the target's ATK by <color=#00F6FF>{1}</color> for 1 round.",
  str_skill_passive_desc_410094 = "After a Chain Combo hits the target, reduces the target's ATK by <color=#00F6FF>{1}</color> for 1 round.",
  str_skill_passive_desc_400096 = "Grants a <link=\"30013\"><#FFAE07><u>Sariel Mark</u></color></link>, up to 8 stacks. Each stack increases Sariel's DEF by <color=#00F6FF>{1}</color>. Retains 50% of the stacks at the end of the round.",
  str_skill_passive_desc_410096 = "Grants a <link=\"30013\"><#FFAE07><u>Sariel Mark</u></color></link>, up to 8 stacks. Each stack increases Sariel's DEF by <color=#00F6FF>{1}</color>. Retains 50% of the stacks at the end of the round.",
  str_skill_passive_desc_420096 = "Grants a <link=\"30013\"><#FFAE07><u>Sariel Mark</u></color></link>, up to 8 stacks. Each stack increases Sariel's DEF by <color=#00F6FF>{1}</color>, increasing up to <color=#00F6FF>50%</color> DEF based on the amount of HP lost. Retains 50% of the stacks at the end of the round.",
  str_skill_passive_desc_400056 = "When a normal attack or an Active Skill deals damage (whichever is more), converts <color=#00F6FF>{1}</color> of the damage to ATK. Only valid for current round.",
  str_skill_passive_desc_410056 = "When a normal attack or an Active Skill deals damage (whichever is more), converts <color=#00F6FF>{1}</color> of the damage to ATK. Only valid for current round.",
  str_skill_passive_desc_430056 = "When a normal attack or an Active Skill deals damage (whichever is more), convert <color=#00F6FF>{1}</color> of the damage to ATK. Only valid for current round. When there is only 1 enemy on the battlefield, increases the ATK of Water Aurorians by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_400103 = "Every 3 rounds, Hollow can be activated or saved for future use. After becoming Hollow, Chain Combo damage ignores defense and deals damage equal to <color=#00F6FF>{1}</color> of Eicy's ATK, and recovers HP by the same amount.",
  str_skill_passive_desc_410103 = "Every 3 rounds, Hollow can be activated or saved for future use. After becoming Hollow, Chain Combo damage ignores defense and deals damage equal to <color=#00F6FF>{1}</color> of Eicy's ATK, and recovers HP by the same amount.",
  str_skill_passive_desc_430103 = "Grants the Void status once every 3 rounds (if not used, this status is retained). When in the Void status, Chain Combo deals damage equal to <color=#00F6FF>{1}</color> of Eicy's ATK (this damage ignores DEF), and restores HP by the same amount. The lower the team's HP, the higher the healing effectiveness (up to <color=#00F6FF>50%</color>).",
  str_skill_passive_desc_410067 = "If HP has been recovered in this round, Alice's basic DEF increases by <color=#00F6FF>{1}</color> for this round.",
  str_skill_passive_desc_430067 = "If HP has been recovered in this round, Alice's basic DEF increases by <color=#00F6FF>{1}</color> for this round.",
  str_skill_passive_desc_400030 = "Normal attacks <color=#00F6FF>can hit diagonally</color>. Normal diagonal attacks afflict the target with 1 stack of Shatter, which stacks up to 5 times. Each stack reduces the target's DEF by an amount equal to <color=#00F6FF>{1}</color> of Sinsa's basic DEF for 1 round.",
  str_skill_passive_desc_410030 = "Normal attacks <color=#00F6FF>can hit diagonally</color>. Normal diagonal attacks afflict the target with 1 stack of Shatter, which stacks up to 5 times. Each stack reduces the target's DEF by an amount equal to <color=#00F6FF>{1}</color> of Sinsa's basic DEF for 1 round.",
  str_skill_passive_desc_430030 = "Normal attacks <color=#00F6FF>can hit diagonally</color>. Normal diagonal attacks, Active Skills, and Chain Combos afflict the target with 1 stack of Shatter, which stacks up to 5 times. Each stack reduces the target's DEF by an amount equal to <color=#00F6FF>{1}</color> of Sinsa's basic DEF for 1 round.",
  str_skill_passive_desc_410104 = "Active Skills mark the attack target. When Dawn's Active Skills and Chain Combos attack marked enemies, the mark is consumed and restores HP equal to <color=#00F6FF>{1}</color> of damage dealt.",
  str_skill_passive_desc_430104 = "Active Skills mark the attack target. When Dawn's Active Skills and Chain Combos attack marked enemies, the mark is consumed and restores HP equal to <color=#00F6FF>{1}</color> of damage dealt. If the team is at full HP, the final damage of this attack will be increased by <color=#00F6FF>25%</color>.",
  str_skill_passive_desc_410071 = "At the start of each round, applies a Burn Mark to the enemy with the highest percentage of HP, increasing all damage Taki deals to the target by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430071 = "At the start of each round, applies a Burn Mark to the enemy with the highest percentage of HP, increasing all damage Taki deals to the target by <color=#00F6FF>{1}</color>. Each time an enemy afflicted with Burn Mark is eliminated, Taki's ATK increases by <color=#00F6FF>3%</color>, up to a maximum of <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_400105 = "When normal attacks, Chain Combos, and Active Skills deal damage, every <color=#00F6FF>10</color>th instance of damage also deals <color=#00F6FF>{1}</color> damage once to <color=#00F6FF>all</color> enemies.",
  str_skill_passive_desc_410105 = "When normal attacks, Chain Combos, and Active Skills deal damage, every <color=#00F6FF>10</color>th instance of damage also deals <color=#00F6FF>{1}</color> damage once to <color=#00F6FF>all</color> enemies.",
  str_skill_passive_desc_420105 = "When normal attacks, Chain Combos, and Active Skills deal damage, every <color=#00F6FF>8</color>th instance of damage also deals <color=#00F6FF>{1}</color> damage once to <color=#00F6FF>all</color> enemies.",
  str_skill_passive_desc_430105 = "When normal attacks, Chain Combos, and Active Skills deal damage, every <color=#00F6FF>8</color>th instance of damage also deals <color=#00F6FF>{1}</color> damage once to <color=#00F6FF>all</color> enemies.",
  str_skill_passive_desc_430109 = "Gain <color=#00F6FF>5</color> Vis at the beginning of every round.",
  str_skill_passive_desc_433109 = "Gains <color=#00F6FF>5</color> Vis at the beginning of every round. Gains <color=#00F6FF>1</color> Vis for the first normal attack launched each round and increases the damage of this normal attack by <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_430110 = "Gains <color=#00F6FF>5</color> Vis at the beginning of every round. Normal attacks have a <color=#00F6FF>30%</color> chance to release 1 lightning strike to hit the farthest enemy.",
  str_skill_passive_desc_433110 = "Gains <color=#00F6FF>5</color> Vis at the beginning of every round. Gains <color=#00F6FF>2</color> extra Vis when killing a target with an Active Skill. Normal attacks have a <color=#00F6FF>30%</color> chance to release 1 lightning strike to hit the farthest enemy.",
  str_skill_passive_desc_430107 = "Gains 10 Vis at the beginning of the battle. When ending the round in a non-augmented state, gains <color=#00F6FF>5</color> Vis (gains 1 extra Vis for every 20% of HP lost).",
  str_skill_passive_desc_436107 = "Gains 10 Vis at the beginning of the battle. At the start of each round, for every 1 enemy exists <color=#00F6FF>in 4 tiles in a cross shape</color> around, gains <color=#00F6FF>1</color> Vis. When ending the round in a non-augmented state, gains <color=#00F6FF>5</color> Vis (gains 1 extra Vis for every 20% of HP lost).",
  str_skill_passive_desc_430108 = "Gains <color=#00F6FF>5</color> Vis at the beginning of every round. Gains an extra <color=#00F6FF>5</color> Vis when killing a target with an Active Skill.",
  str_skill_passive_desc_400116 = "All damage Fleur deals to enemies with less than 40% of their Max HP is increased by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410112 = "Smokey triggers <color=#00F6FF>Manticore's Kiss</color> <color=#00F6FF>each time</color> she attacks an enemy with an <color=#00F6FF>Active Skill or Chain Combo, or the first time she hits them with a normal attack each round</color>, dealing additional DEF-ignoring damage equal to <color=#00F6FF>{1}</color> ATK. This effect decreases when triggered repeatedly, down to a minimum of <color=#00F6FF>20%</color> of its initial damage.",
  str_skill_passive_desc_420112 = "Smokey triggers <color=#00F6FF>Manticore's Kiss</color> <color=#00F6FF>each time</color> she attacks an enemy with an <color=#00F6FF>Active Skill or Chain Combo, or the first time she hits them with a normal attack each round</color>, dealing additional DEF-ignoring damage equal to <color=#00F6FF>{1}</color> ATK. This effect decreases when triggered repeatedly, down to a minimum of <color=#00F6FF>20%</color> of its initial damage. <color=#00F6FF>Manticore's Kiss</color> deals <color=#00F6FF>double</color> damage to enemies on Red tiles.",
  str_skill_passive_desc_430112 = "Smokey triggers <color=#00F6FF>Manticore's Kiss</color> <color=#00F6FF>each time</color> she attacks an enemy with an <color=#00F6FF>Active Skill or Chain Combo, or the first time she hits them with a normal attack each round</color>, dealing additional DEF-ignoring damage equal to <color=#00F6FF>{1}</color> ATK. This effect decreases when triggered repeatedly, down to a minimum of <color=#00F6FF>20%</color> of its initial damage. <color=#00F6FF>Manticore's Kiss</color> deals <color=#00F6FF>double</color> damage to enemies on Red tiles.",
  str_skill_passive_desc_400113 = "Gains a Divine Mark at the start of battle or upon using an Active Skill. While this mark exists, Bonacie's DEF increases by <color=#00F6FF>{1}</color>. This mark disappears once Bonacie loses HP.",
  str_skill_passive_desc_410113 = "Gains a Divine Mark at the start of battle or upon using an Active Skill. While this mark exists, Bonacie's DEF increases by <color=#00F6FF>{1}</color>. This mark disappears once Bonacie loses HP.",
  str_skill_passive_desc_420113 = "Gains a Divine Mark at the start of battle or upon using an Active Skill. While this mark exists, Bonacie's DEF increases by <color=#00F6FF>{1}</color>. This mark disappears once Bonacie loses HP. When this mark exists, the Chain Combo damage dealt by Thunder Aurorians increases by <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_400114 = "When an Active Skill deals damage, recovers the team's HP by an amount equal to <color=#00F6FF>{1}</color> of the damage dealt.",
  str_skill_passive_desc_410114 = "When an Active Skill deals damage, recovers the team's HP by an amount equal to <color=#00F6FF>{1}</color> of the damage dealt.",
  str_skill_passive_desc_430114 = "When an Active Skill deals damage, recovers the team's HP by an amount equal to <color=#00F6FF>{1}</color> of the damage dealt and increases the Chain Combo damage dealt by Fire Aurorians by <color=#00F6FF>10%</color> this round.",
  str_skill_passive_desc_410127 = "At the start of each round, if there are enemies within <color=#00F6FF>2 surrounding clusters</color>, throws a dagger at any 1 enemy, dealing <color=#00F6FF>{1}</color> damage and inflicting 1 stack of <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> status for 2 rounds.",
  str_skill_passive_desc_430127 = "At the start of each round, if there are enemies within <color=#00F6FF>2 surrounding clusters</color>, throws a dagger at any 1 enemy, dealing <color=#00F6FF>{1}</color> damage and inflicting 1 stack of <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> status for 2 rounds. The dagger will be triggered when passing through Paper Cranes.",
  str_skill_desc_3351221 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>16 tiles in a radial shape</color> centered on 1 selected tile. Damage dealt to the selected tile ignores DEF. Clears <color=#00F6FF>broken tile</color> effects from tiles in this span. When Blessing reaches 10 stacks, active skill range becomes the <color=#00F6FF>maximum radial-shaped span</color>.",
  str_skill_passive_desc_410117 = "Can accumulate <link=\"30016\"><#FFAE07><u>Fury</u></color></link>. Each stack of Fury increases Gram's basic ATK by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430117 = "Can accumulate <link=\"30017\"><#FFAE07><u>Fury</u></color></link>. Each stack of Fury increases Gram's basic ATK by <color=#00F6FF>{1}</color>. There is no limit to how much Fury can be gained from his Active Skill. This effect will be cleared at the end of each wave. For every stack cleared, Gram will recover for an amount equal to <color=#00F6FF>5%</color> of his Max HP.",
  str_skill_passive_desc_410119 = "Can stack <link=\"30018\"><#FFAE07><u>Dauntless Heart</u></color></link>. Each stack of Dauntless Heart increases Revy's basic ATK by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420119 = "Can stack <link=\"30018\"><#FFAE07><u>Dauntless Heart</u></color></link>. Each stack of Dauntless Heart increases Revy's basic ATK by <color=#00F6FF>{1}</color> and Active Skill damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430119 = "Can stack <link=\"30018\"><#FFAE07><u>Dauntless Heart</u></color></link>. Each stack of Dauntless Heart increases Revy's basic ATK by <color=#00F6FF>{1}</color> and Active Skill damage by <color=#00F6FF>5%</color>. Normal attacks <color=#00F6FF>can hit diagonally</color>.",
  str_skill_passive_desc_410122 = "Can obtain <link=\"30019\"><#FFAE07><u>Blessing</u></color></link>. Each Blessing stack increases Allura's Active Skill damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410121 = "Whenever passing through an <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>, gains 1 stack of Barbed Mark. Each stack increases chain damage by <color=#00F6FF>{1}</color>. Retains 50% of stacks at the end of the round.",
  str_skill_passive_desc_430121 = "Whenever passing through an <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>, gains 1 stack of Barbed Mark. Each stack increases Chain Combo and Normal Attack damage by <color=#00F6FF>{1}</color>. Retains 50% of stacks at the end of the round.",
  str_skill_passive_desc_410065 = "Each Chain Combo hit grants 1 stack of Snowpuff Mark. Each stack increases DEF by <color=#00F6FF>{1}</color>. The mark disappears at the end of the round.",
  str_skill_passive_desc_410115 = "Whenever passing through an <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>, gains 1 stack of Emerald Mark. Each stack grants <color=#00F6FF>{1}</color> of Naroxel's basic ATK. Retains 50% of stacks at the end of the round.",
  str_skill_passive_desc_430115 = "Whenever passing through an <link=\"20001\"><#FFAE07><u>Enhanced Tile</u></color></link>, gains 1 stack of Emerald Mark. Each stack grants your entire team <color=#00F6FF>{1}</color> of Naroxel's basic ATK. Retains 50% of stacks at the end of the round.",
  str_skill_passive_desc_410126 = "Summons <link=\"30024\"><#FFAE07><u>Frankel</u></color></link> to the tile selected by your Active Skill. Each time a unit uses an Active Skill, Frankel unleashes a <color=#00F6FF>Roar</color>, dealing <color=#00F6FF>{1}</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Frankel also unleashes a <color=#00F6FF>Roar</color> when disappearing.",
  str_skill_passive_desc_420126 = "Summons <link=\"30024\"><#FFAE07><u>Frankel</u></color></link> to the tile selected by your Active Skill. Each time a unit uses an Active Skill, Frankel unleashes a <color=#00F6FF>Roar</color>, dealing <color=#00F6FF>{1}</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. If only one enemy is within the range, unleashes <color=#00F6FF>Sundering Claw</color>, increasing damage by <color=#00F6FF>50%</color>. Frankel also unleashes a <color=#00F6FF>Roar</color> when disappearing.",
  str_skill_passive_desc_410129 = "Active Skills and Chain Combos inflict 1 stack of Parasitic Mark each time they deal damage. Parasitic Mark stacks up to <color=#00F6FF>9</color> times. Each time an enemy moves 1 tile, each stack of Parasitic Mark deals <color=#00F6FF>{1}</color> damage.",
  str_skill_passive_desc_420129 = "Active Skills and Chain Combos inflict 1 stack of Parasitic Mark each time they deal damage. Parasitic Mark stacks up to <color=#00F6FF>9</color> times. Each time an enemy moves 1 tile, each stack of Parasitic Mark deals <color=#00F6FF>{1}</color> damage. Luke's normal attacks and Chain Combos deal <color=#00F6FF>30%</color> increased damage to the enemy afflicted with the highest number of Parasitic Mark stacks.",
  str_skill_passive_desc_430129 = "Active Skills and Chain Combos inflict 1 stack of Parasitic Mark each time they deal damage. Parasitic Mark stacks up to <color=#00F6FF>9</color> times. Each time an enemy moves 1 tile, each stack of Parasitic Mark deals <color=#00F6FF>{1}</color> damage. This damage increases to <color=#00F6FF>{2}</color> for the enemy with the highest number of stacks on the battlefield. Luke's normal attacks and Chain Combos deal <color=#00F6FF>30%</color> increased damage to the enemy afflicted with the highest number of Parasitic Mark stacks.",
  str_skill_passive_desc_410055 = "When attacked, gains 1 stack of Battle Mark. Can stack up to <color=#00F6FF>15</color> times. Each Battle Mark stack increases ATK by <color=#00F6FF>{1}</color>. Battle Mark stacks decrease by 50% each round.",
  str_skill_passive_desc_420055 = "When attacked, gains 1 stack of Battle Mark. Can stack up to <color=#00F6FF>15</color> times. Each Battle Mark stack increases ATK and DEF by <color=#00F6FF>{1}</color>. Battle Mark stacks decrease by 50% each round.",
  str_skill_passive_desc_430055 = "When attacked, gains 1 stack of Battle Mark. Can stack up to <color=#00F6FF>15</color> times. Each Battle Mark stack increases ATK and DEF by <color=#00F6FF>{1}</color>. Battle Mark stacks decrease by 50% each round. For each stack of Battle Mark lost, gains a shield equal to <color=#00F6FF>12%</color> of Pittman's Max HP.",
  str_skill_passive_desc_410120 = "When using Chain Combos and Active Skills, Pompey will show up and attack instead of Hedy. Pompey's ATK is equal to <color=#00F6FF>{1}</color> of Hedy's ATK.",
  str_skill_passive_desc_430120 = "When using Chain Combos and Active Skills, Pompey will show up and attack instead of Hedy. Pompey's ATK is equal to <color=#00F6FF>{1}</color> of Hedy's ATK. During Aurora Time, Pompey's ATK increases by <color=#00F6FF>2%</color> with every tile connection, up to a maximum of <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_410123 = "For every 1 enemy within <color=#00F6FF>12 tiles in a diamond shape</color>, ATK increases by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430123 = "For every 1 enemy within <color=#00F6FF>2 clusters</color>, ATK and DEF increase by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410015 = "For each cluster grenades travel before Active Skill deals damage, final damage increases by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420015 = "For each cluster grenades travel before Active Skill deals damage, final damage increases by <color=#00F6FF>{1}</color>. For each cluster grenades travel before Chain Combo deals damage, final damage increases by <color=#00F6FF>{2}</color>.",
  str_skill_passive_desc_410131 = "If the team is not at full HP before using a normal attack, this normal attack's effect will instead restore HP equal to <color=#00F6FF>{1}</color> of Novio's ATK.",
  str_skill_passive_desc_430131 = "If the team is not at full HP before using a normal attack, this normal attack's effect will instead restore HP equal to <color=#00F6FF>{1}</color> of Novio's ATK. If the team is at full HP, this attack and its Chain Combo damage will increase by <color=#00F6FF>10%</color>. Damage bonus will increase to <color=#00F6FF>25%</color> if a Shield already exists.",
  str_skill_passive_desc_410132 = "During Aurora Time, ATK is increased by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430132 = "During Aurora Time, ATK is increased by <color=#00F6FF>{1}</color>, and triggers Chain Combo when passing through any tiles. Chain Combo damage will always be considered as the Forest element.",
  str_skill_passive_desc_410133 = "Every Combo increases Chain Combo Damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430133 = "Every Combo increases Chain Combo Damage by <color=#00F6FF>{1}</color> and Splash Damage by <color=#00F6FF>{2}</color>.",
  str_skill_passive_desc_410137 = "Active Skill deals damage to a selected enemy. For every <color=#00F6FF>1</color> blue tile at the enemy's feet, it deals <color=#00F6FF>{1}</color> of Fafnir's Atk damage.",
  str_skill_passive_desc_430137 = "Active Skill deals damage to a selected enemy, for every <color=#00F6FF>1</color> Blue tile at the enemy's feet, deals <color=#00F6FF>{1}</color> of Fafnir's ATK damage. Active Skills from other Dragon Maid characters will also trigger this damage effect when hits an enemy.",
  str_skill_passive_desc_410134 = "Kanna gains 3 charges when casting her Active Skill and 1 charge when any Thunder Aurorians or Dragon Maid characters cast their Active Skills, up to 10 charges. Every charge increases Basic ATK by <color=#00F6FF>{1}</color>, and will be cleared after the round ends.",
  str_skill_passive_desc_430134 = "Kanna gains 3 charges when casting her Active Skill and 1 charge when any Thunder Aurorians or Dragon Maid characters cast their Active Skills, up to 10 charges. Every charge increases Basic ATK by <color=#00F6FF>{1}</color>, and half the charges will be cleared after the round ends.",
  str_skill_passive_desc_416134 = "Kanna gains 3 charges when casting her Active Skill and 1 charge when any Thunder Aurorians or Dragon Maid characters cast their Active Skills, up to 10 charges. Every charge increases Basic ATK by <color=#00F6FF>{1}</color>, and will be cleared after the round ends. Kanna gains 2 charges at the start of each wave.",
  str_skill_passive_desc_436134 = "Kanna gains 3 charges when casting her Active Skill and 1 charge when any Thunder Aurorians or Dragon Maid characters cast their Active Skills, up to 10 charges. Every charge increases Basic ATK by <color=#00F6FF>{1}</color>, and half the charges will be cleared after the round ends. Kanna gains 2 charges at the start of each wave.",
  str_skill_passive_desc_410135 = "Increases Chain Combo damage by <color=#00F6FF>{1}</color> when HP is full.",
  str_skill_passive_desc_430135 = "Increases normal attack, Chain Combo, and Active Skill damage by <color=#00F6FF>{1}</color> when HP is full.",
  str_skill_passive_desc_410136 = "When a Chain Combo hits an enemy, 1 stack of Mortality Mark is inflicted. Each stack of the mark increases Active Skill damage received by this enemy from all Aurorians by <color=#00F6FF>{1}</color>. Maximum <color=#00F6FF>10</color> stacks, and lasts for the entire battle.",
