  str_skill_passive_desc_430141 = "For every <color=#00F6FF>3</color> times the Chain Combo deals damage to the same target, inflict extra damage equal to <color=#00F6FF>{1}</color> of the target's current HP, and no less than <color=#00F6FF>{2}</color> of Ruby's basic DEF.",
