  str_skill_desc_302142 = "Choose 1 of the <color=#00F6FF>13 tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to the selected tile and its <color=#00F6FF>2 surrounding clusters</color> and forcing <color=#00F6FF>non-Boss</color> enemies within range to move <color=#00F6FF>2</color> tiles towards the selected tile. The damage is reduced by 53% per cluster.",
  str_skill_desc_320142 = "Choose 1 of the <color=#00F6FF>13 tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to the selected tile and its <color=#00F6FF>3 surrounding clusters</color> and forcing <color=#00F6FF>non-Boss</color> enemies within range to move <color=#00F6FF>2</color> tiles towards the selected tile. The damage is reduced by 53% per cluster.",
  str_skill_desc_322142 = "Choose 1 of the <color=#00F6FF>13 tiles in a diamond shape</color>, dealing <color=#00F6FF>{1}%</color> damage to the selected tile and its <color=#00F6FF>3 surrounding clusters</color> and forcing <color=#00F6FF>non-Boss</color> enemies within range to move <color=#00F6FF>2</color> tiles towards the selected tile. The damage is reduced by 53% per cluster.",
