  str_skill_passive_desc_420142 = "For every <color=#00F6FF>3rd</color> and <color=#00F6FF>5th</color> normal attack, damage is increased based on the target's remaining HP. The increase reaches a maximum of <color=#00F6FF>{1}</color> when the target is at its max HP.",
