  str_skill_desc_300140 = "After using, Thunder Aurorians will release their Chain Combo <color=#00F6FF>twice</color> during this round. For the <color=#00F6FF>second</color> release, all Thunder Aurorians' ATK is <color=#00F6FF>80%</color> of Florine's.",
  str_skill_desc_306140 = "After using, Thunder Aurorians will release their Chain Combo <color=#00F6FF>twice</color> during this round. For the <color=#00F6FF>second</color> release, all Thunder Aurorians' ATK is <color=#00F6FF>80%</color> of Florine's.",
  str_skill_desc_320140 = "After using, Thunder Aurorians will release their Chain Combo <color=#00F6FF>twice</color> during this round. For the <color=#00F6FF>second</color> release, all Thunder Aurorians' ATK is <color=#00F6FF>80%</color> of Florine's. At the same time, the number of tiles required to trigger Thunder Aurorian Chain Combos is changed by <color=#00F6FF>-1</color>.",
  str_skill_desc_326140 = "After using, Thunder Aurorians will release their Chain Combo <color=#00F6FF>twice</color> during this round. For the <color=#00F6FF>second</color> release, all Thunder Aurorians' ATK is <color=#00F6FF>80%</color> of Florine's. At the same time, the number of tiles required to trigger Thunder Aurorian Chain Combos is changed by <color=#00F6FF>-1</color>.",
  str_skill_desc_330140 = "After using, Thunder Aurorians will release their Chain Combo <color=#00F6FF>twice</color> during this round. For the <color=#00F6FF>second</color> release, all Thunder Aurorians' ATK is <color=#00F6FF>95%</color> of Florine's. At the same time, the number of tiles required to trigger Thunder Aurorian Chain Combos is changed by <color=#00F6FF>-1</color>.",
  str_skill_desc_336140 = "After using, Thunder Aurorians will release their Chain Combo <color=#00F6FF>twice</color> during this round. For the <color=#00F6FF>second</color> release, all Thunder Aurorians' ATK is <color=#00F6FF>95%</color> of Florine's. At the same time, the number of tiles required to trigger Thunder Aurorian Chain Combos is changed by <color=#00F6FF>-1</color>.",
  str_skill_passive_desc_410140 = "The damage for all thunder Aurorian Chain Combos of different ranks are increased by <color=#00F6FF>{1}</color>/<color=#00F6FF>{2}</color>/<color=#00F6FF>{3}</color>, respectively.",
  str_skill_name_200150110 = "Ghost - Rip",
  str_skill_desc_200150110 = "Slashes with its sharp claws at targets within range.",
  str_skill_name_290200101 = "Shadow Nobutora",
