  str_skill_passive_desc_430145 = "After teleporting with the Active Skill, retrieve all katanas. Each katana deals <color=#00F6FF>{1}</color> damage to the nearest <color=#00F6FF>1</color> enemy while ignoring their DEF. The further the distance, the lower the damage (minimum 20% of the original damage). If at least <color=#00F6FF>4</color> katanas are retrieved, <color=#00F6FF>1</color> new katana will be summoned. When Amemori becomes the Captain, she gains <color=#00F6FF>1</color> <link=\"30028\"><#FFAE07><u>Ninja Power</u></color></link>. Triggers up to <color=#00F6FF>3</color> times per round.",
  str_skill_passive_desc_433145 = "After teleporting with the Active Skill, retrieve all katanas. Each katana deals <color=#00F6FF>{1}</color> damage to the nearest <color=#00F6FF>1</color> enemy while ignoring their DEF. The further the distance, the lower the damage (minimum 20% of the original damage). If at least <color=#00F6FF>4</color> katanas are retrieved, <color=#00F6FF>1</color> new katana will be summoned. When Amemori becomes the Captain, she gains <color=#00F6FF>1</color> <link=\"30029\"><#FFAE07><u>Ninja Power</u></color></link>. Triggers up to <color=#00F6FF>3</color> times per round.",
  str_skill_passive_desc_436145 = "After teleporting with the Active Skill, retrieve all katanas. Each katana deals <color=#00F6FF>{1}</color> damage to the nearest <color=#00F6FF>1</color> enemy while ignoring their DEF. The further the distance, the lower the damage (minimum 20% of the original damage). If at least <color=#00F6FF>4</color> katanas are retrieved, <color=#00F6FF>1</color> new katana will be summoned. When Amemori becomes the Captain, she gains <color=#00F6FF>1</color> <link=\"30029\"><#FFAE07><u>Ninja Power</u></color></link>. Triggers up to <color=#00F6FF>3</color> times per round. Captain changes for the battle: <color=#00F6FF>+1</color>.",
