  str_skill_passive_desc_410146 = "Gains <link=\"30026\"><#FFAE07><u>Heroic Mark</u></color></link>. If Yao has been Captain in this round, each stack of Heroic Mark increases her base ATK by <color=#00F6FF>{1}</color>. Bonuses and stacks are cleared at the end of the round.",
