  str_skill_passive_desc_430146 = "Gains <link=\"30027\"><#FFAE07><u>Heroic Mark</u></color></link>. If Yao has been Captain in this round, each stack of Heroic Mark increases her base ATK by <color=#00F6FF>{1}</color>. Bonuses and stacks are cleared at the end of the round. Whenever Yao becomes the Captain, gain <color=#00F6FF>1</color> stack of <link=\"30027\"><#FFAE07><u>Heroic Mark</u></color></link>.",
  str_skill_passive_desc_436146 = "Gains <link=\"30027\"><#FFAE07><u>Heroic Mark</u></color></link>. If Yao has been Captain in this round, each stack of Heroic Mark increases her base ATK by <color=#00F6FF>{1}</color>. Bonuses and stacks are cleared at the end of the round. Whenever Yao becomes the Captain, gain <color=#00F6FF>1</color> stack of <link=\"30027\"><#FFAE07><u>Heroic Mark</u></color></link>. Captain changes for the battle: <color=#00F6FF>+1</color>.",
