  str_skill_desc_2001471 = "Deal <color=#00F6FF>150%</color> damage 2 times to random enemy units within <color=#00F6FF>3 surrounding clusters</color>. If a target sustains damage more than once, the damage for every hit after the first one is reduced by half.",
