  str_skill_desc_320147 = "Deals <color=#00F6FF>{1}%</color> damage <color=#00F6FF>8</color> times to 1 selected tile within <color=#00F6FF>3 surrounding clusters</color>, then deals an additional <color=#00F6FF>188%</color> damage to the same tile and <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_322147 = "Deals <color=#00F6FF>{1}%</color> damage <color=#00F6FF>8</color> times to 1 selected tile within <color=#00F6FF>3 surrounding clusters</color>, then deals an additional <color=#00F6FF>188%</color> damage to the same tile and <color=#00F6FF>1 surrounding cluster</color>. Reduces active skill cooldown by <color=#FFFF00>1</color> round when occupying the Captain position. Triggers up to <color=#00F6FF>3</color> times per round.",
  str_skill_passive_desc_410147 = "At the beginning of each round, Momo & Anzu will become the Captain automatically while the rest of the team retreats 1 position. Each time Momo & Anzu become the Captain, a <link=\"30030\"><#FFAE07><u>Special Kaniya Cuisine</u></color></link> will be obtained with a <color=#00F6FF>{1}</color> chance for an <color=#00F6FF>additional one</color>.",
