  str_skill_desc_3001513 = "Giles joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Uses <color=#00F6FF>120</color> sanity points to deal <color=#00F6FF>{1}%</color> DMG to enemies in the 4 adjacent tiles in a <color=#00F6FF>cross shape</color> around 1 chosen tile. Deals 2× damage if the caster's tile is selected. After an Active Skill kills a target, it can be used again to deal 2× final damage at the cost of 2× sanity points.",
  str_skill_desc_3001514 = "Giles joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Uses <color=#00F6FF>240</color> sanity points to deal <color=#00F6FF>{1}%</color> DMG to enemies in the 4 adjacent tiles in a <color=#00F6FF>cross shape</color> around 1 chosen tile. Deals 2× damage if the caster's tile is selected. After an Active Skill kills a target, it can be used again to deal 2× final damage at the cost of 2× sanity points.",
  str_skill_passive_desc_410151 = "<color=#00F6FF>Activated after killing any enemy</color> in this round: Whenever Giles deals damage, his ATK is enhanced according to the current Sanity point. The lower the Sanity point, the greater the damage, up to <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_413151 = "<color=#00F6FF>Activated after killing any enemy</color> in this round: Whenever Giles deals damage, DMG is increased according to the current Sanity. The lower the Sanity, the greater the damage increase, up to <color=#00F6FF>{1}</color>. The kill of any <color=#00F6FF>Mirage</color> additionally increases bonuses by <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_416151 = "<color=#00F6FF>Activated after killing any enemy</color> in this round: Whenever Giles deals damage, DMG is increased according to the current Sanity. The lower the Sanity, the greater the damage increase, up to <color=#00F6FF>{1}</color>. The kill of any <color=#00F6FF>Mirage</color> additionally increases bonuses by <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_430151 = "<color=#00F6FF>Activated after killing any enemy</color> in this round: Whenever Giles deals damage, his ATK is enhanced according to the current Sanity point. The lower the Sanity point, the greater the damage, up to <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_433151 = "<color=#00F6FF>Activated after killing any enemy</color> in this round: Whenever Giles deals damage, DMG is increased according to the current Sanity. The lower the Sanity, the greater the damage increase, up to <color=#00F6FF>{1}</color>. The kill of any <color=#00F6FF>Mirage</color> additionally increases bonuses by <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_436151 = "<color=#00F6FF>Activated after killing any enemy</color> in this round: Whenever Giles deals damage, DMG is increased according to the current Sanity. The lower the Sanity, the greater the damage increase, up to <color=#00F6FF>{1}</color>. The kill of any <color=#00F6FF>Mirage</color> additionally increases bonuses by <color=#00F6FF>10%</color>.",
