  str_skill_desc_300152 = "May joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Restores <color=#00F6FF>25%</color> of the lost sanity points at the cost of <color=#00F6FF>20%</color> of her current HP.",
  str_skill_desc_302152 = "May joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Restores <color=#00F6FF>25%</color> of the lost sanity points at the cost of <color=#00F6FF>15%</color> of her current HP.",
  str_skill_desc_305152 = "May's able to change the <link=\"30040\"><#FFAE07><u>sanity system</u></color></link> for this battle: More resistant to the Sanity System's debuff effects. Debuffs are also weakened. Restores <color=#00F6FF>25%</color> of the lost sanity points at the cost of <color=#00F6FF>15%</color> of her current HP.",
  str_skill_desc_2001521 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>8 tiles in an X shape</color>.",
  str_skill_desc_2001522 = "Deals <color=#00F6FF>{1}%</color> damage in an <color=#00F6FF>X shape to the maximum range</color>.",
  str_skill_desc_2001523 = "Deals <color=#00F6FF>{1}%</color> damage in an <color=#00F6FF>X shape to the maximum range</color>.",
