  str_skill_passive_desc_425152 = "For every 1 sanity point lost, restore HP equal to <color=#00F6FF>{1}</color> of May's ATK. Her DEF increases as sanity drops, up to <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_430152 = "For every 1 sanity point lost, restore HP equal to <color=#00F6FF>{1}</color> of May's ATK. The lower the sanity, the greater the recovery, up to <color=#00F6FF>100%</color>. Her DEF increases as sanity drops, up to <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_435152 = "For every 1 sanity point lost, restore HP equal to <color=#00F6FF>{1}</color> of May's ATK. The lower the sanity, the greater the recovery, up to <color=#00F6FF>100%</color>. Her DEF increases as sanity drops, up to <color=#00F6FF>100%</color>.",
  str_skill_upgrade_desc_15015212 = "Active Skill Enhancement: Restores <color=#00F6FF>25%</color> of lost sanity points at the cost of <color=#00F6FF>15%</color> of her current HP.",
