  str_skill_desc_22015012 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>3 rows</color>.",
  str_skill_desc_22015013 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 rows</color>. When Sanity drops below <color=#00F6FF>75</color> points, the triggering condition is reduced to <color=#00F6FF>15</color>. If in the <color=#00F6FF>Insane state</color>, reduce the triggering condition to <color=#00F6FF>5</color>.",
  str_skill_desc_23015011 = "Deals <color=#00F6FF>{1}%</color> DMG to <color=#00F6FF>1 row</color>. The lower the Sanity, the greater the DMG increase, up to <color=#00F6FF>80%</color>.",
  str_skill_desc_23015012 = "Deals <color=#00F6FF>{1}%</color> DMG to <color=#00F6FF>3 rows</color>. The lower the Sanity, the greater the DMG increase, up to <color=#00F6FF>80%</color>.",
  str_skill_desc_23015013 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 rows</color>. When Sanity drops below <color=#00F6FF>75</color> points, the triggering condition is reduced to <color=#00F6FF>15</color>. If in the <color=#00F6FF>Insane state</color>, reduce the triggering condition to <color=#00F6FF>5</color>. The lower the Sanity, the greater the DMG increase, up to <color=#00F6FF>80%</color>.",
  str_skill_desc_23615011 = "Deals <color=#00F6FF>{1}%</color> DMG to <color=#00F6FF>1 row</color>. The lower the Sanity, the greater the DMG increase, up to <color=#00F6FF>100%</color>.",
  str_skill_desc_23615012 = "Deals <color=#00F6FF>{1}%</color> DMG to <color=#00F6FF>3 rows</color>. The lower the Sanity, the greater the DMG increase, up to <color=#00F6FF>100%</color>.",
  str_skill_desc_23615013 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 rows</color>. When Sanity drops below <color=#00F6FF>75</color> points, the triggering condition is reduced to <color=#00F6FF>15</color>. If in the <color=#00F6FF>Insane state</color>, reduce the triggering condition to <color=#00F6FF>5</color>. The lower the Sanity, the greater the DMG increase, up to <color=#00F6FF>100%</color>.",
  str_skill_desc_3001501 = "Lenore joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Choose any 1 tile and then select another 1 within <color=#00F6FF>2 surrounding clusters</color> to generate a rectangle area, within which dealing <color=#00F6FF>333%</color> DMG to tiles. Each tile in the rectangle deducts <color=#00F6FF>3</color> sanity points. If an enemy sustains damage more than once, the subsequent effect is reduced to <color=#00F6FF>33%</color>.",
  str_skill_desc_3031501 = "Lenore joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Choose any 1 tile and then select another 1 within <color=#00F6FF>2 surrounding clusters</color> to generate a rectangle area, within which dealing <color=#00F6FF>333%</color> DMG to tiles. Each tile in the rectangle deducts <color=#00F6FF>3</color> Sanity points. If an enemy unit sustains damage more than once, the subsequent effect is reduced to <color=#00F6FF>33%</color>. Every time when an Active Skill causes DMG, Lenore's Max HP is boosted by <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_410150 = "If not in the <color=#00F6FF>calm state</color> at the start of each round, deal DMG equal to <color=#00F6FF>{1}</color> of the team's Max HP to all enemies. The lower the Sanity, the higher the damage increase, up to <color=#00F6FF>{2}</color> of the team's Max HP.",
