  str_skill_desc_290270111 = "Forsakin summons Dark Region on the field, limiting Aurorians' movement.",
  str_skill_upgrade_desc_16015413 = "Chain Combo Enhancement: The times of the Chain Combo attack will always be <color=#00F6FF>+1</color>.",
  str_skill_upgrade_desc_16015416 = "Chain Combo Enhancement: Increases Chain Combo damage by <color=#FFFF00>20%</color>.",
  str_skill_name_200154 = "Piercing Deluge",
