  str_skill_name_320154 = "Target Secured",
  str_skill_name_330154 = "Target Secured",
  str_skill_desc_300154 = "Selects and <color=#00F6FF>locks on</color> 1 enemy. There can be a maximum of <color=#00F6FF>1</color> target being locked on at the same time. As long as the locked-on target is alive, Vice: Keen Sight's Chain Combos will always <color=#00F6FF>target it</color>. If the selected enemy is already locked on, deals <color=#00F6FF>100%</color> damage to it once instead.",
  str_skill_desc_330154 = "Selects and <color=#00F6FF>locks on</color> 1 enemy. There can be a maximum of <color=#00F6FF>1</color> target being locked on at the same time. As long as the locked-on target is alive, Vice: Keen Sight's Chain Combos will always <color=#00F6FF>target it</color>. If the selected enemy is already locked on, deals <color=#00F6FF>100%</color> damage to it once instead. Every stack of <link=\"30042\"><#FFAE07><u>Timeless Mark</u></color></link> on the target increases damage dealt to it by an additional <color=#00F6FF>5%</color>.",
  str_skill_desc_200154 = "Deals <color=#00F6FF>100%</color> damage once to the nearest target for every <color=#00F6FF>3</color> consecutive tiles traveled. The damage is not affected by the number of connected tiles.",
  str_skill_desc_203154 = "Deals <color=#00F6FF>100%</color> damage once to the nearest target for every <color=#00F6FF>3</color> consecutive tiles traveled. The damage is not affected by the number of connected tiles. The times of the Chain Combo attack will always be <color=#00F6FF>+1</color>.",
  str_skill_desc_206154 = "Deals <color=#00F6FF>100%</color> damage once to the nearest target for every <color=#00F6FF>3</color> consecutive tiles traveled. The damage is not affected by the number of connected tiles. The times of the Chain Combo attack will always be <color=#00F6FF>+1</color>.",
  str_skill_passive_name_410154 = "Timeless Insignia",
  str_skill_passive_name_420154 = "Timeless Insignia",
  str_skill_passive_desc_410154 = "Inflicts <link=\"30042\"><#FFAE07><u>Timeless Mark</u></color></link> on locked-on target. Every stack of <link=\"30042\"><#FFAE07><u>Timeless Mark</u></color></link> increases the damage Vice: Keen Sight deals to the target by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420154 = "Inflicts <link=\"30042\"><#FFAE07><u>Timeless Mark</u></color></link> on locked-on target. Every stack of <link=\"30042\"><#FFAE07><u>Timeless Mark</u></color></link> increases the damage Vice: Keen Sight deals to the target by <color=#00F6FF>{1}</color>. Vice: Keen Sight applies 1 additional stack of Timeless Mark on the locked-on target for every <color=#00F6FF>3%</color> damage it deals to allies.",
