  str_skill_name_336153 = "Illuminated Finale",
  str_skill_desc_300153 = "Selects any <color=#00F6FF>4</color> tiles and summons an Air Raid Beacon that lasts for <color=#00F6FF>2</color> rounds, and then enters <color=#00F6FF>Finality state</color> for 2 rounds. While in the Finality state, normal attacks extend to <color=#00F6FF>diagonal tiles</color>. Meanwhile, Chain Combo skill deals an additional half of the current damage to the tile where the Air Raid Beacon is located and 4 surrounding tiles. When dealing damage multiple times to the same tile, each following final damage is reduced by <color=#00F6FF>20%</color>.",
  str_skill_desc_306153 = "Selects any <color=#00F6FF>4</color> tiles and summons an Air Raid Beacon that lasts for <color=#00F6FF>2</color> rounds, and then enters <color=#00F6FF>Finality state</color> for 2 rounds. While in the Finality state, normal attacks extend to <color=#00F6FF>diagonal tiles</color>. Meanwhile, Chain Combo skill deals an additional half of the current damage to the tile where the Air Raid Beacon is located and 4 surrounding tiles. When dealing damage multiple times to the same tile, each following final damage is reduced by <color=#00F6FF>20%</color>.",
  str_skill_desc_320153 = "Selects any <color=#00F6FF>4</color> tiles and summons an Air Raid Beacon that lasts for <color=#00F6FF>2</color> rounds, and then enters <color=#00F6FF>Finality state</color> for 2 rounds. While in the Finality state, normal attacks extend to <color=#00F6FF>diagonal tiles</color>. Meanwhile, Chain Combo skill deals an additional half of the current damage to the tile where the Air Raid Beacon is located and 4 surrounding tiles. When dealing damage multiple times to the same tile, each following final damage is reduced by <color=#00F6FF>20%</color>. Gains an additional <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Finale</u></color></link> regardless of the limit while in Finality state.",
  str_skill_desc_326153 = "Selects any <color=#00F6FF>4</color> tiles and summons an Air Raid Beacon that lasts for <color=#00F6FF>2</color> rounds, and then enters <color=#00F6FF>Finality state</color> for 2 rounds. While in the Finality state, normal attacks extend to <color=#00F6FF>diagonal tiles</color>. Meanwhile, Chain Combo skill deals an additional half of the current damage to the tile where the Air Raid Beacon is located and 4 surrounding tiles. When dealing damage multiple times to the same tile, each following final damage is reduced by <color=#00F6FF>20%</color>. Gains an additional <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Finale</u></color></link> regardless of the limit while in Finality state.",
  str_skill_desc_330153 = "Selects any <color=#00F6FF>4</color> tiles and summons an Air Raid Beacon that lasts for <color=#00F6FF>2</color> rounds, and then enters <color=#00F6FF>Finality state</color> for 2 rounds. While in the Finality state, normal attacks extend to <color=#00F6FF>diagonal tiles</color>. Meanwhile, Chain Combo skill deals an additional half of the current damage to the tile where the Air Raid Beacon is located and 4 surrounding tiles. When dealing damage multiple times to the same tile, each following final damage is reduced by <color=#00F6FF>20%</color>. Gains an additional <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Finale</u></color></link> regardless of the limit while in Finality state.",
  str_skill_desc_336153 = "Selects any <color=#00F6FF>4</color> tiles and summons an Air Raid Beacon that lasts for <color=#00F6FF>2</color> rounds, and then enters <color=#00F6FF>Finality state</color> for 2 rounds. While in the Finality state, normal attacks extend to <color=#00F6FF>diagonal tiles</color>. Meanwhile, Chain Combo skill deals an additional half of the current damage to the tile where the Air Raid Beacon is located and 4 surrounding tiles. When dealing damage multiple times to the same tile, each following final damage is reduced by <color=#00F6FF>20%</color>. Gains an additional <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Finale</u></color></link> regardless of the limit while in Finality state.",
  str_skill_desc_2001531 = "Deals <color=#00F6FF>{1}%</color> damage to the 3 nearest enemies within <color=#00F6FF>3 surrounding clusters</color>.",
  str_skill_desc_2001532 = "Deals <color=#00F6FF>{1}%</color> damage to the 4 nearest enemies within <color=#00F6FF>4 surrounding clusters</color>.",
  str_skill_desc_2001533 = "Deals <color=#00F6FF>{1}%</color> damage to all enemies within <color=#00F6FF>4 surrounding clusters</color>.",
  str_skill_passive_name_410153 = "Power of Illumina",
  str_skill_passive_name_413153 = "Power of Illumina",
  str_skill_passive_name_420153 = "Power of Illumina",
  str_skill_passive_name_423153 = "Power of Illumina",
  str_skill_passive_name_426153 = "Power of Illumina",
  str_skill_passive_name_430153 = "Power of Illumina",
  str_skill_passive_name_433153 = "Power of Illumina",
  str_skill_passive_name_436153 = "Power of Illumina",
  str_skill_passive_desc_410153 = "Gains <link=\"30043\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_413153 = "Gains <link=\"30043\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>{1}</color>. Upon entering combat, instantly gains <color=#00F6FF>2</color> Finale.",
  str_skill_passive_desc_420153 = "Gains <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>{1}</color>. Whenever passing through a Dark Tile, gains <color=#00F6FF>1</color> temporary Finale that can exceed the Finale limit. This additional Finale disappears when entering Aurora Time, or at the end of the round.",
  str_skill_passive_desc_423153 = "Gains <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>{1}</color>. Upon entering combat, instantly gains <color=#00F6FF>2</color> Finale. Whenever passing through a Dark Tile, gains <color=#00F6FF>1</color> temporary Finale that can exceed the Finale limit. This additional Finale disappears when entering Aurora Time, or at the end of the round.",
  str_skill_passive_desc_426153 = "Gains <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>{1}</color>. Upon entering combat, instantly gains <color=#00F6FF>2</color> Finale. Whenever passing through a Dark Tile, gains <color=#00F6FF>1</color> temporary Finale that can exceed the Finale limit, and increases Chain Combo damage factor by <color=#00F6FF>2%</color>. This additional Finale and Chain Combo bonus disappear when entering Aurora Time, or at the end of the round.",
  str_skill_passive_desc_430153 = "Gains <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>{1}</color>. <color=#00F6FF>Thunder</color> or <color=#00F6FF>Illumina Federation</color> Aurorians gain 50% Finale</color> bonus based on their <color=#00F6FF>ATK. Whenever passing through a Dark Tile, gains <color=#00F6FF>1</color> temporary Finale that can exceed the Finale limit. This additional Finale disappears when entering Aurora Time, or at the end of the round.",
  str_skill_passive_desc_433153 = "Gains <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>{1}</color>. <color=#00F6FF>Thunder</color> or <color=#00F6FF>Illumina Federation</color> Aurorians gain 50% Finale</color> bonus based on their <color=#00F6FF>ATK. Upon entering combat, instantly gains <color=#00F6FF>2</color> Finale. Whenever passing through a Dark Tile, gains <color=#00F6FF>1</color> temporary Finale that can exceed the Finale limit. This additional Finale disappears when entering Aurora Time, or at the end of the round.",
  str_skill_passive_desc_436153 = "Gains <link=\"300442\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>{1}</color>. <color=#00F6FF>Thunder</color> or <color=#00F6FF>Illumina Federation</color> Aurorians gain 50% Finale</color> bonus based on their <color=#00F6FF>ATK. Upon entering combat, instantly gains <color=#00F6FF>2</color> Finale. Whenever passing through a Dark Tile, gains <color=#00F6FF>1</color> temporary Finale that can exceed the Finale limit, and increases Chain Combo damage factor by <color=#00F6FF>2%</color>. This additional Finale and Chain Combo bonus disappear when entering Aurora Time, or at the end of the round.",
  str_skill_upgrade_refine_desc_16015311 = "Active Skill Enhancement: Gains <color=#00F6FF>6</color> temporary Finale after entering the Finality state.",
  str_skill_upgrade_refine_desc_16015312 = "Chain Combo Enhancement: Increases damage by <color=#00F6FF>10%</color>.",
  str_skill_upgrade_refine_desc_16015313 = "Active Skill Enhancement: If the Chain Combo deals multiple instances of damage to the same tile after entering the Finality state, each following final damage is reduced by <color=#00F6FF>15%</color>.",
  str_skill_desc_2501531 = "Deals <color=#00F6FF>150%</color> damage to the 3 nearest enemies within <color=#00F6FF>3 surrounding clusters</color>.",
  str_skill_desc_2501532 = "Deals <color=#00F6FF>160%</color> damage to the 4 nearest enemies within <color=#00F6FF>4 surrounding clusters</color>.",
  str_skill_desc_2501533 = "Deals <color=#00F6FF>170%</color> damage to all enemies within <color=#00F6FF>4 surrounding clusters</color>.",
  str_skill_desc_340153 = "Selects any <color=#00F6FF>4</color> tiles and summons an Air Raid Beacon that lasts for <color=#00F6FF>2</color> rounds, and then enters <color=#00F6FF>Finality state</color> for 2 rounds. While in the Finality state, normal attacks extend to <color=#00F6FF>diagonal tiles</color>. Meanwhile, Chain Combo skill deals an additional half of the current damage to the tile where the Air Raid Beacon is located and 4 surrounding tiles. When dealing damage multiple times to the same tile, each following final damage is reduced by <color=#00F6FF>20%</color>. Gains an additional <color=#00F6FF>6</color> <link=\"300443\"><#FFAE07><u>Finale</u></color></link> regardless of the limit while in Finality state.",
  str_skill_desc_360153 = "Selects any <color=#00F6FF>4</color> tiles and summons an Air Raid Beacon that lasts for <color=#00F6FF>2</color> rounds, and then enters <color=#00F6FF>Finality state</color> for 2 rounds. While in the Finality state, normal attacks extend to <color=#00F6FF>diagonal tiles</color>. Meanwhile, Chain Combo skill deals an additional half of the current damage to the tile where the Air Raid Beacon is located and 4 surrounding tiles. When dealing damage multiple times to the same tile, each following final damage is reduced by <color=#00F6FF>15%</color>. Gains an additional <color=#00F6FF>6</color> <link=\"300443\"><#FFAE07><u>Finale</u></color></link> regardless of the limit while in Finality state.",
  str_skill_passive_desc_450153 = "Gains <link=\"300443\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>3%</color>. <color=#00F6FF>Thunder</color> or <color=#00F6FF>Illumina Federation</color> Aurorians gain 50% Finale</color> bonus based on their <color=#00F6FF>ATK. Whenever passing through a Dark Tile, gains <color=#00F6FF>1</color> temporary Finale that can exceed the Finale limit. This additional Finale disappears when entering Aurora Time, or at the end of the round.",
  str_skill_passive_desc_453153 = "Gains <link=\"300443\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>3%</color>. <color=#00F6FF>Thunder</color> or <color=#00F6FF>Illumina Federation</color> Aurorians gain 50% Finale</color> bonus based on their <color=#00F6FF>ATK. Upon entering combat, instantly gains <color=#00F6FF>2</color> Finale. Whenever passing through a Dark Tile, gains <color=#00F6FF>1</color> temporary Finale that can exceed the Finale limit. This additional Finale disappears when entering Aurora Time, or at the end of the round.",
  str_skill_passive_desc_456153 = "Gains <link=\"300443\"><#FFAE07><u>Finale</u></color></link>, and each Finale increases ATK by <color=#00F6FF>3%</color>. <color=#00F6FF>Thunder</color> or <color=#00F6FF>Illumina Federation</color> Aurorians gain 50% Finale</color> bonus based on their <color=#00F6FF>ATK. Upon entering combat, instantly gains <color=#00F6FF>2</color> Finale. Whenever passing through a Dark Tile, gains <color=#00F6FF>1</color> temporary Finale that can exceed the Finale limit, and increases Chain Combo damage factor by <color=#00F6FF>2%</color>. This additional Finale and Chain Combo bonus disappear when entering Aurora Time, or at the end of the round.",
  str_skill_name_290230101 = "Claudia: Meteor Smash",
  str_skill_name_290230102 = "Claudia: Meteor Smash",
  str_skill_name_290230103 = "Claudia: Meteor Smash",
  str_skill_name_290230104 = "Claudia: Meteor Smash",
  str_skill_name_290230201 = "Claudia: Leaping Cleave",
  str_skill_name_290230202 = "Claudia: Leaping Cleave",
  str_skill_name_290230203 = "Claudia: Leaping Cleave",
  str_skill_name_290230301 = "Claudia: Sever",
  str_skill_name_290230401 = "Emerging Platform",
  str_skill_name_290240101 = "Asher: Assault",
  str_skill_desc_290230101 = "When Claudia is standing on the ground, all the platforms within a cross-shaped range around the enemy are summoned to ram together, dealing damage multiple times to the enemy.",
  str_skill_desc_290230102 = "When Claudia is standing on a platform, all the platforms within a cross-shaped range around the enemy are summoned to ram together. If Claudia is within this range, the enemy will be stunned.",
  str_skill_desc_290230103 = "When Claudia is standing on Asher, all the platforms within a cross-shaped range around the enemy are summoned to ram together. If Asher is also within this range, the enemy will be stunned and knocked back.",
  str_skill_desc_290230104 = "When there are no platforms within a cross-shaped range around the enemy, Claudia summons 4 platforms at random locations within 5×5 tiles in the center of the field. Then generates a platform at the farthest position from the enemy on the field and teleports there.",
  str_skill_desc_290230201 = "If the enemy is within attack range, Claudia teleports next to the enemy, dealing severe damage and then retreats a short distance. If no enemies are within attack range, Claudia generates a platform within 5×5 tiles in the center of the field and teleports to the farthest position from the enemy on the field.",
  str_skill_desc_290230202 = "If the enemy is within attack range, Claudia teleports next to the enemy, dealing severe damage and then retreats a short distance. If no enemies are within attack range, Claudia generates a platform within 5×5 tiles in the center of the field and teleports to the farthest position from the enemy on the field.",
  str_skill_desc_290230203 = "If the enemy is within attack range, Claudia teleports next to the enemy, dealing severe damage and then retreats a short distance. If no enemies are within attack range, Claudia generates a platform within 5×5 tiles in the center of the field and teleports to the farthest position from the enemy on the field.",
  str_skill_desc_290230301 = "Claudia generates a platform in the center of the field and on the enemy tile respectively. Then teleports to the platform and severs, dealing full-screen damage to all the enemies.",
  str_skill_desc_290230401 = "At the start of the round, Claudia summons at most 10 platforms at the edge of the field.",
  str_skill_desc_290240101 = "Asher approaches an enemy within attack range and attacks once, crushing all platforms along the way. If no enemies are within attack range, Asher remains stationary on the spot.",
  str_skill_name_290250101 = "Immolation Finale",
  str_skill_desc_290250101 = "Minos moves randomly on the field for a period of time and resets all tiles traversed. After moving, Minos shoots the player, dealing great damage once.",
  str_skill_name_290250102 = "Phantom Attack",
  str_skill_desc_290250102 = "If Minos passes an enhanced tile, a phantom will be summoned on the enhanced tile to deal single damage to the player. Damage dealt by the phantom increases as Minos' Mark stacks.",
  str_skill_name_290250201 = "Restoration Phantom",
  str_skill_desc_290250201 = "Minos absorbs all the enhanced and weakened tiles on the board, and then deals damage to the player. Minos deals damage 1 extra time for each enhanced tile he absorbs. Damage dealt increases the more Minos Mark stacks he has.",
  str_skill_name_390250101 = "Nefarious - Phantom Attack",
  str_skill_desc_390250101 = "Nefarious Minos chooses a path with the largest number of weakened tiles and moves 5 tiles, absorbing enhanced and weakened tiles along his path. Each time he absorbs weakened tiles, a phantom will be summoned to deal single damage to the player. If there is no weakened tile along his path or on the board, Minos will summon 7 weakened tiles within 3 surrounding clusters.",
  str_skill_name_390250102 = "Nefarious - Immolation Finale",
  str_skill_desc_390250102 = "Nefarious - Minos locks on to the target and shoots, dealing full-screen damage.",
  str_skill_name_390310106 = "Nefarious - Sweet Kiss",
  str_skill_desc_390310106 = "Nefarious Barbara moves to the farthest location from the target by connecting tiles, then deals large area damage excluding safe zones and breaks red tiles outside the safe zones.",
  str_skill_name_390310107 = "Nefarious - Final Note",
  str_skill_desc_390310107 = "Nefarious Barbara moves to the farthest location from the target by connecting tiles, then summons allies in the center of the board, dealing full-screen damage and knocking targets back.",
