  str_skill_desc_3351652 = "Converts the <color=#00F6FF>5</color> nearest Green tiles to Yellow and leaves behind a <color=#00F6FF>Solar Arrow Mine</color>. If the Active Skill is ready in the last round, increases the tile-converting count by <color=#00F6FF>1</color> in this round.",
  str_skill_passive_name_400165 = "Solar Arrow Domain",
