  str_skill_desc_323164 = "Consumes <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Souls</u></color></link> to teleport to any tile within <color=#00F6FF>16 tiles in a cross shape</color>, then converts <color=#00F6FF>the 2 tiles in front and behind</color> the unit to Red tiles and deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>tiles along the path and 1 tile in front</color>.",
  str_skill_desc_326164 = "Consumes <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Souls</u></color></link> to teleport to any tile within <color=#00F6FF>16 tiles in a cross shape</color>, then converts <color=#00F6FF>the 2 tiles in front and behind</color> the unit to Red tiles and deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>tiles along the path and 1 tile in front</color>.",
  str_skill_desc_330164 = "Consumes <color=#00F6FF>2</color> <link=\"30053\"><#FFAE07><u>Smoldering Souls</u></color></link> to teleport to any tile within <color=#00F6FF>16 tiles in a cross shape</color>, then converts <color=#00F6FF>the 2 tiles in front and behind</color> the unit to Red tiles and deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>tiles along the way and 1 tile in front</color>. Gains <color=#00F6FF>1</color> <link=\"30053\"><#FFAE07><u>Smoldering Soul</u></color></link> if an enemy is hit. Triggers up to <color=#00F6FF>1</color> time in each round.",
  str_skill_desc_333164 = "Consumes <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Souls</u></color></link> to teleport to any tile within <color=#00F6FF>16 tiles in a cross shape</color>, then converts <color=#00F6FF>the 2 tiles in front and behind</color> the unit to Red tiles and deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>tiles along the way and 1 tile in front</color>. Gains <color=#00F6FF>1</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> if an enemy is hit. Triggers up to <color=#00F6FF>1</color> time in each round.",
  str_skill_desc_336164 = "Consumes <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Souls</u></color></link> to teleport to any tile within <color=#00F6FF>16 tiles in a cross shape</color>, then converts <color=#00F6FF>the 2 tiles in front and behind</color> the unit to Red tiles and deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>tiles along the way and 1 tile in front</color>. Gains <color=#00F6FF>1</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> if an enemy is hit. Triggers up to <color=#00F6FF>2</color> times in each round.",
