  str_skill_desc_2001682 = "Deals <color=#00F6FF>{1}%</color> damage to the 3 nearest enemies, then generates a <link=\"30061\"><#FFAE07><u>Sunshower Mark</u></color></link> on 1 random tile occupied by an enemy.",
  str_skill_desc_2001683 = "Deals <color=#00F6FF>{1}%</color> damage to the 4 nearest enemies, then generates a <link=\"30061\"><#FFAE07><u>Sunshower Mark</u></color></link>on 1 random tile occupied by an enemy.",
  str_skill_desc_300168 = "Activates all <link=\"30061\"><#FFAE07><u>Sunshower Marks</u></color></link> on the field and deals <color=#00F6FF>240%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> around them. If a target sustains damage more than once, the damage for every hit after the first one is reduced, down to <color=#00F6FF>10%</color> of the original damage.",
  str_skill_desc_320168 = "Activates all <link=\"30061\"><#FFAE07><u>Sunshower Marks</u></color></link> on the field and deals <color=#00F6FF>240%</color> damage to <color=#00F6FF>9 tiles in a square shape</color> around them. If a target sustains damage more than once, the damage for every hit after the first one is reduced, down to <color=#00F6FF>10%</color> of the original damage.",
  str_skill_desc_330168 = "Activates all <link=\"30061\"><#FFAE07><u>Sunshower Marks</u></color></link> on the field and deals <color=#00F6FF>240%</color> damage to <color=#00F6FF>9 tiles in a square shape</color> around them. If a target sustains damage more than once, the damage for every hit after the first one is reduced, down to <color=#00F6FF>10%</color> of the original damage. If any tile on the field is occupied by <color=#00F6FF>3</color> activated marks but no Sunshower Mark, generates 1 new Sunshower Mark on that tile.",
