  str_skill_desc_300167 = "Jeno starts the battle with the <link=\"30058\"><#FFAE07><u>Origin Deck</u></color></link> and the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Gains 1 random Origin Card for every <color=#00F6FF>{1}</color> Sanity consumed. When cast again in the same round, increases the consumption by <color=#00F6FF>5</color>.",
  str_skill_desc_303167 = "Jeno starts the battle with the <link=\"30059\"><#FFAE07><u>Origin Deck</u></color></link> and the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Gains 1 random Origin Card for every <color=#00F6FF>{1}</color> Sanity consumed. When cast again in the same round, increases the consumption by <color=#00F6FF>5</color>.",
  str_skill_desc_306167 = "Jeno starts the battle with the <link=\"30060\"><#FFAE07><u>Origin Deck</u></color></link> and the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Gains 1 random Origin Card for every <color=#00F6FF>{1}</color> Sanity consumed. When cast again in the same round, increases the consumption by <color=#00F6FF>5</color>.",
  str_skill_desc_320167 = "Jeno starts the battle with the <link=\"30058\"><#FFAE07><u>Origin Deck</u></color></link> and the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Gains 1 random Origin Card for every <color=#00F6FF>{1}</color> Sanity consumed. When cast again in the same round, increases the consumption by <color=#00F6FF>5</color>. For Aurorians simultaneously enhanced by Luminous Cluster and Astronomical Transit, the lower the Sanity, the higher the ATK bonus, up to <color=#00F6FF>66.6%</color>.",
  str_skill_desc_323167 = "Jeno starts the battle with the <link=\"30059\"><#FFAE07><u>Origin Deck</u></color></link> and the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Gains 1 random Origin Card for every <color=#00F6FF>{1}</color> Sanity consumed. When cast again in the same round, increases the consumption by <color=#00F6FF>5</color>. For Aurorians simultaneously enhanced by Luminous Cluster and Astronomical Transit, the lower the Sanity, the higher the ATK bonus, up to <color=#00F6FF>66.6%</color>.",
  str_skill_desc_326167 = "Jeno starts the battle with the <link=\"30060\"><#FFAE07><u>Origin Deck</u></color></link> and the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Gains 1 random Origin Card for every <color=#00F6FF>{1}</color> Sanity consumed. When cast again in the same round, increases the consumption by <color=#00F6FF>5</color>. For Aurorians simultaneously enhanced by Luminous Cluster and Astronomical Transit, the lower the Sanity, the higher the ATK bonus, up to <color=#00F6FF>66.6%</color>.",
  str_skill_passive_name_410167 = "Change of Heart",
  str_skill_passive_desc_410167 = "When casting Origin Deck, restores the team's HP by <color=#00F6FF>{1}</color> of Jeno's basic ATK. This effect is not affected by the Sanity System. The lower the team's HP, the higher the recovery effect, up to a 100% bonus.",
  str_skill_passive_name_413167 = "Change of Heart",
  str_skill_passive_desc_413167 = "When casting Origin Deck, restores the team's HP by <color=#00F6FF>{1}</color> of Jeno's basic ATK. This effect is not affected by the Sanity System. The lower the team's HP, the higher the recovery effect, up to a 100% bonus. Gains <color=#00F6FF>2</color> random cards at the beginning of the battle.",
  str_skill_passive_name_416167 = "Change of Heart",
  str_skill_passive_desc_416167 = "When casting Origin Deck, restores the team's HP by <color=#00F6FF>{1}</color> of Jeno's basic ATK. This effect is not affected by the Sanity System. The lower the team's HP, the higher the recovery effect, up to a 100% bonus. Gains <color=#00F6FF>2</color> random cards at the beginning of the battle.",
  str_skill_passive_name_430167 = "Change of Heart",
  str_skill_passive_desc_430167 = "When casting Origin Deck, restores the team's HP by <color=#00F6FF>{1}</color> of Jeno's basic ATK. This effect is not affected by the Sanity System. The lower the team's HP, the higher the recovery effect, up to a 100% bonus. Gains 1 random card when entering Aurora Time.",
  str_skill_passive_name_433167 = "Change of Heart",
  str_skill_passive_desc_433167 = "When casting Origin Deck, restores the team's HP by <color=#00F6FF>{1}</color> of Jeno's basic ATK. This effect is not affected by the Sanity System. The lower the team's HP, the higher the recovery effect, up to a 100% bonus. Gains <color=#00F6FF>2</color> random cards at the beginning of the battle, and gains 1 random card when entering Aurora Time.",
  str_skill_passive_name_436167 = "Change of Heart",
  str_skill_passive_desc_436167 = "When casting Origin Deck, restores the team's HP by <color=#00F6FF>{1}</color> of Jeno's basic ATK. This effect is not affected by the Sanity System. The lower the team's HP, the higher the recovery effect, up to a 100% bonus. Gains <color=#00F6FF>2</color> random cards at the beginning of the battle, and gains 1 random card when entering Aurora Time.",
