  str_skill_desc_30016740 = "Captain changes for the battle +1. Recovers <color=#00F6FF>18%</color> of lost Sanity.",
  str_skill_name_10071413 = "Sanity Fluctuation",
  str_skill_desc_10071413 = "Tentaclaws will influence Aurorian Sanity. At the beginning of each round, each existing Tentaclaw reduces Sanity by 2, and the death of each Tentaclaw restores Sanity by 3.",
  str_skill_upgrade_desc_16016613 = "Active Skill Enhancement: Gains <color=#00F6FF>1</color> point of Bait Value at the beginning of each wave.",
  str_skill_upgrade_desc_16016616 = "Active Skill Enhancement: For the <color=#00F6FF>2nd/3rd</color> round that a Hunt Mark exists, Kyllo deals <color=#00F6FF>350%/500%</color> damage.",
  str_skill_passive_name_410166 = "Swelling Tides",
  str_skill_passive_name_430166 = "Swelling Tides",
  str_skill_passive_desc_410166 = "Fia glides quickly on <color=#00F6FF>Blue</color> tiles, dealing damage to adjacent enemies. When <link=\"30057\"><#FFAE07><u>turning</u></color></link>, deals damage to <color=#00F6FF>1 surrounding cluster</color>. Adds a Damp effect to the target that lasts for 1 round: increases counter elemental damage factor by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430166 = "Fia slides quickly on <color=#00F6FF>Blue</color> tiles, dealing damage to adjacent enemies. When <link=\"30057\"><#FFAE07><u>turning</u></color></link>, deals damage to <color=#00F6FF>1 surrounding cluster</color>. Adds a Damp effect to the target that lasts for 1 round: increases counter elemental damage factor by <color=#00F6FF>{1}</color>. Damp effect increases <color=#00F6FF>50%</color> to Fire enemies.",
  str_skill_name_300166 = "The Kyllo Strategy",
  str_skill_name_320166 = "The Kyllo Strategy",
  str_skill_name_303166 = "The Kyllo Strategy",
  str_skill_name_306166 = "The Kyllo Strategy",
