  str_skill_desc_320166 = "Consumes <color=#00F6FF>1</color> point of <link=\"30055\"><#FFAE07><u>Bait Value</u></color></link> to place 1 Hunt Mark on any tile, or select 1 Hunt Mark to release Kyllo. While the Hunt Mark is active for <color=#00F6FF>0/1/2/3</color> round(s), Kyllo attacks the <color=#00F6FF>Hunt Mark tile/5 tiles in a cross shape/13 tiles in a diamond shape/25 tiles in a square shape</color>, dealing <color=#00F6FF>150%/200%/250%/300%</color> damage. Reduces target's basic DEF by <color=#00F6FF>5%</color> for the round. Effect can be stacked.",
  str_skill_desc_303166 = "Consumes <color=#00F6FF>1</color> point of <link=\"30056\"><#FFAE07><u>Bait Value</u></color></link> to place 1 Hunt Mark on any tile, or select 1 Hunt Mark to release Kyllo. While the Hunt Mark is active for <color=#00F6FF>0/1/2/3</color> round(s), Kyllo attacks the <color=#00F6FF>Hunt Mark tile/5 tiles in a cross shape/13 tiles in a diamond shape/25 tiles in a square shape</color>, dealing <color=#00F6FF>150%/200%/250%/300%</color> damage.",
  str_skill_desc_306166 = "Consumes <color=#00F6FF>1</color> point of <link=\"30056\"><#FFAE07><u>Bait Value</u></color></link> to place 1 Hunt Mark on any tile, or select 1 Hunt Mark to release Kyllo. While the Hunt Mark is active for <color=#00F6FF>0/1/2/3</color> round(s), Kyllo attacks the <color=#00F6FF>Hunt Mark tile/5 tiles in a cross shape/13 tiles in a diamond shape/25 tiles in a square shape</color>, dealing <color=#00F6FF>150%/200%/350%/500%</color> damage.",
  str_skill_desc_323166 = "Consumes <color=#00F6FF>1</color> point of <link=\"30056\"><#FFAE07><u>Bait Value</u></color></link> to place 1 Hunt Mark on any tile, or select 1 Hunt Mark to release Kyllo. While the Hunt Mark is active for <color=#00F6FF>0/1/2/3</color> round(s), Kyllo attacks the <color=#00F6FF>Hunt Mark tile/5 tiles in a cross shape/13 tiles in a diamond shape/25 tiles in a square shape</color>, dealing <color=#00F6FF>150%/200%/250%/300%</color> damage. Reduces target's basic DEF by <color=#00F6FF>5%</color> for the round. Effect can be stacked.",
  str_skill_desc_326166 = "Consumes <color=#00F6FF>1</color> point of <link=\"30056\"><#FFAE07><u>Bait Value</u></color></link> to place 1 Hunt Mark on any tile, or select 1 Hunt Mark to release Kyllo. While the Hunt Mark is active for <color=#00F6FF>0/1/2/3</color> round(s), Kyllo attacks the <color=#00F6FF>Hunt Mark tile/5 tiles in a cross shape/13 tiles in a diamond shape/25 tiles in a square shape</color>, dealing <color=#00F6FF>150%/200%/350%/500%</color> damage. Reduces target's basic DEF by <color=#00F6FF>5%</color> for the round. Effect can be stacked.",
