  str_skill_desc_2301731 = "Deals <color=#00F6FF>140%</color> damage to the nearest and farthest targets, but subsequent damage dealt to the same targets are <color=#00F6FF>halved</color>. Summons <color=#00F6FF>up to 1</color> <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> at the feet of the targets.",
  str_skill_desc_2301732 = "Deals <color=#00F6FF>160%</color> damage to the nearest and farthest targets, but subsequent damage dealt to the same targets are <color=#00F6FF>halved</color>. Summons <color=#00F6FF>up to 1</color> <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> at the feet of the targets.",
  str_skill_desc_2301733 = "Deals <color=#00F6FF>180%</color> damage to the nearest and farthest targets, but subsequent damage dealt to the same targets are <color=#00F6FF>halved</color>. Summons <color=#00F6FF>up to 1</color> <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> at the feet of the targets.",
