  str_skill_passive_name_423173 = "Omnipotent Unleashing",
  str_skill_passive_desc_410173 = "Immediately deals <color=#00F6FF>{1}</color> damage to <color=#00F6FF>1</color> random target on the field whenever the team obtains <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including <link=\"30065\"><#FFAE07><u>absorbing</u></color></link>).",
  str_skill_passive_desc_420173 = "Immediately deals <color=#00F6FF>{1}</color> damage to <color=#00F6FF>1</color> random target on the field whenever the team obtains <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including <link=\"30065\"><#FFAE07><u>absorption</u></color></link>). Starts the battle with <color=#00F6FF>33</color> Mortal Mark stacks and reduces <color=#00F6FF>1</color> stack for every enhanced tile obtained. Minos enters Minotaur State when all Marks have been removed, increasing his basic ATK by <color=#00F6FF>20%</color>, allowing his normal attacks to hit diagonal tiles, increasing Equipment Skill damage to <color=#00F6FF>2.5</color> times, and allowing his Chain Combo to deal normal damage when hitting the same target again.",
  str_skill_passive_desc_423173 = "Immediately deals <color=#00F6FF>{1}</color> damage to <color=#00F6FF>1</color> random target on the field whenever the team obtains <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including <link=\"30065\"><#FFAE07><u>absorption</u></color></link>). Starts the battle with <color=#00F6FF>33</color> Mortal Mark stacks and reduces <color=#00F6FF>1</color> stack for every enhanced tile obtained. Minos enters Minotaur State when all Marks have been removed, increasing his basic ATK by <color=#00F6FF>25%</color>, allowing his normal attacks to hit diagonal tiles, increasing Equipment Skill damage to <color=#00F6FF>2.5</color> times, and allowing his Chain Combo to deal normal damage when hitting the same target again.",
