  str_skill_desc_2001721 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. If standing outside a <color=#00F6FF>dazzling array</color>, generates a dazzling array spanning <color=#00F6FF>1 surrounding cluster</color> at the current location.",
  str_skill_desc_2001722 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. If standing outside a <color=#00F6FF>dazzling array</color>, generates a dazzling array spanning <color=#00F6FF>1 surrounding cluster</color> at the current location.",
  str_skill_desc_2001723 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>12 tiles in a diamond shape</color>. If standing outside a <color=#00F6FF>dazzling array</color>, generates a dazzling array spanning <color=#00F6FF>12 tiles in a diamond shape</color> at the current location.",
  str_skill_desc_3001721 = "Teleports to any location within a <link=\"30066\"><#FFAE07><u>dazzling array</u></color></link>. There can only be <color=#00F6FF>2</color> dazzling arrays on the field at any time.",
  str_skill_desc_3201721 = "Teleports to any location within a <link=\"30066\"><#FFAE07><u>dazzling array</u></color></link> and deals <color=#00F6FF>{1}%</color> damage to tiles within the span of the <color=#00F6FF>dazzling array</color>. There can only be <color=#00F6FF>2</color> dazzling arrays on the field at any time.",
  str_skill_desc_3031721 = "Teleports to any location within a <link=\"30067\"><#FFAE07><u>dazzling array</u></color></link>. There can only be <color=#00F6FF>3</color> dazzling arrays on the field at any time.",
  str_skill_desc_3231721 = "Teleports to any location within a <link=\"30067\"><#FFAE07><u>dazzling array</u></color></link> and deals <color=#00F6FF>{1}%</color> damage to tiles within the span of the <color=#00F6FF>dazzling array</color>. There can only be <color=#00F6FF>3</color> dazzling arrays on the field at any time.",
  str_skill_desc_3061721 = "Teleports to any location within a <link=\"30068\"><#FFAE07><u>dazzling array</u></color></link>. There can only be <color=#00F6FF>3</color> dazzling arrays on the field at any time.",
  str_skill_desc_3261721 = "Teleports to any location within a <link=\"30068\"><#FFAE07><u>dazzling array</u></color></link> and deals <color=#00F6FF>{1}%</color> damage to tiles within the span of the <color=#00F6FF>dazzling array</color>. There can only be <color=#00F6FF>3</color> dazzling arrays on the field at any time.",
  str_skill_passive_desc_410172 = "Gain a shield equal to <color=#00F6FF>{1}</color> of Lilica's current DEF for every tile traversed within a <color=#00F6FF>dazzling array</color>.",
  str_skill_passive_desc_430172 = "Gain a shield equal to <color=#00F6FF>{1}</color> of Lilica's current DEF for every tile traversed within a <color=#00F6FF>dazzling array</color>. At the end of the round, deals true damage equal to the remaining shield to all tiles within the span of all <color=#00F6FF>dazzling arrays</color>.",
  str_skill_upgrade_desc_16017213 = "Active Skill Enhancement: There can only be <color=#00F6FF>3</color> dazzling arrays on the field at any time.",
  str_skill_upgrade_desc_16017216 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat. At the start of battle, generates a dazzling array that is <color=#00F6FF>12 tiles in a diamond shape</color> at the starting location.",
  str_skill_name_29038011 = "There You Are!",
