  str_skill_desc_2001691 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>8 tiles in a cross shape</color>.",
  str_skill_desc_2001692 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>12 tiles in a diamond shape</color>.",
