  str_skill_desc_300169 = "Deals <color=#00F6FF>300%</color> damage to 1 adjacent enemy in a <color=#00F6FF>cross shape</color> and knocks it back by 2 tiles. When <color=#00F6FF>blocked</color> while being knocked back, it takes an additional <color=#00F6FF>200%</color> damage and is <color=#00F6FF>stunned</color> for 1 round.",
  str_skill_desc_305169 = "Deals <color=#00F6FF>300%</color> damage to 1 adjacent enemy in a <color=#00F6FF>cross shape</color> and knocks it back by 3 tiles. When <color=#00F6FF>blocked</color> while being knocked back, it takes an additional <color=#00F6FF>200%</color> damage and is <color=#00F6FF>stunned</color> for 1 round.",
  str_skill_desc_330169 = "Deals <color=#00F6FF>300%</color> damage to 1 adjacent enemy in a <color=#00F6FF>cross shape</color> and knocks it back by 2 tiles. When <color=#00F6FF>blocked</color> while being knocked back, it takes an additional <color=#00F6FF>200%</color> damage and is <color=#00F6FF>stunned</color> for 1 round. If it is blocked by another enemy, that enemy is also dealt damage and stunned.",
  str_skill_desc_335169 = "Deals <color=#00F6FF>300%</color> damage to 1 adjacent enemy in a <color=#00F6FF>cross shape</color> and knocks it back by 3 tiles. When <color=#00F6FF>blocked</color> while being knocked back, it takes an additional <color=#00F6FF>200%</color> damage and is <color=#00F6FF>stunned</color> for 1 round. If it is blocked by another enemy, that enemy is also dealt damage and stunned.",
  str_skill_passive_name_410169 = "Batter's Swing",
  str_skill_passive_name_420169 = "Batter's Swing",
  str_skill_passive_desc_410169 = "Increases Sadie's basic ATK by <color=#00F6FF>{1}</color>. Sadie deals up to <color=#00F6FF>3</color> normal attacks when connecting tiles. After 3 attacks, gain 1 <color=#00F6FF>Crash Point</color> when making the next normal attack. Each Crash Point increases the Active Skill damage factor by <color=#00F6FF>{2}</color>, and all Crash Points are cleared after using the Active Skill.",
  str_skill_passive_desc_420169 = "Increases Sadie's basic ATK by <color=#00F6FF>{1}</color>. Sadie deals up to <color=#00F6FF>3</color> normal attacks when connecting tiles, and the 3rd normal attack deals double damage. After 3 attacks, gain 1 <color=#00F6FF>Crash Point</color> when making the next normal attack. Each Crash Point increases the Active Skill damage factor by <color=#00F6FF>{2}</color>, and all Crash Points are cleared after using the Active Skill.",
