  str_skill_desc_160175101 = "Consumes <color=#00F6FF>2</color> Cubic Energy to convert any 1 tile into a Prism Tile.",
  str_skill_desc_160175103 = "Consumes <color=#00F6FF>2</color> Cubic Energy to summon 1 Katana on any traversable tile without an existing Katana on it.",
  str_skill_desc_160175104 = "Consumes <color=#00F6FF>1</color> Cubic Energy to summon 1 Air Raid Beacon on any traversable tile without an existing Air Raid Beacon on it.",
  str_skill_desc_160175105 = "Consumes <color=#00F6FF>1</color> Cubic Energy to summon 1 Mechanical Bee on any traversable tile within 3 surrounding clusters without an existing Mechanical Bee on it. Up to 4 Mechanical Bees can exist on the battlefield at a time.",
  str_skill_desc_160175106 = "Consumes <color=#00F6FF>1</color> Cubic Energy to summon 1 Solar Arrow Mine on any traversable tile without an existing Solar Arrow Mine on it.",
  str_skill_desc_160175107 = "Consumes <color=#00F6FF>3</color> Cubic Energy to summon 1 Banner on any traversable tile. Up to 1 Banner can exist on the battlefield at a time.",
  str_skill_desc_160175108 = "Consumes <color=#00F6FF>4</color> Cubic Energy to summon 1 Lantern on any traversable tile without an existing Lantern on it. Up to 1 Lantern can exist on the battlefield at a time.",
  str_skill_desc_160175109 = "Consumes <color=#00F6FF>2</color> Cubic Energy to summon 1 Iron Lizard on 1 selected traversable tile without Iron Lizard.",
