  str_skill_name_33617511 = "Heavenly Pirouette",
  str_skill_name_30017513 = "Heavenly Pirouette",
  str_skill_desc_30017511 = "Consumes 1 <link=\"30069\"><#FFAE07><u>Cubic Energy</u></color></link> to summon 1 <link=\"30072\"><#FFAE07><u>Healing Orb</u></color></link> on any traversable tile, or to select a Healing Orb already on the field and absorb it to recover HP based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies.",
  str_skill_desc_30317511 = "Consumes 1 <link=\"30070\"><#FFAE07><u>Cubic Energy</u></color></link> to summon 1 <link=\"30072\"><#FFAE07><u>Healing Orb</u></color></link> on any traversable tile, or to select a Healing Orb already on the field and absorb it to recover HP based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies.",
  str_skill_desc_30617511 = "Consumes 1 <link=\"30070\"><#FFAE07><u>Cubic Energy</u></color></link> to summon 1 <link=\"30073\"><#FFAE07><u>Healing Orb</u></color></link> on any traversable tile, or to select a Healing Orb already on the field and absorb it to recover HP based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies.",
  str_skill_desc_32017511 = "Consumes 1 <link=\"30069\"><#FFAE07><u>Cubic Energy</u></color></link> to summon 1 <link=\"30072\"><#FFAE07><u>Healing Orb</u></color></link> on any traversable tile, or to select a Healing Orb already on the field and absorb it to recover HP based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies, returning 1 Cubic Energy each.",
  str_skill_desc_32317511 = "Consumes 1 <link=\"30070\"><#FFAE07><u>Cubic Energy</u></color></link> to summon 1 <link=\"30072\"><#FFAE07><u>Healing Orb</u></color></link> on any traversable tile, or to select a Healing Orb already on the field and absorb it to recover HP based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies, returning 1 Cubic Energy each.",
  str_skill_desc_32617511 = "Consumes 1 <link=\"30070\"><#FFAE07><u>Cubic Energy</u></color></link> to summon 1 <link=\"30073\"><#FFAE07><u>Healing Orb</u></color></link> on any traversable tile, or to select a Healing Orb already on the field and absorb it to recover HP based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies, returning 1 Cubic Energy each.",
  str_skill_desc_33017511 = "Consumes 1 <link=\"30069\"><#FFAE07><u>Cubic Energy</u></color></link> to summon 1 <link=\"30072\"><#FFAE07><u>Healing Orb</u></color></link> on any traversable tile, or to select a Healing Orb already on the field and absorb it to recover HP based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies, returning 1 Cubic Energy each. Axelia can use the <link=\"30071\"><#FFAE07><u>Authority Module</u></color></link> to summon the summonable objects of certain other Thunder Aurorians' Active Skills.",
  str_skill_desc_33317511 = "Consumes 1 <link=\"30070\"><#FFAE07><u>Cubic Energy</u></color></link> to summon 1 <link=\"30072\"><#FFAE07><u>Healing Orb</u></color></link> on any traversable tile, or to select a Healing Orb already on the field and absorb it to recover HP based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies, returning 1 Cubic Energy each. Axelia can use the <link=\"30071\"><#FFAE07><u>Authority Module</u></color></link> to summon the summonable objects of certain other Thunder Aurorians' Active Skills.",
  str_skill_desc_33617511 = "Consumes 1 <link=\"30070\"><#FFAE07><u>Cubic Energy</u></color></link> to summon 1 <link=\"30073\"><#FFAE07><u>Healing Orb</u></color></link> on any traversable tile, or to select a Healing Orb already on the field and absorb it to recover HP based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies, returning 1 Cubic Energy each. Axelia can use the <link=\"30071\"><#FFAE07><u>Authority Module</u></color></link> to summon the summonable objects of certain other Thunder Aurorians' Active Skills.",
  str_skill_desc_330175111 = "Consumes 1 <color=#D1970C><b>Cubic Energy</b></color> to summon 1 Healing Orb on any traversable tile, which will restore HP equal to <color=#D1970C><b>40%/100%/200%</b></color> of Axelia's ATK to Aurorians who pass through this orb after it has been on the field for <color=#D1970C><b>0/1/2</b></color> rounds. Alternatively, select a Healing Orb already on the field and absorb it to recover HP equal to <color=#D1970C><b>40%/100%/200%</b></color> of Axelia's ATK based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies, returning 1 Cubic Energy each.",
  str_skill_desc_336175111 = "Consumes 1 <color=#D1970C><b>Cubic Energy</b></color> to summon 1 Healing Orb on any traversable tile, which will restore HP equal to <color=#D1970C><b>40%/100%/250%</b></color> of Axelia's ATK to Aurorians who pass through this orb after it has been on the field for <color=#D1970C><b>0/1/2</b></color> rounds. Alternatively, select a Healing Orb already on the field and absorb it to recover HP equal to <color=#D1970C><b>80%/180%/400%</b></color> of Axelia's ATK based on the number of rounds it has been on the field. Healing Orbs disappear when touched by enemies, returning 1 Cubic Energy each.",
  str_skill_passive_name_4101751 = "Cubic Switch",
  str_skill_passive_desc_4101751 = "After a Thunder Aurorian on the team uses an Active Skill, Axelia gains <color=#00F6FF>1</color> stack of Conversion Energy. Using a Chain Combo clears all stacks of Conversion Energy and deals <color=#00F6FF>{1}</color> damage for each stack to the enemy with the highest HP on the field.",
  str_skill_name_2001751 = "Heavenly Blessing",
  str_skill_name_2001752 = "Heavenly Blessing",
  str_skill_name_2001753 = "Heavenly Blessing",
  str_skill_desc_2001751 = "Recovers the team's HP by <color=#00F6FF>135%</color> of Axelia's ATK.",
  str_skill_desc_2001752 = "Recovers the team's HP by <color=#00F6FF>160%</color> of Axelia's ATK.",
  str_skill_desc_2001753 = "Recovers the team's HP by <color=#00F6FF>190%</color> of Axelia's ATK.",
  str_skill_name_29036011 = "Corrosion",
  str_skill_desc_29036011 = "Deals severe damage to the target when an Aurorian is within 1 surrounding cluster of Diavola and inflicts Toxin.",
  str_skill_name_29036012 = "Worm Lure",
  str_skill_desc_29036012 = "When Aurorians move away from Diavola, Dawn Sprites are summoned to random locations on the field.",
  str_skill_name_20006091 = "Enhancement",
  str_skill_desc_20006091 = "When within 1 surrounding cluster of Diavola, increases Diavola's attack by fusing with it.",
  str_skill_name_200190101 = "Lantern Spirit: Link",
  str_skill_desc_200190101 = "If the Lantern Spirit can traverse through an Aurorian when it attacks, it deals damage and forms a link with the Aurorian. Otherwise, it will only deal damage to the Aurorian, and gain an ACT boost.",
  str_skill_name_290340101 = "Asmodeus: Chain of Nightmares",
  str_skill_desc_290340101 = "Asmodeus attacks all Aurorians within range, linking herself to them with her Chain of Nightmares. Aurorians linked to the Chain of Nightmares will take damage for every 1 tile they traverse. If an Aurorian is already linked to the Chain of Nightmares when Asmodeus attacks, she deals more damage and gains Life Drain.",
  str_skill_name_290341101 = "Asmodeus: Chain of Nightmares",
  str_skill_desc_290341101 = "Asmodeus attacks all Aurorians within range, linking herself to them with her Chain of Nightmares. When the Chain of Nightmares is broken, it deals high damage to Aurorians. If an Aurorian is already linked to the Chain of Nightmares when Asmodeus attacks, she deals more damage and gains Life Drain.",
  str_skill_name_290340102 = "Asmodeus: Intensification",
  str_skill_desc_290340102 = "If Asmodeus is unable to attack any Aurorians, her ACT will keep increasing until she hits an Aurorian.",
  str_skill_name_290340201 = "Asmodeus: Flaming",
  str_skill_desc_290340201 = "Asmodeus teleports to the farthest tile she can attack Aurorians from and attacks them.",
  str_skill_name_2001761 = "Australis Tempest",
  str_skill_name_2001762 = "Australis Tempest",
  str_skill_name_2001763 = "Australis Tempest",
  str_skill_name_3001761 = "Borealis Resplendence",
  str_skill_name_3021761 = "Borealis Resplendence",
  str_skill_name_3051761 = "Borealis Resplendence",
  str_skill_name_3201761 = "Borealis Resplendence",
  str_skill_name_3221761 = "Borealis Resplendence",
  str_skill_name_3251761 = "Borealis Resplendence",
  str_skill_name_3301761 = "Borealis Resplendence",
  str_skill_name_3321761 = "Borealis Resplendence",
  str_skill_name_3351761 = "Borealis Resplendence",
  str_skill_passive_name_4101761 = "Australis Booster",
  str_skill_passive_name_4151761 = "Australis Booster",
  str_skill_passive_name_4201761 = "Australis Booster",
  str_skill_passive_name_4251761 = "Australis Booster",
  str_skill_passive_name_4301761 = "Australis Booster",
  str_skill_passive_name_4351761 = "Australis Booster",
  str_skill_desc_2001761 = "Deals <color=#00F6FF>60%</color> damage 2 times to random enemies within <color=#00F6FF>3 surrounding clusters</color>. Each time damage is dealt, increases the number of <color=#00F6FF>Australis Spears</color> in targeted enemies by 1. When dealing damage to a target more than once, the damage from the second time forth is halved.",
  str_skill_desc_2001762 = "Deals <color=#00F6FF>80%</color> damage 3 times to random enemies within <color=#00F6FF>3 surrounding clusters</color>. Each time damage is dealt, increases the number of <color=#00F6FF>Australis Spears</color> in targeted enemies by 1. When dealing damage to a target more than once, the damage from the second time forth is halved.",
  str_skill_desc_2001763 = "Deals <color=#00F6FF>100%</color> damage 4 times to random enemies within <color=#00F6FF>3 surrounding clusters</color>. Each time damage is dealt, increases the number of <color=#00F6FF>Australis Spears</color> in targeted enemies by 1. When dealing damage to a target more than once, the damage from the second time forth is halved.",
  str_skill_desc_3001761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>2 surrounding clusters</color>. Deals <color=#00F6FF>80%</color> damage for each Australis Spear pulled out.",
  str_skill_desc_3021761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>80%</color> damage for each Australis Spear pulled out.",
  str_skill_desc_3051761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>80%–120%</color> damage for each Australis Spear pulled out. The lower the target's current HP, the higher the damage factor.",
  str_skill_desc_3201761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>2 surrounding clusters</color>. Deals <color=#00F6FF>80%</color> damage and recovers HP by <color=#00F6FF>10%</color> of the damage dealt in this way for each Australis Spear pulled out.",
  str_skill_desc_3221761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>80%</color> damage and recovers HP by <color=#00F6FF>10%</color> of the damage dealt in this way for each Australis Spear pulled out.",
  str_skill_desc_3251761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>80%–120%</color> damage and recovers HP by <color=#00F6FF>10%</color> of the damage dealt in this way for each Australis Spear pulled out. The lower the target's current HP, the higher the damage factor.",
  str_skill_desc_3301761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>2 surrounding clusters</color>. Deals <color=#00F6FF>80%</color> damage and recovers HP by <color=#00F6FF>10%–15%</color> of the damage dealt in this way for each Australis Spear pulled out. The lower the team's HP, the higher the recovery factor.",
  str_skill_desc_3321761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>80%</color> damage and recovers HP by <color=#00F6FF>10%–15%</color> of the damage dealt in this way for each Australis Spear pulled out. The lower the team's HP, the higher the recovery factor.",
  str_skill_desc_3351761 = "Pulls out Australis Spears from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>80%–120%</color> damage and recovers HP by <color=#00F6FF>10%–15% of</color> the damage dealt in this way for each <color=#00F6FF>Australis Spear</color> pulled out. The lower the target's current HP, the higher the damage factor. The lower the team's HP, the higher the recovery factor.",
  str_skill_passive_desc_4101761 = "Every <color=#00F6FF>{1}</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_passive_desc_4151761 = "Every <color=#00F6FF>{1}</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_passive_desc_4201761 = "Every <color=#00F6FF>{1}</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_passive_desc_4251761 = "Every <color=#00F6FF>{1}</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_passive_desc_4301761 = "Every <color=#00F6FF>{1}</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_passive_desc_4351761 = "Every <color=#00F6FF>{1}</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_upgrade_desc_15017612 = "Active Skill Enhancement: Increases skill range to <color=#FFFF00>3 surrounding clusters</color>.",
  str_skill_upgrade_desc_15017615 = "Active Skill Enhancement: The lower the HP of the target, the higher the damage factor, up to <color=#00F6FF>40%</color>.",
  str_skill_name_290350103 = "Cerritus: Shattering Smash",
  str_skill_desc_290350103 = "Cerritus shatters the tiles under its feet and charges into Aurorians, knocking them back and destroying all Pebbles along its path and inflicting Aurorians it rams into with Exhausted.",
  str_skill_name_290350104 = "Cerritus: Devastating Quake",
  str_skill_desc_290350104 = "Cerritus smashes the 2 tiles in front of it after moving, dealing massive damage and shattering the tiles.",
  str_skill_desc_290350203 = "Cerritus shatters the tiles under its feet and charges into Aurorians, knocking them back and destroying all Pebbles along its path.",
  str_skill_desc_290350204 = "Cerritus smashes the 2 tiles in front of it after moving, dealing massive damage and shattering the tiles. Aurorians will gain the Exhausted state after being dealt damage.",
  str_skill_name_216003811 = "Megashock!",
  str_skill_desc_216003811 = "Phantom Gronru deals damage to 1 column.",
  str_skill_name_91001641 = "Enhancement",
  str_skill_desc_91001641 = "Increases the ACT and ATK of all Eclipsites excluding itself. This effect can stack.",
  str_skill_name_290290101 = "Greed: Surge",
  str_skill_desc_290290101 = "Crushes neighboring Aurorians, dealing massive damage that ignores enemy defense and knocks them back by 1 tile. If the 4 tiles next to the Aurorians are blocked, they are defeated instantly.",
  str_skill_desc_290291131 = "Crushes neighboring Aurorians, defeating them instantly!",
  str_skill_name_290290104 = "Greed: Fracture",
  str_skill_desc_290290104 = "If there are no adjacent Aurorians, it travels 1 tile towards the direction of the Aurorians' current location and then deals area damage within 1 surrounding cluster of its head.",
  str_skill_name_290290100 = "Jormungand's Body",
  str_skill_desc_290290100 = "Jormungand's body is protected by special energy that can nullify all attacks. Its body has the ability to replicate itself.",
  str_skill_name_290290102 = "Jormungand's Tail",
  str_skill_desc_290290102 = "Damage dealt to its tail is transmitted to its head.",
