  str_skill_desc_315180 = "Converts the <color=#00F6FF>5</color> nearest Blue tiles to Green. Randomly inflicts a <color=#00F6FF>Stakeout Mark</color> on half of the enemies on the field. If the Active Skill was ready in the last round, converts <color=#00F6FF>+1</color> tile in this round.",
  str_skill_desc_3131801 = "Converts the <color=#00F6FF>4</color> nearest Blue tiles to Green. Randomly inflicts a <color=#00F6FF>Stakeout Mark</color> on half of the enemies on the field. If the Active Skill was ready in the last round, converts <color=#00F6FF>+1</color> tile in this round.",
  str_skill_desc_3151801 = "Converts the <color=#00F6FF>5</color> nearest Blue tiles to Green. Randomly inflicts a <color=#00F6FF>Stakeout Mark</color> on half of the enemies on the field. If the Active Skill was ready in the last round, converts <color=#00F6FF>+1</color> tile in this round.",
  str_skill_desc_330180 = "Converts the <color=#00F6FF>4</color> nearest Blue tiles to Green. Randomly inflicts a <color=#00F6FF>Stakeout Mark</color> on half of the enemies on the field, then generates an <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> under the feet of up to <color=#00F6FF>3</color> marked enemies.",
  str_skill_desc_333180 = "Converts the <color=#00F6FF>4</color> nearest Blue tiles to Green. Randomly inflicts a <color=#00F6FF>Stakeout Mark</color> on half of the enemies on the field, then generates an <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> under the feet of up to <color=#00F6FF>3</color> marked enemies. If the Active Skill was ready in the last round, converts <color=#00F6FF>+1</color> tile in this round.",
