  str_skill_desc_2201803 = "Deals <color=#00F6FF>{1}%</color> damage to the nearest and <color=#00F6FF>smallest</color> enemy, then inflicts a </color>Stakeout Mark<color=#00F6FF> on it.",
  str_skill_passive_desc_410180 = "Active Skills inflict a <color=#00F6FF>Stakeout Mark</color> on enemies that increases the final damage they take from single instance Chain Combo skills by <color=#00F6FF>{1}</color>. Lasts until Aurorian round ends.",
  str_skill_passive_desc_420180 = "Active Skills and Chain Combos inflict a <color=#00F6FF>Stakeout Mark</color> on enemies that increases the final damage they take from single instance Chain Combo skills by <color=#00F6FF>{1}</color>. Lasts until Aurorian round ends.",
