  str_skill_passive_desc_410177 = "Whenever team gains <color=#00F6FF>{1}</color> <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including via <link=\"30065\"><#FFAE07><u>Absorption</u></color></link>), generates 1 enhanced tile on the nearest <color=#00F6FF>non-Green tile</color>.",
  str_skill_upgrade_desc_16017713 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat. Generates <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> on random <color=#00F6FF>non-Green tiles</color>.",
  str_skill_upgrade_desc_16017716 = "Active Skill Enhancement: Skill cooldown <color=#FFFF00>-1</color>. If the Active Skill was ready in the last round, then in Warsong Mode, tiles that enemies are standing on can be connected during <color=#00F6FF>Aurora Time</color>, and <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> are deemed as chromatic tiles. (Valid for Ascension III)",
  str_skill_desc_290420101 = "Moves towards Aurorians and swings its forearm to deal damage to enemies within 2 tiles in front.",
  str_skill_desc_290420102 = "Deals damage to all enemies on the field.",
  str_skill_name_200200101 = "Venomex Ball",
  str_skill_desc_200200101 = "Spits out a Venomex Ball, dealing damage to targets within range. The ball splashes across 4 tiles in a cross shape, poisoning all enemies and allies within the splash range.",
  str_skill_name_200210001 = "Cozen Assassination",
  str_skill_desc_200210001 = "When the Crud's countdown ends, Cozen jumps out of it to attack Aurorians before going back into hiding.",
