  str_skill_desc_290400101 = "Bennuguardian uses its claws to deal damage to targets within its area of attack.",
  str_skill_name_290400102 = "Bennu Leap",
  str_skill_desc_290400102 = "Bennuguardian leaps towards the target, hammering the ground when it lands to deal great damage to targets in 1 surrounding cluster.",
  str_skill_name_290400103 = "Bennu Fury",
  str_skill_desc_290400103 = "The enraged Bennuguardian unleashes a powerful skill that deals damage to all targets on the field.",
  str_skill_name_5220012 = "Healing Gel",
  str_skill_desc_5220012 = "Restores <color=#00F6FF>20%</color> of the team's Max HP.",
  str_skill_name_5220013 = "Path Analyzer",
  str_skill_desc_5220013 = "Activates the device and teleports to a traversable tile.",
  str_skill_name_290430101 = "Regal: Tempest",
  str_skill_desc_290430101 = "Regal moves close to the target by connecting tiles of two elements: his own and that of another Legendary Aurorian on the field. He then launches a normal attack in 8 directions, then after the chain ends, deals damage to 1 surrounding cluster.",
  str_skill_name_290440101 = "Requiem: Sacred Lance",
  str_skill_desc_290440101 = "Requiem moves close to the target by connecting tiles of two elements: her own and that of another Legendary Aurorian on the field. She then launches a normal attack in 4 directions, then after the chain ends, deals damage to 1 surrounding cluster. Every 3 normal attacks, she deals additional damage equal to a percentage of the target's Max HP.",
  str_skill_name_290450101 = "Frostfire: Extinction",
  str_skill_desc_290450101 = "Frostfire moves far away from the target by connecting tiles of two elements: her own and that of another Legendary Aurorian on the field. After moving, she deals damage to all targets on the field.",
  str_skill_name_290460101 = "Mythos: Towering Canopy",
  str_skill_desc_290460101 = "Mythos moves far away from the target by connecting tiles of two elements: her own and that of another Legendary Aurorian on the field. After moving, deals damage to all targets on the field.",
  str_skill_name_2801101 = "Command Mark",
  str_skill_desc_2801101 = "Absorbed by Aurorians when they pass through. Increases the number of times the Captain can be changed.",
  str_skill_name_5000881 = "Blade",
  str_skill_desc_5000881 = "Absorbs by Aurorians when passing through it. Increases Aurorian ATK.",
  str_skill_name_5000891 = "Shield",
  str_skill_desc_5000891 = "Absorbs by Aurorians when passing through it. Increases Aurorian DEF.",
  str_skill_name_2002101 = "Sword Buff",
  str_skill_desc_2002101 = "After being picked up, inflicts Silence but greatly increases ATK.",
  str_skill_desc_2002201 = "After being picked up, increases Chain Combo damage by 8%.",
