  str_skill_name_3201831 = "Between Life and Death",
  str_skill_name_3251831 = "Between Life and Death",
  str_skill_desc_3001831 = "Selects 1 enemy and forces their HP to be <color=#00F6FF>no less than 1</color> before the enemy round begins. The target enemy is randomly afflicted with one of the following effects: Final damage taken from <color=#00F6FF>Normal Attacks/Chain Combos/Active Skills</color> increases by <color=#00F6FF>5%/5%/7%</color>.",
  str_skill_desc_3201831 = "Selects 1 enemy and forces their HP to be <color=#00F6FF>no less than 1</color> before the enemy round begins. The target enemy is randomly afflicted with one of the following effects: Final damage taken from <color=#00F6FF>Normal Attacks/Chain Combos/Active Skills</color> increases by <color=#00F6FF>5%/5%/7%</color>. Effect is repeated <color=#00F6FF>1 to 3</color> times.",
  str_skill_desc_3251831 = "Selects 1 enemy and forces their HP to be <color=#00F6FF>no less than 1</color> before the enemy round begins. The target enemy is randomly afflicted with one of the following effects: Final damage taken from <color=#00F6FF>Normal Attacks/Chain Combos/Active Skills</color> increases by <color=#00F6FF>5%/5%/7%</color>. Effect is repeated <color=#00F6FF>2 to 5</color> times.",
  str_skill_name_2001831 = "Curative Flight",
