  str_skill_desc_3001852 = "Unlocks after accumulating <color=#00F6FF>8</color> stacks of Kyanite Power: Choose an enemy and teleport to the closest position within <color=#00F6FF>1 surrounding cluster</color> around the target.",
  str_skill_desc_3361852 = "Unlocks after accumulating <color=#00F6FF>5</color> stacks of Kyanite Power: Choose an enemy and teleport to the closest position within <color=#00F6FF>1 surrounding cluster</color> around the target.",
  str_skill_passive_desc_410185 = "When the team teleports with an Active Skill, deal <color=#00F6FF>{1}</color> damage to the enemy that has the lowest HP within <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_passive_desc_416185 = "When the team teleports with an Active Skill, deal <color=#00F6FF>{1}</color> damage to the enemy that has the lowest HP within <color=#00F6FF>1 surrounding cluster</color> and gain <color=#00F6FF>1</color> stack of Kyanite Power. Each stack will increase the damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_420185 = "When the team teleports with an Active Skill, deal <color=#00F6FF>{1}</color> damage to the enemy that has the lowest HP within <color=#00F6FF>1 surrounding cluster</color>. When Kya's Active Skill triggers this effect, her final damage will be increased by <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_426185 = "When the team teleports with an Active Skill, deal <color=#00F6FF>{1}</color> damage to the enemy that has the lowest HP within <color=#00F6FF>1 surrounding cluster</color> and gain <color=#00F6FF>1</color> stack of Kyanite Power. When Kya's Active Skill triggers this effect, her final damage will be increased by <color=#00F6FF>60%</color>. Each stack of Kyanite Power will increase the damage by <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430185 = "When the team teleports with an Active Skill, deal <color=#00F6FF>{1}</color> damage to the enemy that has the lowest HP within <color=#00F6FF>1 surrounding cluster</color> and gain <color=#00F6FF>1</color> stack of Kyanite Power. When Kya's Active Skill triggers this effect, her final damage will be increased by <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_432185 = "When the team teleports with an Active Skill, deal <color=#00F6FF>{1}</color> damage to the enemy that has the lowest HP within <color=#00F6FF>1 surrounding cluster</color> and gain <color=#00F6FF>1</color> stack of Kyanite Power. When Kya's Active Skill triggers this effect, her final damage will be increased by <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_436185 = "When the team teleports with an Active Skill, deal <color=#00F6FF>{1}</color> damage to the enemy that has the lowest HP within <color=#00F6FF>1 surrounding cluster</color> and gain <color=#00F6FF>1</color> stack of Kyanite Power. When Kya's Active Skill triggers this effect, her final damage will be increased by <color=#00F6FF>60%</color>. Each stack of Kyanite Power will increase the damage by <color=#00F6FF>5%</color>.",
  str_skill_upgrade_desc_15018512 = "Active Skill Enhancement: The number of stacks required for Blink of an Eye reduces to <color=#00F6FF>5</color>. (Valid for Ascension III)",
  str_skill_upgrade_desc_15018515 = "Equipment Skill Enhancement: Each skill trigger will generate <color=#00F6FF>1</color> stack of Kyanite Power. Each stack of Kyanite Power will increase Kya's Equipment Skill damage by <color=#00F6FF>5%</color>.",
  str_skill_name_28005016 = "Dragger",
  str_skill_desc_28005016 = "Pulls Eclipsites within a small range in front of the Dragger 1 tile in its direction. Each Eclipsite can only be affected by the Dragger's pull effect once per turn.",
  str_skill_name_400054101 = "Uproot",
  str_skill_desc_400054101 = "Deals damage to all targets within range and smashes all tiles within range, destroying all Bullock 8 summons on them.",
  str_skill_desc_5410100 = "Uses spear to attack Eclipsites within attack range.",
  str_skill_desc_888426101 = "After the player uses Active Skills 3 times in a row, summons a Lumo Piker to the battlefield.",
  str_skill_desc_4100002 = "Summons Fire Dreadblades each round until 4 Fire Dreadblades are on the battlefield.",
  str_skill_desc_4100004 = "Summons Thunder Dreadblades each round until 4 Thunder Dreadblades are on the battlefield.",
  str_skill_desc_4100005 = "Summons an Enferno each round until 2 Enfernos are on the battlefield.",
  str_skill_desc_4100006 = "Summons an Enferno to the battlefield each round. Will not summon if there is already an Enferno on the battlefield.",
  str_skill_desc_5401005 = "Enferno summons burning rain at random locations near the Lumo Constructor, dealing elemental damage and burning targets.",
  str_skill_name_290470111 = "Mechanical Huntsman: Annihilate",
  str_skill_desc_290470111 = "Channels Darkflow with its giant hammer, dealing massive damage to all targets on the field. This attack reduces the HP of Aurorians inside the guarded zone to 1.",
  str_skill_name_290470121 = "Mechanical Huntsman: Hunt Down",
  str_skill_desc_290470121 = "If its target is in the guarded zone, it moves next to them and deals melee damage. If the target is outside the guarded zone, it hooks a target in the same row or column and pulls the target near itself.",
  str_skill_desc_290470122 = "If its target is in the guarded zone, it moves next to them and deals melee damage. If the target is outside the guarded zone, it hooks a target in the same row or column and pulls the target near itself.",
  str_skill_name_290470131 = "Mechanical Huntsman: Banish",
  str_skill_desc_290470131 = "Sends forth waves of turbulent energy with its giant hammer, dealing damage to all enemies on the field. The player will be knocked to the edge of the field by the energy if inside the guarded zone.",
  str_skill_name_290490101 = "The Four Knights: Team Battle",
  str_skill_desc_290490101 = "Moves to a tile diagonal from the member of The Four Knights nearest the target (if the caster is the nearest member of The Four Knights, they will remain on the same tile), and then attacks targets within 1 surrounding cluster.",
  str_skill_desc_290490103 = "Moves to a tile diagonal from the member of The Four Knights nearest the target (if the caster is the nearest member of The Four Knights, they will remain on the same tile), and then attacks targets within 1 surrounding cluster, inflicting Fragility on Aurorians. Each stack of Fragility reduces Aurorians' DEF by 2%.",
  str_skill_desc_290490107 = "Attacks targets within 1 surrounding cluster.",
  str_skill_name_290490102 = "The Four Knights: Quick Strike",
  str_skill_desc_290490102 = "The Four Knights split up, rushing to the edges of the field, then attack the target.",
  str_skill_desc_290490108 = "Attacks targets while remaining in place.",
  str_skill_name_290550101 = "Demon Hati: Cobalt Flame",
  str_skill_desc_290550101 = "Demon Hati loses 15% of her current HP and teleports as close as possible to an enemy within 12 tiles in a diamond shape, then deals damage to enemies within 1 surrounding cluster. If she hits a target, she recovers 15% of her lost HP.",
  str_skill_name_290550111 = "Demon Hati: Cobalt Flame+",
  str_skill_desc_290550111 = "Demon Hati loses 15% of her current HP and teleports as close as possible to an enemy within 2 surrounding clusters, then deals damage to enemies within 1 surrounding cluster. If she hits a target, she recovers 15% of her lost HP.",
  str_skill_name_290550121 = "Demon Hati: Cobalt Flame++",
  str_skill_desc_290550121 = "Demon Hati loses 15% of her current HP and teleports as close as possible to an enemy within 2 surrounding clusters, then deals damage to enemies within 2 surrounding clusters. If she hits a target, she recovers 15% of her lost HP.",
  str_skill_name_290550102 = "Demon Hati: Nether Flames",
  str_skill_desc_290550102 = "Demon Hati teleports next to Aurorians and consumes 15% of her current HP to deal massive damage to Aurorians. If she hits an Aurorian, she recovers 15% of her lost HP.",
