  str_skill_desc_3001890 = "Selects 1 tile from <color=#00F6FF>4 tiles in a cross shape</color> at the current location and deals <color=#00F6FF>100%</color> damage to <color=#00F6FF>2 rows in a fan shape</color> in this direction.",
  str_skill_desc_3001891 = "Selects 1 tile from <color=#00F6FF>4 tiles in a cross shape</color> at the current location and deals <color=#00F6FF>100%</color> damage to <color=#00F6FF>2 rows in a fan shape</color> in this direction. Zeal increases damage and range, dealing up to <color=#00F6FF>400%</color> damage to <color=#00F6FF>7 rows in a fan shape</color>. Zeal will be cleared after casting the skill.",
  str_skill_desc_3001892 = "Selects 1 tile from <color=#00F6FF>4 tiles in a cross shape</color> at the current location and deals <color=#00F6FF>100%</color> damage to <color=#00F6FF>2 rows in a fan shape</color> in this direction. Zeal increases damage and range, dealing up to <color=#00F6FF>400%</color> damage to <color=#00F6FF>7 rows in a fan shape</color>. Zeal will be cleared after casting the skill.",
  str_skill_desc_3061891 = "Selects 1 tile from <color=#00F6FF>4 tiles in a cross shape</color> at the current location and deals <color=#00F6FF>100%</color> damage to <color=#00F6FF>2 rows in a fan shape</color> in this direction. Zeal increases damage and range, dealing up to <color=#00F6FF>400%</color> damage to <color=#00F6FF>7 rows in a fan shape</color>. Zeal will be cleared after casting the skill. If you choose to cast this skill with your current tile, it will increase Zeal by <color=#00F6FF>35</color> points instead of dealing damage.",
  str_skill_desc_3061892 = "Selects 1 tile from <color=#00F6FF>4 tiles in a cross shape</color> at the current location and deals <color=#00F6FF>100%</color> damage to <color=#00F6FF>2 rows in a fan shape</color> in this direction. Zeal increases damage and range, dealing up to <color=#00F6FF>400%</color> damage to <color=#00F6FF>7 rows in a fan shape</color>. Zeal will be cleared after casting the skill. If you choose to cast this skill with your current tile, it will increase Zeal by <color=#00F6FF>35</color> points instead of dealing damage.",
  str_skill_desc_3301892 = "Can still use Normal Attacks in the Overzealous state this round. Zeal will dissipate at the end of the round.",
  str_skill_desc_3331892 = "Increases Zeal to <color=#00F6FF>100</color>. Can still use Normal Attacks in the Overzealous state this round. Zeal will dissipate at the end of the round.",
