  str_skill_passive_name_430190 = "Guardian of Sanctitude",
  str_skill_passive_desc_410189 = "Leyn's Normal Attacks gain a damage bonus of up to <color=#00F6FF>{1}</color> based on his <link=\"30078\"><#FFAE07><u>Zeal</u></color></link>, the higher the Zeal, the higher the damage bonus. When Zeal reaches <color=#00F6FF>100</color>, he enters the Overzealous state and cannot use Normal Attacks.",
  str_skill_passive_desc_420189 = "Leyn's Normal Attacks gain a damage bonus of up to <color=#00F6FF>{1}</color> based on his <link=\"30078\"><#FFAE07><u>Zeal</u></color></link>, the higher the Zeal, the higher the damage bonus. When Zeal reaches <color=#00F6FF>100</color>, he enters the Overzealous state and cannot use Normal Attacks. However, the final damage of his Chain Combos increases by <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_430189 = "Leyn's Normal Attacks gain a damage bonus of up to <color=#00F6FF>{1}</color> based on his <link=\"30078\"><#FFAE07><u>Zeal</u></color></link>, the higher the Zeal, the higher the damage bonus. When Zeal reaches <color=#00F6FF>100</color>, he enters the Overzealous state and cannot use Normal Attacks. However, the final damage of his Chain Combos increases by <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_433189 = "Leyn's Normal Attacks gain a damage bonus of up to <color=#00F6FF>{1}</color> based on his <link=\"30078\"><#FFAE07><u>Zeal</u></color></link>, the higher the Zeal, the higher the damage bonus. When Zeal reaches <color=#00F6FF>100</color>, he enters the Overzealous state and cannot use Normal Attacks. However, the final damage of his Chain Combos increases by <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_410190 = "<color=#00F6FF>50%</color> of damage dealt by Chain Combos is converted into a shield. The value of this shield cannot exceed <color=#00F6FF>{1}</color> of Matthieu's ATK.",
  str_skill_passive_desc_420190 = "<color=#00F6FF>50%</color> of damage dealt by Chain Combos is converted into a shield. The value of this shield cannot exceed <color=#00F6FF>{1}</color> of Matthieu's ATK. Whenever Fire Aurorians cast Active Skills, gain a shield equal to <color=#00F6FF>10%</color> of Matthieu's ATK.",
  str_skill_passive_desc_430190 = "<color=#00F6FF>50%</color> of damage dealt by Chain Combos is converted into a shield. The value of this shield cannot exceed <color=#00F6FF>{1}</color> of Matthieu's ATK. Whenever Fire Aurorians cast Active Skills, gain a shield equal to <color=#00F6FF>10%</color> of Matthieu's ATK.",
