  str_skill_desc_3001861 = "Tina begins sleepwalking, ignoring tile colors for up to <color=#00F6FF>3</color> consecutive tiles while <color=#00F6FF>converting tiles she passes through</color> to Blue, then returns to her starting tile.",
  str_skill_desc_3061861 = "Tina begins sleepwalking, ignoring tile colors for up to <color=#00F6FF>4</color> consecutive tiles while <color=#00F6FF>converting tiles she passes through</color> to Blue, then returns to her starting tile.",
  str_skill_desc_3201861 = "Tina begins sleepwalking, ignoring tile colors for up to <color=#00F6FF>3</color> consecutive tiles while <color=#00F6FF>converting her starting tile and tiles she passes through</color> to Blue tiles before returning to her starting tile. If there are enemies at the end of her path, she may choose to descend on the enemy to deal <color=#00F6FF>200%</color> damage to them, before landing on the tile right before the enemy.",
  str_skill_desc_3261861 = "Tina begins sleepwalking, ignoring tile colors for up to <color=#00F6FF>4</color> consecutive tiles while <color=#00F6FF>converting her starting tile and tiles she passes through</color> to Blue tiles before returning to her starting tile. If there are enemies at the end of her path, she may choose to descend on the enemy to deal <color=#00F6FF>200%</color> damage to them, before landing on the tile right before the enemy.",
  str_skill_upgrade_desc_16018913 = "Active Skill Enhancement: Combat Overload becomes a <color=#FFFF00>Preemptive Strike</color> and increases Zeal to <color=#00F6FF>100</color> when activated. (Valid for Ascension III)",
  str_skill_upgrade_desc_16018916 = "Active Skill Enhancement: Can select current tile to increase Zeal by <color=#00F6FF>35</color> instead of dealing damage. (Valid for Ascension I)",
