  str_skill_upgrade_refine_desc_16001111 = "Equipment Skill Enhancement: Applies up to <color=#00F6FF>7</color> stacks of Dragontooth Mark on enemies.",
  str_skill_upgrade_refine_desc_16001112 = "<color=#00F6FF>New Active Skill Variant I</color>: <color=#FFFF00>Skill cooldown -1 after casting</color>. Teleports to a selected location within <color=#FFFF00>3 surrounding clusters</color>, deals <color=#FFFF00>200%</color> damage to <color=#FFFF00>1 surrounding cluster</color>, and applies 2 stacks of Dragontooth Mark (if she kills an enemy, maximum Dragontooth Mark stacks are applied to other enemies within the area).",
  str_skill_upgrade_refine_desc_16001113 = "<color=#00F6FF>New Active Skill Variant II</color>: <color=#FFFF00>Skill cooldown +1 after casting</color>. Teleports to <color=#FFFF00>any location</color>, deals <color=#FFFF00>360%</color> damage to <color=#FFFF00>3 surrounding clusters</color>, and applies 2 stacks of Dragontooth Mark (if she kills an enemy, maximum Dragontooth Mark stacks are applied to other enemies within the area).",
  str_skill_desc_3300111 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Teleports to a selected location within <color=#FFFF00>3 surrounding clusters</color>, deals <color=#FFFF00>200%</color> damage to <color=#FFFF00>1 surrounding cluster</color>, and applies 2 stacks of Dragontooth Mark (if she kills an enemy, maximum Dragontooth Mark stacks are applied to other enemies within the area).",
  str_skill_desc_3300112 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Teleports to <color=#FFFF00>any location</color>, deals <color=#FFFF00>360%</color> damage to <color=#FFFF00>3 surrounding clusters</color>, and applies 2 stacks of Dragontooth Mark (if she kills an enemy, maximum Dragontooth Mark stacks are applied to other enemies within the area).",
