  str_skill_desc_3201911 = "Selects 1 enemy within <color=#00F6FF>24 tiles in a diamond shape</color>, then teleports to the nearest tile to the target and deals <color=#00F6FF>150%</color> damage to them. If the Active Skill was ready in the last round, the selection range in this round becomes <color=#00F6FF>4 surrounding clusters</color>.",
  str_skill_desc_32019112 = "Selects 1 enemy within <color=#00F6FF>24 tiles in a diamond shape</color>, then teleports to the nearest tile to the target and deals <color=#00F6FF>150%</color> damage to them. If the Active Skill was ready in the last round, the selection range in this round becomes <color=#00F6FF>4 surrounding clusters</color> and the damage is increased to <color=#00F6FF>200%</color>.",
  str_skill_desc_32019113 = "Selects 1 enemy within <color=#00F6FF>24 tiles in a diamond shape</color>, then teleports to the nearest tile to the target and deals <color=#00F6FF>150%</color> damage to 5 tiles in a cross shape. If the Active Skill was ready in the last round, the selection range in this round becomes <color=#00F6FF>4 surrounding clusters</color> and the damage is increased to <color=#00F6FF>200%</color>.",
  str_skill_name_3001912 = "Ominous Flame",
  str_skill_name_3061912 = "Ominous Flame",
  str_skill_desc_3001912 = "Consumes <color=#00F6FF>10%</color> of the team's current HP to deal {1}% damage to <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_passive_name_410191 = "Incinerating Claws",
  str_skill_passive_desc_410191 = "Hati's damage increases as the team's HP decreases, up to <color=#00F6FF>{1}</color> when the team's HP is lower than <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_4101911 = "Hati's damage increases as the team's HP decreases, up to <color=#00F6FF>60%</color> when the team's HP is lower than <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16019111 = "Equipment Skill Enhancement: Bonus goes up to <color=#00F6FF>60%</color> when team HP is lower than 30%.",
  str_skill_upgrade_refine_desc_16019112 = "New Active Skill Effect: If the Active Skill was ready in the last round, the selection range in this round becomes 4 surrounding clusters <color=#00F6FF>and damage is increased to 200%</color>.",
  str_skill_upgrade_refine_desc_16019113 = "Active Skill Enhancement: Deals damage to <color=#00F6FF>5 tiles in a cross shape</color> instead of 1 target.",
  str_skill_name_2001931 = "Radial Currents",
  str_skill_name_2001932 = "Radial Currents",
  str_skill_name_20019333 = "Radial Currents",
  str_skill_name_2201931 = "Radial Currents",
  str_skill_name_2201932 = "Radial Currents",
  str_skill_name_2201933 = "Radial Currents",
  str_skill_name_3001931 = "To The Heavens",
  str_skill_name_3051931 = "To The Heavens",
  str_skill_name_3301931 = "To The Heavens",
  str_skill_name_3351931 = "To The Heavens",
  str_skill_name_3401931 = "To The Heavens Variant I",
  str_skill_name_3451931 = "To The Heavens Variant I",
  str_skill_name_3401932 = "To The Heavens Variant II",
  str_skill_desc_2001931 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>8 tiles in a cross shape</color>.",
  str_skill_desc_2001932 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>12 tiles in a diamond shape</color>.",
  str_skill_desc_20019333 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and enemies in a <color=#00F6FF>cross shape to the maximum range</color>.",
  str_skill_desc_2201931 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>8 tiles in a cross shape</color>. Increases the damage dealt to enemies along a cross shape by 30%.",
  str_skill_desc_2201932 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>12 tiles in a diamond shape</color>. Increases the damage dealt to enemies along a cross shape by 30%.",
  str_skill_desc_2201933 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color> and <color=#00F6FF>a cross shape to the maximum range</color>. Increases the damage dealt to enemies along a cross shape by 30%.",
  str_skill_desc_3001931 = "Attacks in any 1 selected direction, dealing <color=#00F6FF>160%</color> damage to all enemies in this direction.",
  str_skill_desc_3051931 = "Attacks in any 1 selected direction, dealing <color=#00F6FF>200%</color> damage to all enemies in this direction.",
  str_skill_desc_3301931 = "Attacks in any 1 selected direction, dealing <color=#00F6FF>160%</color> damage to all enemies in this direction. The further a target is, the more damage dealt. Final damage increases by <color=#00F6FF>10%</color> per cluster.",
  str_skill_desc_3351931 = "Attacks in any 1 selected direction, dealing <color=#00F6FF>200%</color> damage to all enemies in this direction. The further a target is, the more damage dealt. Final damage increases by <color=#00F6FF>10%</color> per cluster.",
  str_skill_desc_3401931 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Deals 160% damage to all enemies in 1 selected direction, then swaps positions with the <color=#FFFF00>preceding</color> team member. The further the target is, the more damage dealt. Final damage increases by 10% per cluster. <color=#FFFF00>If an outer tile is selected, Kristen moves forward by 1 tile before casting the skill</color>.",
  str_skill_desc_3451931 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Deals 200% damage to all enemies in 1 selected direction, then swaps positions with the <color=#FFFF00>preceding</color> team member. The further the target is, the more damage dealt. Final damage increases by 10% per cluster. <color=#FFFF00>If an outer tile is selected, Kristen moves forward by 1 tile before casting the skill</color>.",
  str_skill_desc_3401932 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. <color=#FFFF00>Without attacking</color>, swaps positions with the <color=#FFFF00>succeeding</color> team member. <color=#FFFF00>Increases damage of next Active Skill by 50%</color>. This damage bonus does not stack when cast more than once.",
  str_skill_passive_name_410193 = "Jetstream Laser",
  str_skill_passive_name_430193 = "Jetstream Laser",
  str_skill_passive_desc_410193 = "Normal attacks will penetrate through enemies, dealing <color=#00F6FF>{1}</color> damage to the target 1 tile behind the enemy.",
  str_skill_passive_desc_430193 = "Normal attacks will penetrate through enemies, dealing <color=#00F6FF>{1}</color> damage to the target 1 tile behind the enemy.",
  str_skill_passive_desc_4401933 = "Normal attacks will penetrate enemies, dealing <color=#00F6FF>60%</color> damage to the target 1 tile behind the enemy. Captain changes for the battle increase by <color=#00F6FF>1</color> when Kristen swaps positions with a team member. Triggers up to 1 time per round.",
  str_skill_upgrade_refine_desc_15019311 = "<color=#00F6FF>New Active Skill Variant I</color>: <color=#FFFF00>Skill cooldown +1 after casting</color>. Deals damage to all enemies in 1 selected direction, then swaps positions with the <color=#FFFF00>preceding</color> team member. The further the target is, the more damage dealt. Final damage increases by 10% per cluster. <color=#FFFF00>If an outer tile is selected, Kristen moves forward by 1 tile before casting the skill</color>.",
  str_skill_upgrade_refine_desc_15019312 = "<color=#00F6FF>New Active Skill Variant II</color>: <color=#FFFF00>Skill cooldown -1 after casting</color>. <color=#FFFF00>Without attacking</color>, swaps positions with the <color=#FFFF00>succeeding</color> team member. <color=#FFFF00>Increases damage of next Active Skill by 50%</color>. This damage bonus does not stack when cast more than once.",
  str_skill_upgrade_refine_desc_15019313 = "Equipment Skill Enhancement: Captain changes for the battle increase by 1 when Kristen swaps positions with a team member. Triggers up to 1 time per round.",
  str_skill_upgrade_desc_15019312 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat.",
  str_skill_upgrade_desc_15019315 = "Active Skill Enhancement: Increases Active Skill damage by <color=#FFFF00>40%</color>.",
  str_skill_upgrade_refine_desc_14004811 = "Equipment Skill Enhancement: For every 1 Yellow tile at the enemy's feet, damage increases by <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_14004812 = "Active Skill Enhancement: Deals double damage to the tile at the center of the skill's range.",
  str_skill_upgrade_refine_desc_14004813 = "Active Skill Enhancement: If Active Skill was ready in the last round, the selection range becomes <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_passive_desc_4400481 = "Increases Dayna's damage against enemies occupying a Yellow tile by <color=#00F6FF>10%</color>. For each Yellow tile at the enemy's feet, the damage bonus increases by <color=#00F6FF>1%</color>. Also grants Thunder Aurorian teammates <color=#00F6FF>50%</color> of this bonus.",
  str_skill_name_3400482 = "Capricious Thunder",
  str_skill_name_3420482 = "Capricious Thunder",
  str_skill_name_3400483 = "Capricious Thunder",
  str_skill_name_3420483 = "Capricious Thunder",
  str_skill_desc_3400482 = "Deals <color=#00F6FF>250%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color> centered on 1 selected tile. Damage dealt to the selected central tile is doubled.",
  str_skill_desc_3420482 = "Deals <color=#00F6FF>250%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color> centered on 1 selected tile. Damage dealt to the selected central tile is doubled. Converts up to 1 tile under the enemy to Yellow.",
  str_skill_desc_3400483 = "Deals <color=#00F6FF>250%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color> centered on 1 selected tile. Damage dealt to the selected central tile is doubled. If this Active Skill was ready in the last round, the selection range becomes <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_3420483 = "Deals <color=#00F6FF>250%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color> centered on 1 selected tile. Damage dealt to the selected central tile is doubled. Converts up to 1 tile under the enemy to Yellow. If this Active Skill was ready in the last round, the selection range becomes <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_upgrade_refine_desc_15009811 = "Chain Combo Enhancement: Increases Chain Combo damage factor by <color=#00F6FF>15%/20%/20%</color>.",
  str_skill_upgrade_refine_desc_15009812 = "Equipment Skill Enhancement: Dismember Mark stacks up to <color=#00F6FF>10 times</color> and each stack increases damage by 6%.",
  str_skill_upgrade_refine_desc_15009813 = "Active Skill Enhancement: Increases Active Skill damage factor to <color=#00F6FF>500%</color>. If the enemy selected by this Active Skill cannot be displaced, <color=#00F6FF>skill cooldown -1</color> after casting.",
  str_skill_desc_2009811 = "Deals <color=#00F6FF>150%</color> damage to 3 enemies within <color=#00F6FF>3 surrounding clusters</color>.",
  str_skill_desc_2009821 = "Deals <color=#00F6FF>160%</color> damage to 4 enemies within <color=#00F6FF>3 surrounding clusters</color>.",
  str_skill_desc_2009831 = "Deals <color=#00F6FF>170%</color> damage to all enemies within <color=#00F6FF>3 surrounding clusters</color>.",
  str_skill_desc_3300981 = "Selects 1 enemy within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>500%</color> damage to it. If the enemy occupies a single tile and can be knocked back, moves it to a selected position within the range of attack. If the enemy cannot be knocked back, <color=#00F6FF>skill cooldown is reduced by 1</color> after casting. If a target that has a Mark is killed, deals DEF-ignoring damage equal to <color=#00F6FF>40%</color> of Cuscuta's ATK to enemies within <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_3350981 = "Selects 1 enemy and deals <color=#00F6FF>500%</color> damage to it. If the enemy occupies a single tile and can be knocked back, it is moved to a selected position within the range of attack. If the enemy cannot be knocked back, <color=#00F6FF>skill cooldown is reduced by 1</color> after casting. If a target that has a Mark is killed, deals DEF-ignoring damage equal to <color=#00F6FF>40%</color> of Cuscuta's ATK to enemies within <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_3200331 = "Deals <color=#00F6FF>95%</color> damage <color=#00F6FF>5</color> times to random enemies on the battlefield. Launches 1 additional attack for each Blue tile within <color=#00F6FF>1 surrounding cluster</color> of the current location. The first instance of damage dealt to each target is <color=#00F6FF>doubled</color>.",
  str_skill_desc_3250331 = "Deals <color=#00F6FF>95%</color> damage <color=#00F6FF>6</color> times to random enemies on the battlefield. Launches 1 additional attack for each Blue tile within <color=#00F6FF>12 surrounding clusters</color> of the unit. The first instance of damage dealt to each target is <color=#00F6FF>doubled</color>.",
  str_skill_passive_desc_4300331 = "Vice gains 1 stack of Locking Mark whenever she deals damage. Each stack increases damage by <color=#00F6FF>2.5%</color> and Chain Combo damage by <color=#00F6FF>5%</color>. All stacks are cleared at the end of the round.",
  str_skill_passive_desc_4300332 = "Vice gains 1 stack of Locking Mark whenever she deals damage. Each stack increases damage by <color=#00F6FF>2.5%</color> and Chain Combo damage by <color=#00F6FF>5%</color>, as well as increases Vice's basic ATK by 0.5%. All stacks are cleared at the end of the round.",
  str_skill_upgrade_refine_desc_15003311 = "Equipment Skill Enhancement: Each Mark stack increases damage by <color=#00F6FF>2.5%</color> and Chain Combo damage by <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_15003312 = "Active Skill Enhancement: The first instance of damage dealt to each target is <color=#00F6FF>doubled</color>.",
  str_skill_upgrade_refine_desc_15003313 = "Equipment Skill Enhancement: Each Mark stack increases basic ATK by <color=#00F6FF>0.5%</color>.",
  str_skill_desc_340093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>250%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack. Final damage increases by <color=#00F6FF>15%</color> for each enemy killed. Stacks up to 10 times. Teleport range increases by 1 surrounding cluster for every 5 enemies killed.",
  str_skill_desc_346093 = "Teleports to any location within <color=#00F6FF>3 surrounding clusters</color> and deals <color=#00F6FF>250%</color> damage to enemies within <color=#00F6FF>1 surrounding cluster</color>. Damage is doubled when there is only 1 enemy in the area of attack. Final damage increases by <color=#00F6FF>15%</color> for each enemy killed. Stacks up to 10 times. Removes Active Skill cooldown if the target is defeated with the skill (once per round). Teleport range increases by 1 surrounding cluster for every 5 enemies killed.",
  str_skill_passive_desc_4300931 = "After casting a Chain Combo or an Active Skill, if the target's HP is lower than <color=#00F6FF>30%</color>, launches 1 more attack dealing DEF-ignoring damage equal to <color=#00F6FF>120%</color> of ATK. If the target has less HP than Migard's ATK after this extra attack, it is killed.",
  str_skill_passive_desc_4300932 = "After casting a Chain Combo or an Active Skill, if the target's HP is lower than <color=#00F6FF>30%</color>, launches 1 more attack dealing DEF-ignoring damage equal to <color=#00F6FF>120%</color> of ATK. If the target has less HP than 250% of Migard's ATK after this extra attack, it is killed.",
  str_skill_upgrade_refine_desc_16009311 = "Equipment Skill Enhancement: The extra attack's damage increases to <color=#00F6FF>120%</color>.",
  str_skill_upgrade_refine_desc_16009312 = "Active Skill Enhancement: Every <color=#00F6FF>5 times</color> this Active Skill gains a damage bonus, the selection range increases by <color=#00F6FF>1 cluster</color>.",
  str_skill_upgrade_refine_desc_16009313 = "Equipment Skill Enhancement: If the target's HP is lower than <color=#00F6FF>250%</color> of Migard's ATK after the extra attack, it is killed.",
  str_skill_upgrade_refine_desc_15001811 = "Equipment Skill Enhancement: The closer enemies are, the more damage Active Skills and Chain Combos deal (up to <color=#00F6FF>110%</color>).",
  str_skill_upgrade_refine_desc_15001812 = "Chain Combo Enhancement: Increases Chain Combo damage factor by <color=#00F6FF>10%/15%/20%</color>.",
  str_skill_upgrade_refine_desc_15001813 = "Equipment Skill Enhancement: Effect range increases to <color=#00F6FF>5 clusters</color>.",
  str_skill_passive_desc_440018 = "Increases ATK by <color=#00F6FF>5%</color> for every enemy within <color=#00F6FF>1 surrounding cluster</color>. The closer enemies are, the more damage Active Skills and Chain Combos deal (up to <color=#00F6FF>110%</color>). Distances beyond 3 clusters offer no damage bonuses.",
  str_skill_passive_desc_450018 = "Increases ATK by <color=#00F6FF>5%</color> for every enemy within <color=#00F6FF>1 surrounding cluster</color>. The closer enemies are, the more damage Active Skills and Chain Combos deal (up to <color=#00F6FF>110%</color>). Distances beyond 5 clusters offer no damage bonuses.",
  str_skill_desc_2400181 = "Deals <color=#00F6FF>115%</color> damage to <color=#00F6FF>1 column</color>.",
  str_skill_desc_2400182 = "Deals <color=#00F6FF>125%</color> damage to <color=#00F6FF>3 columns</color>.",
  str_skill_desc_2400183 = "Deals <color=#00F6FF>130%</color> damage to <color=#00F6FF>5 columns</color>.",
  str_skill_upgrade_refine_desc_16006411 = "Active Skill Enhancement: Skill cooldown is reduced by <color=#00F6FF>2</color> at the beginning of each battle.",
  str_skill_upgrade_refine_desc_16006412 = "Equipment Skill Enhancement: <color=#00F6FF>5</color> bullets can be reserved when using Active Skill. <color=#00F6FF>1</color> bullet can be reserved when any Aurorians use their Active Skill.",
  str_skill_upgrade_refine_desc_16006413 = "Equipment Skill Enhancement: You can manually toggle whether Chain Combos consume ammo.",
  str_skill_passive_desc_440064 = "Can <link=\"30079\"><#FFAE07><u>reserve ammo</u></color></link>. Each time a Chain Combo deals damage, 1 Ammo is consumed (up to <color=#00F6FF>3</color> Ammo can be consumed in the Overload state). For each Ammo consumed, final damage increases by <color=#00F6FF>30%</color>.",
  str_skill_desc_341064 = "Enters the Overload state, in which Wrath's Chain Combo damage increases by <color=#00F6FF>50%</color> and deals damage to the nearest enemy 2 times. Lasts for 2 rounds. Skill cooldown is reduced by <color=#00F6FF>2</color> at the beginning of each battle.",
  str_skill_upgrade_refine_desc_16001911 = [[
Victoria joins the battle with the <link="30039"><#FFAE07><u>Sanity System</u></color></link>.
<color=#00F6FF>New Active Skill Variant I</color>: <color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#FFFF00>300%</color> damage to up to 3 enemies within range. Deals <color=#FFFF00>300%</color> DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to a percentage of the damage dealt. <color=#FFFF00>Additionally loses Sanity equal to the percentage of HP restored</color>.]],
  str_skill_upgrade_refine_desc_16001912 = "Active Skill Enhancement: Active Skill can attack 1 additional enemy.",
  str_skill_upgrade_refine_desc_16001913 = "<color=#00F6FF>New Active Skill Variant II</color>: <color=#FFFF00>Skill cooldown +1 after casting</color>. Deals 250% damage to up to 4 enemies within range. Deals 250% DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to a percentage of the damage dealt. <color=#FFFF00>Additionally restores Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_3200192 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#FFFF00>300%</color> damage to up to 3 enemies within 3 surrounding clusters. Deals <color=#FFFF00>300%</color> DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 25% of the damage dealt. <color=#FFFF00>Additionally loses Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_3200191 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Deals 250% damage to up to 3 enemies within 3 surrounding clusters. Deals 250% DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 25% of the damage dealt. <color=#FFFF00>Additionally restores Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_3230192 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#FFFF00>300%</color> damage to up to 3 enemies within 3 surrounding clusters. Deals <color=#FFFF00>300%</color> DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt. <color=#FFFF00>Additionally loses Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_3230191 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Deals 250% damage to up to 3 enemies within 3 surrounding clusters. Deals 250% DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt. <color=#FFFF00>Additionally restores Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_3260192 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#FFFF00>300%</color> damage to the 3 nearest enemies. Deals <color=#FFFF00>300%</color> DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt. <color=#FFFF00>Additionally loses Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_3260191 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Deals 250% damage to the 3 nearest enemies. Deals 250% DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt. <color=#FFFF00>Additionally restores Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_32001922 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#FFFF00>300%</color> damage to up to 4 enemies within 3 surrounding clusters. Deals <color=#FFFF00>300%</color> DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 25% of the damage dealt. <color=#FFFF00>Additionally loses Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_32001912 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Deals 250% damage to up to 4 enemies within 3 surrounding clusters. Deals 250% DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 25% of the damage dealt. <color=#FFFF00>Additionally restores Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_32301922 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#FFFF00>300%</color> damage to up to 4 enemies within 3 surrounding clusters. Deals <color=#FFFF00>300%</color> DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt. <color=#FFFF00>Additionally loses Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_32301912 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Deals 250% damage to up to 4 enemies within 3 surrounding clusters. Deals 250% DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt. <color=#FFFF00>Additionally restores Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_32601922 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#FFFF00>300%</color> damage to the 4 nearest enemies. Deals <color=#FFFF00>300%</color> DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt. <color=#FFFF00>Additionally loses Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_32601912 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Deals 250% damage to the 4 nearest enemies. Deals 250% DEF-ignoring damage when there is only 1 enemy in range. Final damage dealt to targets increases by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt. <color=#FFFF00>Additionally restores Sanity equal to the percentage of HP restored</color>.",
  str_skill_desc_340019 = "Deals <color=#00F6FF>250%</color> damage to up to 4 enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>250%</color> DEF-ignoring damage when there is only 1 enemy in range. Increases the final damage dealt to targets by 10% for every stack of Bleeding they have. Restores HP equal to 25% of the damage dealt.",
  str_skill_desc_343019 = "Deals <color=#00F6FF>250%</color> damage to up to 4 enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>250%</color> DEF-ignoring damage when there is only 1 enemy in range. Increases the final damage dealt to targets by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt.",
  str_skill_desc_346019 = "Deals <color=#00F6FF>250%</color> damage to the 4 nearest enemies. Deals <color=#00F6FF>250%</color> DEF-ignoring damage when there is only 1 enemy in range. Increases the final damage dealt to targets by 10% for every stack of Bleeding they have. Restores HP equal to 35% of the damage dealt.",
  str_skill_name_290510101 = "Drilling Field",
  str_skill_desc_290510101 = "The Driller randomly selects an open area to move, dealing discharge damage to 4 adjacent tiles. At the end of the move, the skill generates a certain number of Energy Fields and Support Fields within 2 surrounding clusters.",
  str_skill_desc_290511102 = "The Driller randomly selects an open area to move, dealing discharge damage to 4 adjacent tiles. At the end of the move, this skill generates a certain number of Energy Fields and Support Fields.",
  str_skill_desc_290511103 = "When taking action, generates a certain number of Energy Fields and Support Fields in the surrounding area.",
  str_skill_name_290510102 = "Driller Energy Field",
  str_skill_desc_290510102 = "The Driller absorbs Energy Fields on the field, transforming them into a Drilling Platform on the spot, and deals damage across the field.",
  str_skill_name_290510203 = "Driller Support Field",
  str_skill_desc_290510203 = "The Driller locks onto Aurorians' location with the Drilling Platform and leads the 5 nearest Support Fields to the player to deal damage to the player. Energy charge countdown in 2.",
  str_skill_desc_290510213 = "The Driller locks onto Aurorians' location with the Drilling Platform and leads the 3 nearest Support Fields to the player to deal damage to the player. Energy charge countdown in 1.",
  str_skill_name_290510204 = "Driller Platform Self-Destruct",
  str_skill_desc_290510204 = "The Drilling Platform self-destructs upon gathering full energy, dealing great damage to the entire field.",
  str_skill_name_290510123 = "In Operation",
  str_skill_desc_290510123 = "Driller operates behind the platform. Driller and the Driller Platform have independent HP.",
  str_skill_desc_290511101 = "The Driller moves toward the player, dealing discharge damage to 4 adjacent tiles. At the end of the move, the skill generates Support Fields on 4 adjacent tiles.",
  str_skill_desc_290511203 = "The Driller locks onto the player's location with the Driller Platform and uses all Support Fields to deal damage to the player. The amount of damage dealt to the player increases with the number of Support Fields.",
  str_skill_desc_290512101 = "The Driller focuses on digging, generating a small number of Energy Fields and Support Fields around itself at the start of the round.",
  str_skill_upgrade_desc_16019913 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat.",
  str_skill_upgrade_desc_16019916 = "Equipment Skill Enhancement: When Yingel deals damage to targets that have an Open Wound, she ignores <color=#00F6FF>5%</color> of their DEF for every 1 Open Wound they have. (Valid for Ascension III).",
  str_skill_name_2001991 = "Hyper Focus",
