  str_skill_name_3001991 = "Heaven's Resonance",
  str_skill_desc_3001991 = "Converts any 1 selected tile to a Yellow <link=\"30080\"><#FFAE07><u>cross-shaped Prism tile</u></color></link>.",
  str_skill_passive_name_410199 = "Specialized Reload",
  str_skill_passive_name_420199 = "Specialized Reload",
  str_skill_passive_name_430199 = "Specialized Reload",
  str_skill_passive_name_436199 = "Specialized Reload",
  str_skill_passive_desc_410199 = "Yingel's Normal Attack does damage every <color=#00F6FF>second</color> Normal Attack. Its damage multiplier increases to <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420199 = "Yingel's Normal Attack does damage every <color=#00F6FF>second</color> Normal Attack. Its damage multiplier increases to <color=#00F6FF>{1}</color> and inflicts 1 Open Wound, up to 20 stacks. For every Open Wound a target has, Yingel's Chain Combo final damage increases by <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_430199 = "Yingel's Normal Attack does damage every <color=#00F6FF>second</color> Normal Attack. Its damage multiplier increases to <color=#00F6FF>{1}</color> and inflicts 1 Open Wound, up to 20 stacks. For every Open Wound a target has, Yingel's attacks ignore <color=#00F6FF>3%</color> of their DEF and her Chain Combo final damage increases by <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_436199 = "Yingel's Normal Attack does damage every <color=#00F6FF>second</color> Normal Attack. Its damage multiplier increases to <color=#00F6FF>{1}</color> and inflicts 1 Open Wound, up to 20 stacks. For every Open Wound a target has, Yingel's attacks ignore <color=#00F6FF>5%</color> of their DEF and her Chain Combo final damage increases by <color=#00F6FF>3%</color>.",
  str_skill_desc_1601751002 = "Cross-Shaped Prism Tile",
  str_skill_desc_160175102 = "Consumes <color=#00F6FF>3</color> Cubic Energy to convert any 1 tile into a Cross-Shaped Prism tile.",
  str_skill_name_3400231 = "Sonata of Abyss Variant I",
  str_skill_name_3430231 = "Sonata of Abyss Variant I",
  str_skill_name_3400232 = "Sonata of Abyss Variant II",
  str_skill_name_3430232 = "Sonata of Abyss Variant II",
  str_skill_desc_3400231 = "<color=#FFFF00>Skill cooldown -2 after casting</color>. Deals <color=#FFFF00>250%</color> damage to all enemies. This variant cannot trigger the Equipment Skill's Frighten effect.",
  str_skill_desc_3430231 = "<color=#FFFF00>Skill cooldown -2 after casting</color>. Deals <color=#FFFF00>250%</color> damage to all enemies. This variant cannot trigger the Equipment Skill's Frighten effect.",
  str_skill_desc_3400232 = "<color=#FFFF00>Skill cooldown +2 after casting</color>. <color=#FFFF00>Inflicts all enemies with <link=\"10003\"><#FFAE07><u>Frighten</u></color></link> for 1 round</color> and deals <color=#FFFF00>550%</color> damage to them.",
  str_skill_desc_3430232 = "<color=#FFFF00>Skill cooldown +2 after casting</color>. <color=#FFFF00>Inflicts all enemies with <link=\"10003\"><#FFAE07><u>Frighten</u></color></link> for 1 round</color> and deals <color=#FFFF00>550%</color> damage to them.",
  str_skill_passive_desc_440023 = "Gains 1 stack of Shiver Mark when using a Chain Combo, up to <color=#00F6FF>5</color> stacks. Each stack increases Active Skill damage by <color=#00F6FF>20%</color>. Using an Active Skill inflicts <link=\"10003\"><#FFAE07><u>Frighten</u></color></link> on a number of enemies equivalent to the number of stacks for <color=#00F6FF>1</color> round. Activating the Active Skill <color=#00F6FF>does not clear stacks</color>. If 5 stacks are already present before unleashing a Chain Combo skill, it will deal additional damage the closest enemy. Connolly deals an additional 15% final damage to <link=\"10003\"><#FFAE07><u>Frightened</u></color></link> enemies.",
  str_skill_upgrade_refine_desc_16002311 = "<color=#00F6FF>New Active Skill Variant I</color>: <color=#FFFF00>Skill cooldown -2 after casting</color>. Deals <color=#FFFF00>250%</color> damage to all enemies. This variant cannot trigger the Equipment Skill's Frighten effect.",
  str_skill_upgrade_refine_desc_16002312 = "Equipment Skill Enhancement: Connolly deals <color=#00F6FF>an additional 15% final damage</color> to enemies inflicted with Frighten.",
  str_skill_upgrade_refine_desc_16002313 = "<color=#00F6FF>New Active Skill Variant II</color>: <color=#FFFF00>Skill cooldown +2 after casting</color>. <color=#FFFF00>Inflicts all enemies with <link=\"10003\"><#FFAE07><u>Frighten</u></color></link> for 1 round</color> and deals <color=#FFFF00>550%</color> damage to them.",
  str_skill_name_290520101 = "Ferocious Blitz",
  str_skill_desc_290520101 = "Moves towards Aurorians and deals lots of damage, then retreats away from the target.",
  str_skill_name_290520102 = "Ferocious Blitz",
  str_skill_desc_290520102 = "Deals damage to all Aurorians within range after moving.",
