  str_skill_passive_desc_440090 = "Increases Barbara's damage against enemies occupying a Red tile by <color=#00F6FF>10%</color>. For each Red tile at the enemy's feet, the damage bonus increases by <color=#00F6FF>1%</color>. Also grants Fire Aurorian teammates <color=#00F6FF>50%</color> of this bonus.",
  str_skill_upgrade_refine_desc_15009011 = "Equipment Skill Enhancement: For every 1 Red tile at the enemy's feet, damage bonus increases by <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_15009012 = "<color=#00F6FF>New Active Skill Variant I</color>: <color=#FFFF00>Skill cooldown +1 after casting</color>. Deals <color=#FFFF00>600%</color> damage to all enemies <color=#FFFF00>and stuns them</color>.",
  str_skill_upgrade_refine_desc_15009013 = "<color=#00F6FF>New Active Skill Variant II</color>: <color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#FFFF00>450%</color> damage to all enemies.",
  str_skill_name_5000961 = "Link",
  str_skill_desc_5000961 = "When Aurorians enter within 2 surrounding clusters of the Spikepest, a link is automatically established between them. The link breaks when Aurorians move 4 surrounding clusters away from the Spikepest. While linked, the Spikepest shares 50% of the damage received by the player.",
