  str_skill_passive_name_436192 = "Seal of Thorns",
  str_skill_passive_desc_410192 = "Gains 1 <color=#00F6FF>Thorn</color> for every 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> obtained by the team (including <link=\"30065\"><#FFAE07><u>absorbed</u></color></link> tiles). Each Thorn increases Chain Combo damage rate by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_416192 = "Gains 1 <color=#00F6FF>Thorn</color> for every 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> obtained by the team (including <link=\"30065\"><#FFAE07><u>absorbed</u></color></link> tiles). Each Thorn increases Chain Combo damage rate by <color=#00F6FF>{1}</color>. Gains <color=#00F6FF>5</color> Thorns at the start of every wave.",
  str_skill_passive_desc_430192 = "Gains 1 <color=#00F6FF>Thorn</color> for every 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> obtained by the team (including <link=\"30065\"><#FFAE07><u>absorbed</u></color></link> tiles). Each Thorn increases Chain Combo damage rate by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_436192 = "Gains 1 <color=#00F6FF>Thorn</color> for every 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> obtained by the team (including <link=\"30065\"><#FFAE07><u>absorbed</u></color></link> tiles). Each Thorn increases Chain Combo damage rate by <color=#00F6FF>{1}</color>. Gains <color=#00F6FF>5</color> Thorns at the start of every wave.",
  str_skill_passive_desc_440192 = "Gains 1 <color=#00F6FF>Thorn</color> for every 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> obtained by the team (including <link=\"30065\"><#FFAE07><u>absorbed</u></color></link> tiles). Each Thorn increases Chain Combo damage rate by <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_446192 = "Gains 1 <color=#00F6FF>Thorn</color> for every 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> obtained by the team (including <link=\"30065\"><#FFAE07><u>absorbed</u></color></link> tiles). Each Thorn increases Chain Combo damage rate by <color=#00F6FF>3%</color>. Gains <color=#00F6FF>5</color> Thorns at the start of every wave.",
  str_skill_upgrade_refine_desc_16019211 = "Equipment Skill Enhancement: Each Thorn increases Chain Combo damage by <color=#00F6FF>3%</color>.",
  str_skill_upgrade_refine_desc_16019212 = "Equipment Skill Enhancement: Gains <color=#00F6FF>5</color> Thorns at the start of the battle.",
  str_skill_upgrade_refine_desc_16019213 = "Active Skill Enhancement: Generates <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> randomly within the area of effect.",
  str_skill_passive_desc_440193 = "Gains 1 <color=#00F6FF>Thorn</color> for every 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> obtained by the team (including <link=\"30065\"><#FFAE07><u>absorbed</u></color></link> tiles). Each Thorn increases Chain Combo damage by <color=#00F6FF>3%</color>. Gains <color=#00F6FF>5</color> Thorns at the start of the battle.",
  str_skill_passive_desc_446193 = "Gains 1 <color=#00F6FF>Thorn</color> for every 1 <link=\"20001\"><#FFAE07><u>enhanced tile</u></color></link> obtained by the team (including <link=\"30065\"><#FFAE07><u>absorbed</u></color></link> tiles). Each Thorn increases Chain Combo damage rate by <color=#00F6FF>3%</color>. Gains <color=#00F6FF>5</color> Thorns at the start of the battle and the start of every wave.",
  str_skill_upgrade_desc_16019213 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat.",
  str_skill_upgrade_desc_16019216 = "Equipment Skill Enhancement: Gains <color=#00F6FF>5</color> Thorns at the start of every wave.",
  str_skill_name_5010152 = "Encourage",
  str_skill_desc_5010152 = "Shadow Walker moves to the area with the most friendly units and applies Strength Mark to all allies, granting increased ATK.",
  str_skill_name_888450061 = "Reef Cozen",
  str_skill_desc_888450061 = "Summons 1 Cozen that attacks Aurorians every 2 rounds.",
  str_skill_desc_888450081 = "Siphorb absorbs energy from the tile it stands on and tiles that share the same element within 1 surrounding cluster, then unleashes an Energy Orb that attacks all enemies. Damage increases with the number of tiles absorbed. Generates a Dangerous Area where Aurorians are standing 2 rounds after hitting Aurorians.",
  str_skill_upgrade_refine_desc_13004611 = "Equipment Skill Enhancement: <color=#00F6FF>Doubles</color> the Normal Attack damage bonus Keating receives from each Laughter Mark.",
  str_skill_upgrade_refine_desc_13004613 = "Equipment Skill Enhancement: Every Normal Attack Keating deals has a <color=#00F6FF>35%</color> chance to inflict 1 Laughter Mark on enemies.",
  str_skill_passive_desc_4400461 = "Killing enemies with Laughter Mark inflicts <color=#00F6FF>1</color> additional stack of Laughter Mark to all remaining enemies. Each mark increases Thunder Aurorians' Normal Attack damage by <color=#00F6FF>1.8%</color>. The bonus Keating receives is <color=#00F6FF>doubled</color>.",
  str_skill_desc_340046 = "Reduces skill cooldown by <color=#00F6FF>2</color> at the start of the battle. Generates a clone on a selected tile that pulls over enemies within <color=#00F6FF>3 surrounding clusters</color> and inflicts <link=\"10006\"><#FFAE07><u>Slow</u></color></link> on enemies with 5 stacks of Mark for 2 rounds.",
  str_skill_desc_342046 = "Reduces skill cooldown by <color=#00F6FF>2</color> at the start of the battle. Generates a clone on a selected tile that pulls over enemies within <color=#00F6FF>3 surrounding clusters</color> and inflicts <link=\"10006\"><#FFAE07><u>Slow</u></color></link> on enemies with 4 stacks of Mark for 2 rounds and inflicts <link=\"10004\"><#FFAE07><u>Paralysis</u></color></link> on enemies with 6 stacks of Mark for 1 round.",
  str_skill_desc_345046 = "Reduces skill cooldown by <color=#00F6FF>2</color> at the start of the battle. Generates a clone on a selected tile that pulls over <color=#00F6FF>all</color> enemies and inflicts <link=\"10006\"><#FFAE07><u>Slow</u></color></link> on enemies with 4 stacks of Mark for 2 rounds and inflicts <link=\"10004\"><#FFAE07><u>Paralysis</u></color></link> on enemies with 6 stacks of Mark for 1 round.",
  str_skill_passive_desc_4400463 = "Killing enemies with Laughter Mark inflicts <color=#00F6FF>+1</color> additional stack to all remaining enemies. Each mark increases Thunder Aurorians' Normal Attack damage by <color=#00F6FF>2%</color>. The bonus Keating receives is <color=#00F6FF>doubled</color>. Every Normal Attack Keating deals has a <color=#00F6FF>35%</color> chance to inflict 1 Laughter Mark on enemies.",
  str_skill_upgrade_refine_desc_16006011 = "Equipment Skill Enhancement: Increases the splash damage of Normal Attacks dealt in the Noon state to <color=#00F6FF>60%</color>.",
  str_skill_upgrade_refine_desc_16006012 = "Equipment Skill Enhancement: Increases the damage of Normal Attacks dealt in the Noon state by <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_16006013 = "Chain Combo Enhancement: Increases the range of the Chain Combo by 1 surrounding cluster in the Noon state.",
  str_skill_passive_desc_4400601 = "In the Noon state, Normal Attacks deal <color=#00F6FF>20%</color> increased damage and an additional <color=#00F6FF>60%</color> <link=\"30015\"><#FFAE07><u>Splash</u></color></link> damage to all targets in <color=#00F6FF>4 tiles in a cross shape</color> around the enemy.",
  str_skill_passive_desc_4400602 = "In the Noon state, Normal Attacks deal <color=#00F6FF>25%</color> increased damage and an additional <color=#00F6FF>60%</color> <link=\"30015\"><#FFAE07><u>Splash</u></color></link> damage to all targets in <color=#00F6FF>4 tiles in a cross shape</color> around the enemy.",
  str_skill_desc_243601 = "Deals <color=#00F6FF>155%</color> damage to 4 enemies within <color=#00F6FF>2 surrounding clusters</color>. Increases the range by 1 surrounding cluster in the Noon state.",
  str_skill_desc_243602 = "Deals <color=#00F6FF>160%</color> damage to 4 enemies within <color=#00F6FF>3 surrounding clusters</color>. Increases the range by 1 surrounding cluster in the Noon state.",
  str_skill_desc_243603 = "Deals <color=#00F6FF>175%</color> damage to 4 enemies within <color=#00F6FF>4 surrounding clusters</color>. Increases the range by 1 surrounding cluster in the Noon state.",
