  str_skill_desc_2102003 = "Deals <color=#00F6FF>{1}%</color> damage to the 3 nearest enemies.",
  str_skill_desc_300200 = "Selects up to 2 enemies via the tiles beneath them, dealing <color=#00F6FF>{1}%</color> damage to them. All enemies on the selected tiles and tiles in between are <link=\"30081\"><#FFAE07><u>pulled</u></color></link> to the center of this area. If only one enemy is selected, they will only take damage and will not be pulled.",
  str_skill_desc_305200 = "Choose up to 2 enemies via a tile they occupy and deal <color=#00F6FF>{1}%</color> damage to them. All enemies on the selected tiles and tiles in between are <link=\"30081\"><#FFAE07><u>pulled</u></color></link> towards the center of the formed area. If only 1 enemy is selected, they will only receive damage but will not be pulled. Final damage increases by <color=#00F6FF>10%</color> for every <color=#00F6FF>1</color> tile an enemy is pulled over.",
  str_skill_desc_320200 = "Choose up to 2 enemies via a tile they occupy and deal <color=#00F6FF>{1}%</color> damage to them. All enemies on the selected tiles and tiles in between are <link=\"30081\"><#FFAE07><u>pulled</u></color></link> towards the center of the formed area. If only 1 enemy is selected, Anatoli will substitute as the second target and gather at the center.",
  str_skill_desc_325200 = "Choose up to 2 enemies via a tile they occupy and deal <color=#00F6FF>{1}%</color> damage to them. All enemies on the selected tiles and tiles in between are <link=\"30081\"><#FFAE07><u>pulled</u></color></link> towards the center of the formed area. If only 1 enemy is selected, Anatoli will substitute as the second target and gather at the center. Final damage increases by <color=#00F6FF>10%</color> for every <color=#00F6FF>1</color> tile an enemy is pulled over.",
  str_skill_passive_desc_410200 = "Anatoli's Chain Combos deal an additional <color=#00F6FF>{1}</color> damage to random enemies adjacent to the target.",
  str_skill_passive_desc_430200 = "Anatoli's Chain Combos deal an additional <color=#00F6FF>{1}</color> damage to random enemies adjacent to the target. <color=#00F6FF>Single-target</color> Chain Combos of all allies deal <color=#00F6FF>7%</color> increased final damage to <link=\"30082\"><#FFAE07><u>clustered</u></color></link> enemies.",
  str_skill_upgrade_desc_15020012 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat.",
  str_skill_upgrade_desc_15020015 = "Active Skill Enhancement: Increases final damage by <color=#00F6FF>10%</color> for every <color=#00F6FF>1</color> tile enemies are pulled.",
  str_skill_name_290530101 = "Terror Mark",
  str_skill_desc_290530101 = "Deals damage to the target directly and generates a mark on the tile the target is on.",
  str_skill_name_290530102 = "Dread Rush",
  str_skill_desc_290530102 = "Advance up to 2 tiles towards the target, dealing damage to targets along the way and within 4 tiles in a cross shape at the destination. If Dread Rush misses the target, Helios releases an additional Terror Mark.",
