  str_skill_passive_name_410205 = "Pleasant Greeting",
  str_skill_passive_name_430205 = "Pleasant Greeting",
  str_skill_passive_desc_410205 = "Blanc: Pura Cordis does not perform normal attacks when she is on a Blue tile. Whenever she passes through 1 Blue tile, she gains 1 stack of Hospitality if there are any enemies within <color=#00F6FF>4 tiles in a cross shape</color>. Each stack of Hospitality increases Chain Combo damage rate by <color=#00F6FF>{1}</color> and decreases the Chain Combo trigger condition by <color=#00F6FF>1</color>. All stacks are removed after she uses a Chain Combo.",
  str_skill_passive_desc_430205 = "Blanc: Pura Cordis does not perform normal attacks when she is on a Blue tile. Whenever she passes through 1 Blue tile, she gains 1 stack of Hospitality if there are any enemies or broken tiles within <color=#00F6FF>4 tiles in a cross shape</color>. Each stack of Hospitality increases Chain Combo damage rate by <color=#00F6FF>{1}</color> and decreases the Chain Combo trigger condition by <color=#00F6FF>1</color>. All stacks are removed after she uses a Chain Combo.",
  str_skill_upgrade_desc_15020512 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat.",
  str_skill_upgrade_desc_15020515 = "Chain Combo Enhancement: The duration of broken tiles within the range of the Chain Combo is reduced by <color=#FFFF00>2/3/4</color> rounds (valid for Ascension II).",
  str_skill_passive_desc_440097 = "Normal attacks become 2-combo attacks that deal <color=#00F6FF>60%</color> of base damage each hit. Each attack has a <color=#00F6FF>20%</color> chance to deal <color=#00F6FF>50%</color> extra damage. Each combo increases the trigger chance by <color=#00F6FF>1%</color>, up to 50%.",
  str_skill_name_3400971 = "Frigid Debone Variant I",
  str_skill_name_3400972 = "Frigid Debone Variant II",
  str_skill_name_3420971 = "Frigid Debone Variant I",
  str_skill_name_3420972 = "Frigid Debone Variant II",
  str_skill_desc_3400971 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Teleports to any location and deals damage to enemies in a rectangle shape between the starting point and the destination. The smaller the area, the higher the damage dealt, up to <color=#00F6FF>600%</color> damage.",
  str_skill_desc_3400972 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Teleports to any location within <color=#FFFF00>3 surrounding clusters</color> and deals damage to enemies in a rectangle shape between the starting point and the destination. The smaller the area, the higher the damage dealt, up to <color=#00F6FF>360%</color> damage.",
  str_skill_desc_3420971 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Teleports to any location and deals damage to enemies in a rectangle shape between the starting point and the destination. The smaller the area, the higher the damage dealt, up to <color=#00F6FF>720%</color> damage.",
  str_skill_desc_3420972 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Teleports to any location within <color=#FFFF00>3 surrounding clusters</color> and deals damage to enemies in a rectangle shape between the starting point and the destination. The smaller the area, the higher the damage dealt, up to <color=#00F6FF>480%</color> damage.",
  str_skill_upgrade_refine_desc_15009711 = "<color=#00F6FF>New Active Skill Variant I</color>: <color=#FFFF00>Skill cooldown +1 after casting</color>. Teleports to any location and deals damage to enemies in a rectangle shape between the starting point and the destination. The smaller the area, the higher the damage dealt. Active Skill damage increases by <color=#FFFF00>120%</color>.",
  str_skill_upgrade_refine_desc_15009712 = "Equipment Skill Enhancement: Each combo increases the chance to trigger additional damage by <color=#00F6FF>1%</color>, up to 50%.",
  str_skill_upgrade_refine_desc_15009713 = "<color=#00F6FF>New Active Skill Variant II</color>: <color=#FFFF00>Skill cooldown -1 after casting</color>. Teleports to any location within <color=#FFFF00>3 surrounding clusters</color> and deals damage to enemies in a rectangle shape between the starting point and the destination. The smaller the area, the higher the damage dealt. Active Skill damage reduces by <color=#FFFF00>120%</color>.",
  str_skill_upgrade_refine_desc_16002711 = "Active Skill Enhancement: Active Skill damage factor increases to <color=#00F6FF>360%</color>.",
  str_skill_upgrade_refine_desc_16002712 = "Equipment Skill Enhancement: Gains <color=#00F6FF>2</color> stacks of Silent Thunder Mark upon casting Active Skill.",
  str_skill_upgrade_refine_desc_16002713 = "Equipment Skill Enhancement: Normal Attacks consume 1 stack of Silent Thunder Mark to deal extra damage equal to <color=#00F6FF>2.5%</color> of current HP to enemies. This damage will not be lower than <color=#00F6FF>50%</color> of Michael's ATK.",
  str_skill_desc_3400271 = "Dashes to the selected location, dealing <color=#00F6FF>360%</color> damage, and extra damage equal to <color=#00F6FF>5%</color> of their current HP to enemies along the way and on adjacent tiles.",
  str_skill_desc_3430271 = "Dashes to the selected location, dealing <color=#00F6FF>360%</color> damage, and extra damage equal to <color=#00F6FF>5%</color> of their current HP to enemies along the way and on adjacent tiles, and then instantly casts a Chain Combo once at the selected location corresponding to the distance traveled.",
  str_skill_desc_3400272 = "Dashes to the selected location, dealing <color=#00F6FF>360%</color> damage, and extra damage equal to <color=#00F6FF>5%</color> of their current HP to enemies along the way and on adjacent tiles.",
  str_skill_desc_3430272 = "Dashes to the selected location, dealing <color=#00F6FF>360%</color> damage, and extra damage equal to <color=#00F6FF>5%</color> of their current HP to enemies along the way and on adjacent tiles, and then instantly casts a Chain Combo once at the selected location corresponding to the distance traveled.",
  str_skill_desc_4400271 = "Grants 1 stack of Silent Thunder Mark at the start of each round and when using a Chain Combo, and 2 stacks of Silent Thunder Mark when using an Active Skill. Normal Attacks consume 1 stack of Silent Thunder Mark to deal extra damage equal to <color=#00F6FF>2.5%</color> of current HP to the enemy.",
  str_skill_desc_440027 = "Grants 1 stack of Silent Thunder Mark at the start of each round and when using a Chain Combo, and 2 stacks of Silent Thunder Mark when using an Active Skill. Normal Attacks consume 1 stack of Silent Thunder Mark to deal extra damage equal to <color=#00F6FF>2.5%</color> of current HP to the enemy. This damage will not be lower than <color=#00F6FF>50%</color> of Michael's ATK.",
  str_skill_name_490250101 = "Forsaken: Restoration Phantom",
  str_skill_desc_490250101 = "Forsaken: Minos absorbs enhanced tiles and weakened tiles within 2 surrounding clusters, then deals damage to targets within 1 surrounding cluster. The damage of this attack is enhanced based on the number of tiles absorbed.",
  str_skill_name_490250102 = "Forsaken: Immolation Finale",
  str_skill_desc_490250102 = "Forsaken: Minos absorbs all enhanced and weakened tiles on the board, then deals damage to Aurorians. Minos deals damage 1 extra time for each tile absorbed.",
  str_skill_name_490250103 = "Forsaken: Restoration Phantom+",
  str_skill_desc_490250103 = "Forsaken: Minos absorbs enhanced tiles and weakened tiles within 2 surrounding clusters, then deals damage to targets within 1 surrounding cluster. The damage of this attack is enhanced based on the number of tiles absorbed.",
  str_skill_name_490250104 = "Forsaken: Immolation Finale+",
  str_skill_desc_490250104 = "Forsaken: Minos absorbs all enhanced and weakened tiles on the board, then deals damage to Aurorians. Minos deals damage 1 extra time for each tile absorbed.",
  str_skill_upgrade_refine_desc_16002811 = "Equipment Skill Enhancement: Increases recovery factor to <color=#00F6FF>1.8%</color>.",
  str_skill_upgrade_refine_desc_16002812 = "Active Skill Enhancement: Increases recovery factor to <color=#00F6FF>250%</color>.",
  str_skill_upgrade_refine_desc_16002813 = "Active Skill Enhancement: The lower the team's HP, the higher the healing effectiveness, up to an additional <color=#00F6FF>100% bonus</color>.",
  str_skill_passive_desc_450028 = "Each Blue tile generated on the map recovers the team's HP by <color=#00F6FF>1.8%</color> of Raphael's HP. The lower the team's HP, the higher the healing effectiveness, up to an additional <color=#00F6FF>100% bonus</color>.",
  str_skill_desc_350028 = "Recovers the team's HP by <color=#00F6FF>250%</color> of Raphael's ATK. Resets <color=#00F6FF>all non-Blue</color> tiles.",
  str_skill_desc_356028 = "Recovers the team's HP by <color=#00F6FF>250%</color> of Raphael's ATK. Resets <color=#00F6FF>all non-Blue</color> tiles, and has a <color=#00F6FF>small chance</color> to generate Blue tiles.",
  str_skill_desc_360028 = "Recovers the team's HP by <color=#00F6FF>250%</color> of Raphael's ATK. Resets <color=#00F6FF>all non-Blue</color> tiles. The lower the team's HP, the higher the healing effectiveness, up to an additional <color=#00F6FF>100% bonus</color>.",
  str_skill_desc_366028 = "Recovers the team's HP by <color=#00F6FF>250%</color> of Raphael's ATK. Resets <color=#00F6FF>all non-Blue</color> tiles, with a <color=#00F6FF>small chance</color> to generate Blue tiles. The lower the team's HP, the higher the healing effectiveness, up to an additional <color=#00F6FF>100% bonus</color>.",
  str_skill_upgrade_refine_desc_15007011 = "Active Skill Enhancement: Increases the damage factor to <color=#00F6FF>100%</color>.",
  str_skill_upgrade_refine_desc_15007012 = "Equipment Skill Enhancement: Increases the damage factor to <color=#00F6FF>60%</color>.",
  str_skill_upgrade_refine_desc_15007013 = "Active Skill Enhancement: When dealing damage, there is a <color=#00F6FF>25%</color> chance to inflict 1 stack of <link=\"10002\"><#FFAE07><u>Burn</u></color></link>.",
  str_skill_desc_350070 = "Deals <color=#00F6FF>100%</color> damage <color=#00F6FF>5</color> times to random enemies on the field. Launches 1 additional attack for each Red tile within <color=#00F6FF>1 surrounding cluster</color> of the unit.",
  str_skill_desc_355070 = "Deals <color=#00F6FF>100%</color> damage <color=#00F6FF>6</color> times to random enemies on the field. Launches 1 additional attack for each Red tile within <color=#00F6FF>12 adjacent tiles</color>.",
  str_skill_desc_360070 = "Deals <color=#00F6FF>100%</color> damage <color=#00F6FF>5</color> times to random enemies on the field. Launches 1 additional attack for each Red tile within <color=#00F6FF>1 surrounding cluster</color> of the unit. When dealing damage, there is a <color=#00F6FF>25%</color> chance to inflict 1 stack of <link=\"10002\"><#FFAE07><u>Burn</u></color></link>.",
  str_skill_desc_365070 = "Deals <color=#00F6FF>100%</color> damage <color=#00F6FF>6</color> times to random enemies on the field. Launches 1 additional attack for each Red tile within <color=#00F6FF>12 adjacent tiles</color>. When dealing damage, there is a <color=#00F6FF>25%</color> chance to inflict 1 stack of <link=\"10002\"><#FFAE07><u>Burn</u></color></link>.",
  str_skill_passive_desc_450070 = "Normal Attacks have a <color=#00F6FF>75%</color> chance to trigger 1 Red Dragon Attack that deals damage equal to <color=#00F6FF>60%</color> of Leona's Normal Attack damage, and inflicts 1 stack of <link=\"10002\"><#FFAE07><u>Burn</u></color></link> for 2 rounds.",
  str_skill_desc_400140110 = "When Aurorians start to move, Tentaclaw curls up to avoid attacks and restores HP for Mirren Gautier.",
  str_skill_upgrade_desc_16020713 = "Equipment Skill Enhancement: Reduces the number of Ripple stacks required to trigger the effect to 5. Reduces the number of Ripple stacks consumed to a multiple of 5 stacks instead. (Valid for Ascension I)",
  str_skill_upgrade_desc_16020716 = "Active Skill Enhancement: Converts the selected tile to blue.",
