  str_skill_desc_3002071 = "Selects 1 tile and makes all blue tiles in the same column <link=\"30084\"><#FFAE07><u>converge</u></color></link> towards the selected tile.",
  str_skill_desc_3062071 = "Selects 1 tile and converts this tile to blue, then makes all blue tiles in the same column <link=\"30084\"><#FFAE07><u>converge</u></color></link> towards the selected tile.",
  str_skill_desc_3202071 = "Selects 1 tile and makes all blue tiles in the same column <link=\"30084\"><#FFAE07><u>converge</u></color></link> towards the selected tile. Tapping it again will make the effect alternate between <color=#00F6FF>row/column</color>.",
  str_skill_desc_3262071 = "Selects 1 tile and converts this tile to blue, then makes all blue tiles in the same column <link=\"30084\"><#FFAE07><u>converge</u></color></link> towards the selected tile. Tapping it again will make the effect alternate between <color=#00F6FF>row/column</color>.",
  str_skill_desc_3302071 = "Selects 1 tile and makes all blue tiles in the same column <link=\"30084\"><#FFAE07><u>converge</u></color></link> towards the selected tile. Tapping it again will make the effect alternate between <color=#00F6FF>row/column</color>. Gains 1 stack of Ripple for every 1 blue tile within range of the Active Skill.",
  str_skill_desc_3362071 = "Selects 1 tile and converts this tile to blue, then makes all blue tiles in the same column <link=\"30084\"><#FFAE07><u>converge</u></color></link> towards the selected tile. Tapping it again will make the effect alternate between <color=#00F6FF>row/column</color>. Gains 1 stack of Ripple for every 1 blue tile within range of the Active Skill.",
  str_skill_passive_name_410207 = "From Dawn Til Dusk",
  str_skill_passive_desc_410207 = "Cena gains 1 stack of <link=\"30085\"><#FFAE07><u>Ripple</u></color></link> when Aurorians on the team cast an Active Skill for the first time in the round. If Cena already has 7 or more stacks of Ripple when gaining a stack, they are consumed to recover HP equal to <color=#00F6FF>{1}</color> of Cena's Max HP.",
  str_skill_passive_name_416207 = "From Dawn Til Dusk",
  str_skill_passive_desc_416207 = "Cena gains 1 stack of <link=\"30086\"><#FFAE07><u>Ripple</u></color></link> when Aurorians in the team cast an Active Skill for the first time in the round. If Cena already has 5 or more stacks of Ripple when gaining a stack, a portion is consumed to recover HP equal to <color=#00F6FF>{1}</color> of Cena's Max HP.",
  str_skill_desc_350025 = "Deals <color=#00F6FF>300%</color> damage to <color=#00F6FF>3 selected columns</color> or <color=#00F6FF>3 selected rows</color> and knocks enemies back. Damage dealt to the middle row or column will be 1.7 times the damage dealt to the two sides. Resets all <color=#00F6FF>non-Red</color> tiles within the area of attack.",
  str_skill_desc_356025 = "Deals <color=#00F6FF>300%</color> damage to <color=#00F6FF>3 selected columns</color> or <color=#00F6FF>3 selected rows</color> and knocks enemies back. Damage dealt to the middle row or column will be 1.7 times the damage dealt to the two sides. Resets all <color=#00F6FF>non-Red</color> tiles within the area of attack, and has a <color=#00F6FF>small chance</color> to generate Red tiles.",
  str_skill_desc_360025 = "Deals <color=#00F6FF>340%</color> damage to <color=#00F6FF>3 selected columns</color> or <color=#00F6FF>3 selected rows</color> and knocks enemies back. Damage dealt to the middle row or column will be 1.7 times the damage dealt to the two sides. Resets all <color=#00F6FF>non-Red</color> tiles within the area of attack.",
  str_skill_desc_366025 = "Deals <color=#00F6FF>340%</color> damage to <color=#00F6FF>3 selected columns</color> or <color=#00F6FF>3 selected rows</color> and knocks enemies back. Damage dealt to the middle row or column will be 1.7 times the damage dealt to the two sides. Resets all <color=#00F6FF>non-Red</color> tiles within the area of attack, and has a <color=#00F6FF>small chance</color> to generate Red tiles.",
  str_skill_passive_desc_440025 = "Normal attacks <color=#00F6FF>can now attack diagonally</color>. Normal attacks deal additional DEF-ignoring damage equal to <color=#00F6FF>12%</color> of ATK.",
