  str_skill_desc_3062092 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Select 1 tile to deal <color=#00F6FF>100%</color> damage to 9 tiles in a square shape. If the caster is within the skill's range, the final damage is increased by <color=#00F6FF>30%</color>.",
  str_skill_desc_3062093 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Deals <color=#00F6FF>300%</color> damage to all tiles and final damage increases by <color=#00F6FF>30%</color>.",
  str_skill_passive_name_410209 = "Thunder Fury",
  str_skill_passive_name_420209 = "Thunder Fury",
  str_skill_passive_name_430209 = "Thunder Fury",
  str_skill_passive_desc_410209 = "Enemies attacked by the Active Skill will enter Thunderous Echo status for <color=#00F6FF>2 rounds</color>. Deals <color=#00F6FF>{1}</color> damage to targets under the Thunderous Echo status within <color=#00F6FF>12 tiles in a diamond shape</color> for each tile the team traverses.",
  str_skill_passive_desc_420209 = "Enemies attacked by the Active Skill will enter Thunderous Echo status for <color=#00F6FF>2 rounds</color>. Deals <color=#00F6FF>{1}</color> damage to targets under the Thunderous Echo status within <color=#00F6FF>12 tiles in a diamond shape</color> for each tile the team traverses.",
  str_skill_passive_desc_430209 = "Normal attacks can target enemies within <color=#00F6FF>8 tiles in a cross shape</color>. Enemies attacked by the Active Skill will enter Thunderous Echo status for <color=#00F6FF>2 rounds</color>. Deals <color=#00F6FF>{1}</color> damage to targets under the Thunderous Echo status within <color=#00F6FF>12 tiles in a diamond shape</color> for each tile the team traverses.",
  str_skill_passive_desc_440209 = "Normal attacks can target enemies within <color=#00F6FF>8 tiles in a cross shape</color>. Enemies attacked by the Active Skill will enter Thunderous Echo status for <color=#00F6FF>2 rounds</color>. Deals <color=#00F6FF>50%</color> damage to targets under the Thunderous Echo status within <color=#00F6FF>12 tiles in a diamond shape</color> for each tile the team traverses.",
  str_skill_upgrade_refine_desc_16020911 = "Equipment Skill Enhancement: Increases the damage factor to <color=#00F6FF>50%</color>.",
  str_skill_upgrade_refine_desc_16020912 = "<color=#00F6FF>New Active Skill Variant I</color>: <color=#FFFF00>Skill cooldown +1 after casting</color>. Deals <color=#00F6FF>300%</color> damage to all tiles and final damage increases by <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16020913 = "<color=#00F6FF>New Active Skill Variant II</color>: <color=#FFFF00>Skill cooldown -1 after casting</color>. Select 1 tile to deal <color=#00F6FF>100%</color> damage to 9 tiles in a square shape. If the caster is positioned within the skill's range, the final damage increases by 30%.",
  str_skill_desc_320116 = "Fleur deals <color=#00F6FF>{1}%</color> damage to 1 selected enemy and marks the target, and is able to damage marked targets 1 additional time when using Chain Combos this round. If the Active Skill is ready last round, the final damage this round increases by <color=#00F6FF>35%</color>.",
  str_skill_desc_323116 = "Fleur deals <color=#00F6FF>{1}%</color> damage to 1 selected enemy and marks the target, and is able to damage marked targets 1 additional time when using Chain Combos this round. If the Active Skill is ready last round, the final damage this round increases by <color=#00F6FF>35%</color>.",
  str_skill_upgrade_desc_16011113 = "Equipment Skill Enhancement: Crystal generation range increases to 1/2/3 surrounding clusters.",
  str_skill_upgrade_desc_16011116 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat.",
  str_skill_desc_300111 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies. The fewer the enemies, the greater the damage dealt, up to 2 times the original.",
  str_skill_desc_303111 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies. The fewer the enemies, the greater the damage dealt, up to 2 times the original.",
  str_skill_desc_320111 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies. The fewer the enemies, the greater the damage dealt, up to 2 times the original. Marks the current position <color=#00F6FF>after using Active Skills</color> and when <color=#00F6FF>entering Aurora Time</color>. If the Equipment Skill generates crystals this round, it will trigger once at the marked position.",
  str_skill_desc_323111 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>all</color> enemies. The fewer the enemies, the greater the damage dealt, up to 2 times the original. Marks the current position <color=#00F6FF>after using Active Skills</color> and when <color=#00F6FF>entering Aurora Time</color>. If the Equipment Skill generates crystals this round, it will trigger once at the marked position.",
  str_skill_passive_name_416111 = "Crystal Touch",
  str_skill_passive_name_436111 = "Crystal Touch",
  str_skill_passive_desc_410111 = "Before the enemy takes action, if Beryl has launched a Chain Combo this round, crystals are generated within her <color=#00F6FF>Chain Combo range</color> and will remain there for 1 round. When enemies <link=\"30091\"><#FFAE07><u>touch</u></color></link> her crystals, they take <color=#00F6FF>{1}</color> DEF-ignoring damage (affected by element counters).",
  str_skill_passive_desc_430111 = "Before the enemy takes action, if Beryl has launched a Chain Combo this round, crystals are generated within her <color=#00F6FF>Chain Combo range</color> and will remain there for 1 round. When enemies <link=\"30091\"><#FFAE07><u>touch</u></color></link> her crystals, they take <color=#00F6FF>{1}</color> DEF-ignoring damage (affected by element counters). This damage increases by <color=#00F6FF>10%</color> for each tile connected, up to a maximum of 20 tiles.",
  str_skill_passive_desc_416111 = "Before the enemy takes action, if Beryl has launched a Chain Combo this round, crystals are generated within <color=#00F6FF>1/2/3 surrounding clusters</color> and will remain there for 1 round. When enemies <link=\"30091\"><#FFAE07><u>touch</u></color></link> her crystals, they take <color=#00F6FF>{1}</color> DEF-ignoring damage (affected by element counters).",
  str_skill_passive_desc_436111 = "Before the enemy takes action, if Beryl has launched a Chain Combo this round, crystals are generated within <color=#00F6FF>1/2/3 surrounding clusters</color> and will remain there for 1 round. When enemies <link=\"30091\"><#FFAE07><u>touch</u></color></link> her crystals, they take <color=#00F6FF>{1}</color> DEF-ignoring damage (affected by element counters). This damage increases by <color=#00F6FF>10%</color> for each tile connected, up to a maximum of 20 tiles.",
  str_skill_desc_2001161 = "Deals <color=#00F6FF>{1}%</color> damage to the nearest 2 enemies and <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>Splash</u></color></link> damage to <color=#00F6FF>4 tiles in a cross shape</color> around.",
  str_skill_desc_2001162 = "Deals <color=#00F6FF>{1}%</color> damage to the nearest 2 enemies and <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>Splash</u></color></link> damage to <color=#00F6FF>4 tiles in a cross shape</color> around.",
  str_skill_desc_2001163 = "Deals <color=#00F6FF>{1}%</color> damage to the nearest 2 enemies and <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>Splash</u></color></link> damage to <color=#00F6FF>4 tiles in a cross shape</color> around.",
  str_skill_desc_2061161 = "Deals <color=#00F6FF>{1}%</color> damage to the 2 nearest enemies and <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>splash damage</u></color></link> to <color=#00F6FF>4 tiles in a cross-shaped area</color> around them. This attack ignores all DEF if the target is marked.",
  str_skill_desc_2061162 = "Deals <color=#00F6FF>{1}%</color> damage to the 2 nearest enemies and <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>splash damage</u></color></link> to <color=#00F6FF>4 tiles in a cross-shaped area</color> around them. This attack ignores all DEF if the target is marked.",
  str_skill_desc_2061163 = "Deals <color=#00F6FF>{1}%</color> damage to the 2 nearest enemies and <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>splash damage</u></color></link> to <color=#00F6FF>4 tiles in a cross-shaped area</color> around them. This attack ignores all DEF if the target is marked.",
  str_skill_desc_2201161 = "Deals <color=#00F6FF>{1}%</color> damage to the 2 nearest enemies and <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>splash damage</u></color></link> to <color=#00F6FF>4 tiles in a cross-shaped area</color> around them. This attack ignores 40% of DEF if the target is marked.",
  str_skill_desc_2201162 = "Deals <color=#00F6FF>{1}%</color> damage to the 2 nearest enemies and <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>splash damage</u></color></link> to <color=#00F6FF>4 tiles in a cross-shaped area</color> around them. This attack ignores 40% of DEF if the target is marked.",
  str_skill_desc_2201163 = "Deals <color=#00F6FF>{1}%</color> damage to the 2 nearest enemies and <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>splash damage</u></color></link> to <color=#00F6FF>4 tiles in a cross-shaped area</color> around them. This attack ignores 40% of DEF if the target is marked.",
