  str_skill_desc_20021011 = "Deals <color=#00F6FF>130%</color> damage 2 times, assigned randomly to enemies within <color=#00F6FF>3 surrounding clusters</color> of this unit. When a target takes damage more than once, the damage is halved the second time forth.",
  str_skill_desc_2002102 = "Deals <color=#00F6FF>135%</color> damage 3 times, assigned randomly to enemies within <color=#00F6FF>3 surrounding clusters</color> of this unit. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_2002103 = "Deals <color=#00F6FF>140%</color> damage 4 times, assigned randomly to enemies within <color=#00F6FF>3 surrounding clusters</color>. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_3002101 = "Selects 1 of <color=#00F6FF>4</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>.",
  str_skill_desc_3102101 = "Selects 1 of <color=#00F6FF>4</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>.",
  str_skill_desc_3202101 = "Selects 1 of <color=#00F6FF>4</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>12 tiles in a diamond shape</color> centered on the team's position.",
  str_skill_desc_3302101 = "Selects 1 of <color=#00F6FF>4</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. This damage, along with that triggered by the Equipment Skill, can pierce 1 tile, dealing <color=#00F6FF>halved damage</color> to the pierced tile. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>12 tiles in a diamond shape</color> centered on the team's position.",
  str_skill_desc_3022101 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>.",
  str_skill_desc_3122101 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>.",
  str_skill_desc_3222101 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>12 tiles in a diamond shape</color> from the team's position.",
  str_skill_desc_3322101 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. This damage, along with that triggered by the Equipment Skill, can pierce 1 tile, dealing <color=#00F6FF>halved damage</color> to the pierced tile. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>12 tiles in a diamond shape</color> centered on the team's position.",
  str_skill_desc_3152101 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>.",
  str_skill_desc_3252101 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>12 tiles in a diamond shape</color> from the team's position.",
  str_skill_desc_3352101 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>{1}%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. This damage, along with that triggered by the Equipment Skill, can pierce 1 tile, dealing <color=#00F6FF>halved damage</color> to the pierced tile. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>12 tiles in a diamond shape</color> centered on the team's position.",
  str_skill_passive_desc_410210 = "Each of Joselyne's Normal Attacks and Chain Combos inflict 1 stack of Lingering Will on enemies hit, up to <color=#00F6FF>6</color> stacks. Her Active Skill additionally deals <color=#00F6FF>{1}</color> ATK as damage to the enemy <color=#00F6FF>1 tile ahead</color> multiple times according to the number of Lingering Will stacks on the target. Stacks reset afterwards.",
  str_skill_passive_desc_415210 = "Each of Joselyne's Normal Attacks and Chain Combos inflict 1 stack of Lingering Will on enemies hit, up to <color=#00F6FF>8</color> stacks. Her Active Skill additionally deals <color=#00F6FF>{1}</color> ATK as damage to the enemy <color=#00F6FF>1 tile ahead</color> multiple times according to the number of Lingering Will stacks on the target. Stacks reset afterwards.",
  str_skill_upgrade_desc_15021012 = "Active Skill Enhancement: Selects any of the <color=#FFFF00>8</color> directions and charges toward it.",
  str_skill_upgrade_desc_15021015 = "Equipment Skill Enhancement: Raises the upper limit of Lingering Will stacks to <color=#FFFF00>8</color>.",
  str_skill_name_200330110 = "Psionic Manipulation",
  str_skill_desc_200330110 = "Dreadweaver distances itself from the player team's location. Once the team's movement ends, Dreadweaver will immediately shift the team's location, affecting the position of Chain Combos released by its team.",
  str_skill_name_200330121 = "Blood Sacrifice",
  str_skill_desc_200330121 = "Dreadweaver burns its remaining HP down to 1 point, dealing defense-ignoring true damage to the player. The amount of burned HP directly determines the final DMG. This skill can be cast only once.",
  str_skill_upgrade_refine_desc_15021011 = "Equipment Skill Enhancement: Increases the damage factor to <color=#00F6FF>36%</color>.",
  str_skill_upgrade_refine_desc_15021012 = "Active Skill Enhancement: For every 4 stacks of Lingering Will on the target, deals 120% damage once to all enemies within <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_upgrade_refine_desc_15021013 = "Active Skill Enhancement: Active Skills and Equipment Skills deal full damage on tiles they pierce through.",
  str_skill_passive_desc_440210 = "Each of Joselyne's Normal Attacks and Chain Combos inflict 1 stack of Lingering Will on enemies hit, up to <color=#00F6FF>8</color> stacks. Her Active Skill additionally deals <color=#00F6FF>36%</color> ATK as damage to the enemy <color=#00F6FF>1 tile ahead</color> multiple times according to the number of Lingering Will stacks on the target. Stacks reset afterwards.",
  str_skill_passive_desc_445210 = "Each of Joselyne's Normal Attacks and Chain Combos inflict 1 stack of Lingering Will on enemies hit, up to <color=#00F6FF>8</color> stacks. Her Active Skill additionally deals <color=#00F6FF>36%</color> ATK as damage to the enemy <color=#00F6FF>1 tile ahead</color> multiple times according to the number of Lingering Will stacks on the target. Stacks reset afterwards.",
  str_skill_desc_34021011 = "Selects 1 of <color=#00F6FF>4</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>80%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. This damage, along with that triggered by the Equipment Skill, can pierce 1 tile, dealing <color=#00F6FF>halved damage</color> to the pierced tile. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_34221011 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>80%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. This damage, along with that triggered by the Equipment Skill, can pierce 1 tile, dealing <color=#00F6FF>halved damage</color> to the pierced tile. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_34521011 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>80%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. This damage, along with that triggered by the Equipment Skill, can pierce 1 tile, dealing <color=#00F6FF>halved damage</color> to the pierced tile. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_34021012 = "Selects 1 of <color=#00F6FF>4</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>80%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. This damage, along with that triggered by the Equipment Skill, can pierce 1 tile, dealing <color=#00F6FF>full damage</color> to the pierced tile. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_34221012 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>80%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. This damage, along with that triggered by the Equipment Skill, can pierce 1 tile, dealing <color=#00F6FF>full damage</color> to the pierced tile. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_34521012 = "Selects 1 of <color=#00F6FF>8</color> directions and charges, stopping upon encountering obstacles. Deals <color=#00F6FF>80%</color> damage once to the enemy <color=#00F6FF>1 tile ahead</color>. This damage, along with that triggered by the Equipment Skill, can pierce 1 tile, dealing <color=#00F6FF>full damage</color> to the pierced tile. For every 4 stacks of Lingering Will on the target, additionally deals <color=#00F6FF>120%</color> damage once to all enemies within <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_name_70010981 = "Forsaken: Colossus Sharpness",
