  str_skill_desc_290610102 = "Pushes forward quickly if there is no enemy in front.",
  str_skill_name_290610103 = "All-Round Bombardment",
  str_skill_desc_290610103 = "Deals damage to the Aurorians around the mech and knocks them back. The skill also inflicts damage on the walls.",
  str_skill_name_290610104 = "Flame Jets",
  str_skill_desc_290610104 = "Issues a formidable assault, dealing massive damage to the Aurorians in front and the walls.",
  str_skill_name_290610105 = "Corrupted Mechanic",
  str_skill_desc_290610105 = "Repairs its components when paralyzed, and once the repair is complete, it will redeploy for the siege.",
  str_skill_name_280240101 = "Dispelling Thrust",
  str_skill_desc_280240101 = "Delivers heavy blows on the enemies in front of the Stronghold Gate and Paralyze them.",
  str_skill_name_290570101 = "Mudbundle: Splashing",
  str_skill_name_290570102 = "Mudbundle: Gushing",
  str_skill_name_290570103 = "Mudbundle: Siphoning",
  str_skill_desc_290570101 = "Mudbundle sinks into the mud and emerges at the location nearest to Aurorians, dealing damage to units within 2 surrounding clusters and generating quagmires on the field.",
  str_skill_desc_290570102 = "Mudbundle sinks into the mud and emerges at the location nearest to Aurorians, dealing damage to units within 2 columns in front and generating quagmires on the field.",
  str_skill_desc_290570103 = "Absorbs all tiles on the field and resets them, dealing damage to Aurorians and moving them to a random quagmire.",
