  str_skill_desc_300216 = "Consumes 3 <link=\"30095\"><#FFAE07><u>Spare Parts</u></color></link> to select any 1 tile and generate a Square Thunder Array within <color=#00F6FF>9 tiles in a square shape</color> that lasts for <color=#00F6FF>2</color> rounds. Xuan Ji's normal attack <color=#00F6FF>can be launched diagonally</color> inside a Square Thunder Array.",
  str_skill_desc_303216 = "Consumes 3 <link=\"30095\"><#FFAE07><u>Spare Parts</u></color></link> to select any 1 tile and generate a Square Thunder Array within <color=#00F6FF>25 tiles in a square shape</color> that lasts for <color=#00F6FF>3</color> rounds. Xuan Ji's normal attack <color=#00F6FF>can be launched diagonally</color> inside a Square Thunder Array.",
  str_skill_passive_desc_410216 = "Increases Xuan Ji's damage in a Square Thunder Array by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_416216 = "Increases Xuan Ji's damage in a Square Thunder Array by <color=#00F6FF>{1}</color>. Her damage is further increased by <color=#00F6FF>5%</color> for every additional Square Thunder Array on the field. If Xuan Ji is inside a Square Thunder Array when the round ends, she gains 1 Spare Part.",
  str_skill_passive_desc_430216 = "Increases Xuan Ji's damage in a Square Thunder Array by <color=#00F6FF>{1}</color>. Whenever Xuan Ji is inside a Square Thunder Array after casting her Chain Combo, her Basic ATK is increased by <color=#00F6FF>4%</color>, stacking up to 5 times. If she is not inside a Square Thunder Array when the round ends, the stacks of this effect are halved.",
  str_skill_passive_desc_436216 = "Increases Xuan Ji's damage in a Square Thunder Array by <color=#00F6FF>{1}</color>. Her damage is further increased by <color=#00F6FF>5%</color> for every additional Square Thunder Array on the field. If Xuan Ji is inside a Square Thunder Array when the round ends, she gains 1 Spare Part. Whenever Xuan Ji is inside a Square Thunder Array after casting her Chain Combo, her Basic ATK is increased by <color=#00F6FF>4%</color>, stacking up to 5 times. If she is not inside a Square Thunder Array when the round ends, the stacks of this effect are halved.",
  str_skill_upgrade_desc_16021613 = "Active Skill Enhancement: Expands the area of the Square Thunder Array to <color=#00F6FF>25 tiles in a square shape</color>. Lasts for <color=#00F6FF>3</color> rounds.",
  str_skill_upgrade_desc_16021616 = "Equipment Skill Enhancement: Xuan Ji's damage is further increased by <color=#00F6FF>5%</color> for every additional Square Thunder Array on the field. If Xuan Ji is inside a Square Thunder Array when the round ends, she gains 1 Spare Part.",
  str_skill_name_53820323 = "Explodes when Aurorians approach. If left alone, it will explode after a certain number of rounds have passed and generate several flames around it.",
