  str_skill_desc_3052201 = "Converts <color=#00F6FF>3</color> nearest Yellow tiles to Blue Dark Tiles. If the Active Skill is ready in the last round, increases the tile-converting count by <color=#00F6FF>+1</color> in this round.",
  str_skill_desc_3052202 = "Converts <color=#00F6FF>3</color> nearest Yellow tiles to Blue Dark Tiles. If the Active Skill is ready in the last round, increases the tile-converting count by <color=#00F6FF>+1</color> in this round.",
