  str_skill_passive_name_430220 = "Kaleidoscopic Refractions",
  str_skill_passive_desc_410220 = "At the start of each round, inflicts <color=#00F6FF>Appraisal</color> on 1 farthest target on the field for 1 round. Whenever a target with Appraisal is hit by 1 single target Chain Combo skill, 1 extra attack is launched at the target, dealing damage equal to <color=#00F6FF>{1}</color> of Vergil's ATK.",
  str_skill_passive_desc_420220 = "At the start of each round, inflicts <color=#00F6FF>Appraisal</color> on 1 farthest target on the field for 1 round. Upon entering Aurora Time, it takes effect 1 additional time. Whenever a target with Appraisal is hit by 1 single target Chain Combo skill, 1 extra attack is launched at the target, dealing damage equal to <color=#00F6FF>{1}</color> of Vergil's ATK.",
  str_skill_passive_desc_430220 = "At the start of each round, inflicts <color=#00F6FF>Appraisal</color> on 1 farthest target on the field for 1 round. Upon entering Aurora Time, it takes effect 1 additional time. Whenever a target with Appraisal is hit by 1 single target Chain Combo skill, 1 extra attack is launched at the target, dealing damage equal to <color=#00F6FF>{1}</color> of Vergil's ATK. When the target is hit by Vergil's Chain Combo, this additional damage is doubled.",
  str_skill_upgrade_desc_15022012 = "Active Skill Enhancement: If the Active Skill was ready in the last round, convert 1 additional Yellow tile into a Blue Dark Tile in this round.",
  str_skill_upgrade_desc_15022015 = "Active Skill Enhancement: Increases the number of tiles converted into Blue Dark Tiles by 1.",
