  str_skill_desc_2002181 = "Deals <color=#00F6FF>150%</color> damage to enemies within <color=#00F6FF>2 surrounding clusters</color> 3 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_2002182 = "Deals <color=#00F6FF>155%</color> damage to enemies within <color=#00F6FF>3 surrounding clusters</color> 4 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_2002183 = "Deals <color=#00F6FF>165%</color> damage to enemies within <color=#00F6FF>3 surrounding clusters</color> 5 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_2002184 = "Deals <color=#00F6FF>150%</color> damage to enemies within <color=#00F6FF>2 surrounding clusters</color> 3 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved. Deals damage 1 additional time to the farthest target.",
  str_skill_desc_2002185 = "Deals <color=#00F6FF>155%</color> damage to enemies within <color=#00F6FF>3 surrounding clusters</color> 4 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved. Deals damage 1 additional time to the farthest target.",
  str_skill_desc_2002186 = "Deals <color=#00F6FF>165%</color> damage to enemies within <color=#00F6FF>3 surrounding clusters</color> 5 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved. Deals damage 1 additional time to the farthest target.",
  str_skill_desc_2202181 = "Deals <color=#00F6FF>150%</color> damage to enemies within <color=#00F6FF>2 surrounding clusters</color> 3 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved. For each Dark Tile passed through while connecting tiles this time, the Chain Combo's range expands by 1 surrounding cluster.",
  str_skill_desc_2202182 = "Deals <color=#00F6FF>155%</color> damage to enemies within <color=#00F6FF>3 surrounding clusters</color> 4 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved. For each Dark Tile passed through while connecting tiles this time, the Chain Combo's range expands by 1 surrounding cluster.",
  str_skill_desc_2202183 = "Deals <color=#00F6FF>165%</color> damage to enemies within <color=#00F6FF>3 surrounding clusters</color> 5 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved. For each Dark Tile passed through while connecting tiles this time, the Chain Combo's range expands by 1 surrounding cluster.",
  str_skill_desc_2202184 = "Deals <color=#00F6FF>150%</color> damage to enemies within <color=#00F6FF>2 surrounding clusters</color> 3 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved. Deals damage 1 additional time to the farthest target. This additional damage won't be halved when dealing damage to the same target. For each Dark Tile passed through while connecting tiles this time, the Chain Combo's range expands by 1 surrounding cluster.",
  str_skill_desc_2202185 = "Deals <color=#00F6FF>155%</color> damage to enemies within <color=#00F6FF>3 surrounding clusters</color> 4 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved. Deals damage 1 additional time to the farthest target. This additional damage won't be halved when dealing damage to the same target. For each Dark Tile passed through while connecting tiles this time, the Chain Combo's range expands by 1 surrounding cluster.",
  str_skill_desc_2202186 = "Deals <color=#00F6FF>165%</color> damage to enemies within <color=#00F6FF>3 surrounding clusters</color> 5 times in a fixed order. When a target takes damage more than once, the damage from the second time forth is halved. Deals damage 1 additional time to the farthest target. This additional damage won't be halved when dealing damage to the same target. For each Dark Tile passed through while connecting tiles this time, the Chain Combo's range expands by 1 surrounding cluster.",
  str_skill_desc_3002181 = "Converts 1 selected tile to a Blue <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> and deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color>.",
  str_skill_desc_30021811 = "Converts 1 selected tile to a Blue <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> and deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color>.",
  str_skill_desc_3402181 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected tile.",
  str_skill_desc_3412181 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color> centered on 1 selected tile.",
  str_skill_desc_3402182 = "Converts 1 selected tile to a Blue <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> and deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color>. For every 5 Capital points, gain 1 additional Capital as a dividend.",
  str_skill_desc_3412182 = "Converts 1 selected tile to a Blue <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> and deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color>. For every 5 Capital points, gain 1 additional Capital as a dividend.",
  str_skill_desc_30021812 = "Converts 1 selected tile to a Blue <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> and deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color>.",
  str_skill_desc_300218112 = "Converts 1 selected tile to a Blue <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> and deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color>.",
  str_skill_desc_34021812 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color> centered on 1 selected tile.",
  str_skill_desc_34121812 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color> centered on 1 selected tile.",
  str_skill_desc_34021822 = "Converts 1 selected tile to a Blue <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> and deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>5 tiles in a cross shape</color>. For every 5 Capital points, gain 1 additional Capital as a dividend.",
  str_skill_desc_34121822 = "Converts 1 selected tile to a Blue <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> and deals <color=#00F6FF>150%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color>. For every 5 Capital points, gain 1 additional Capital as a dividend.",
  str_skill_passive_desc_410218 = "Sheol starts the battle with <link=\"510218\"><#FFAE07><u>Investment Strategy</u></color></link> and can accumulate Capital to select investment strategies and gain corresponding combat abilities. (Reach Equipment Level Lv. 3/6/10 to unlock the investment strategies \"Driven by Mist,\" \"Crushing Wealth,\" and \"Capital Strike.\")",
  str_skill_passive_desc_413218 = "Sheol starts the battle with <link=\"513218\"><#FFAE07><u>Investment Strategy</u></color></link> and can accumulate Capital to select investment strategies and gain corresponding combat abilities. Each point of Capital gained after completing the second round of investment increases Sheol's ATK by 1%, up to 40 points. (Reach Equipment Level Lv. 3/6/10 to unlock the investment strategies \"Driven by Mist,\" \"Crushing Wealth,\" and \"Capital Strike.\")",
  str_skill_passive_desc_416218 = "Sheol starts the battle with <link=\"516218\"><#FFAE07><u>Investment Strategy</u></color></link> and can accumulate Capital to select investment strategies and gain corresponding combat abilities. Sheol starts the battle with 5 Capital. Each point of Capital gained after completing the second round of investment increases Sheol's ATK by 1%, up to 40 points. (Reach Equipment Level Lv. 3/6/10 to unlock the investment strategies \"Driven by Mist,\" \"Crushing Wealth,\" and \"Capital Strike.\")",
  str_skill_passive_desc_430218 = "Sheol starts the battle with <link=\"530218\"><#FFAE07><u>Investment Strategy</u></color></link> and can accumulate Capital to select investment strategies and gain corresponding combat abilities. After completing the first round of investment, she can make a second round of investment to get combat abilities she didn't have in the first round of investment. (Reach Equipment Level Lv. 3/6/10 to unlock the investment strategies \"Driven by Mist,\" \"Crushing Wealth,\" and \"Capital Strike.\")",
  str_skill_passive_desc_433218 = "Sheol starts the battle with <link=\"533218\"><#FFAE07><u>Investment Strategy</u></color></link> and can accumulate Capital to select investment strategies and gain corresponding combat abilities. After completing the first round of investment, she can make a second round of investment to get combat abilities she didn't have in the first round of investment. Each point of Capital gained after completing the second round of investment increases Sheol's ATK by 1%, up to 40 points. (Reach Equipment Level Lv. 3/6/10 to unlock the investment strategies \"Driven by Mist,\" \"Crushing Wealth,\" and \"Capital Strike.\")",
  str_skill_passive_desc_436218 = "Sheol starts the battle with <link=\"536218\"><#FFAE07><u>Investment Strategy</u></color></link> and can accumulate Capital to select investment strategies and gain corresponding combat abilities. After completing the first round of investment, she can make a second round of investment to get combat abilities she didn't have in the first round of investment. Sheol starts the battle with 5 Capital. Each point of Capital gained after completing the second round of investment increases Sheol's ATK by 1%, up to 40 points. (Reach Equipment Level Lv. 3/6/10 to unlock the investment strategies \"Driven by Mist,\" \"Crushing Wealth,\" and \"Capital Strike.\")",
  str_skill_upgrade_desc_16021813 = "Equipment Skill Enhancement: Each Capital point gained after completing the second round of investment increases Sheol's ATK by 1%, up to 40 points. (unlocks at Ascension III)",
  str_skill_upgrade_desc_16021816 = "Sheol starts the battle with 5 Capital. For every 5 Capital points she has when casting her Active Skill, she gains 1 additional Capital as a dividend.",
  str_skill_name_53920111 = "Normal Attack",
  str_skill_desc_53920111 = "Attacks enemies with a Normal Attack after moving, dealing lots of damage to them.",
  str_skill_desc_53920112 = "Deals damage to enemies within 2 surrounding clusters after moving.",
  str_skill_desc_53920214 = "After the team passes through a Dark Tile, Sheol deals damage to enemies within 2 surrounding clusters 2 times.",
  str_skill_upgrade_refine_desc_16021811 = "<color=#00F6FF>New Active Skill Variant</color>: <color=#FFFF00>Skill cooldown -1 after casting</color>. The Active Skill only deals damage and does not generate any Blue Dark Tiles.",
  str_skill_upgrade_refine_desc_16021812 = "Active Skill Enhancement: Increases Active Skill damage by <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16021813 = "Equipment Skill Enhancement: Reduces the Capital point cost of the second investment round by 1 point.",
  str_skill_name_70011191 = "Forsaken: Devour - Wholesome",
  str_skill_desc_70011191 = "When targets are within range, Aurorians and ghosts within two clusters in the forward direction are devoured. The Aurorians take damage and are then spat out to the edge of the board.",
  str_skill_name_70011192 = "Forsaken: Devour - Obliterate",
  str_skill_desc_70011192 = "Deals a massive amount of damage to targets when within range, and any ghosts surrounding the targets are eliminated instantly.",
  str_skill_name_70011193 = "Forsaken: Devour - Ghost Army",
  str_skill_desc_70011193 = "When the target is within range, a large number of ghosts are summoned, and all ghosts on the battlefield are enhanced.",
  str_skill_name_70011195 = "Forsaken: Devour - Wholesome",
  str_skill_desc_70011195 = "When targets are within range, Aurorians and ghosts within two clusters in the forward direction are devoured, dealing true damage to Aurorians. The more ghosts that are devoured, the higher the damage dealt. The Aurorians are then spat out to the edge of the board.",
  str_skill_name_200440103 = "Crushing Blow",
  str_skill_name_200450103 = "Blast Barrage",
  str_skill_name_200460103 = "Armed Onslaught",
  str_skill_name_200460104 = "Total Annihilation",
  str_skill_desc_200440103 = "Swings weapon to deal damage to Aurorians.",
  str_skill_desc_200450103 = "Deals damage to Aurorians in a cross shape to the maximum range.",
  str_skill_desc_200460103 = "Deals damage to Aurorians after moving.",
  str_skill_desc_200460104 = "Launches a piercing attack in the direction of Aurorians after moving, dealing damage to both enemies and allies, then loses a certain amount of HP.",
  str_skill_name_8004003 = "Explodes when Aurorians approach it. If left alone, it will explode after a certain number of rounds have passed and generate a 1-tile-long Forbidden Wall around it.",
  str_skill_desc_8004039 = "Damage boost in this round: Dreadblades use blades to attack targets within range 2 times, dealing extremely high damage.",
  str_skill_name_8004039 = "Double Slash+",
  str_skill_desc_8004055 = "Vilanor rushes over and slashes, dealing damage and casting a 5-tile-long Forbidden Wall horizontally beside the Aurorians. then teleports to a new location.",
  str_skill_desc_8004057 = "Vilanor rushes over and slashes, dealing damage and casting a 5-tile-long Forbidden Wall vertically beside the Aurorians, then teleports to a new location.",
  str_skill_desc_8004051 = "Vilanor rushes over and slashes, dealing damage and casting a 3-tile-long Forbidden Wall horizontally beside the Aurorians, then teleports to its original location.",
  str_skill_desc_8004053 = "Vilanor rushes over and slashes, dealing damage and casting a 3-tile-long Forbidden Wall vertically beside the Aurorians, then teleports to its original location.",
  str_skill_name_8004012 = "Summon Darkwasp Vinesmark+",
  str_skill_desc_8004012 = "Summons 1 Darkwasp and 1 Vinesmark into battle each round.",
  str_skill_desc_8004022 = "After stepping on an Exorcism Trap, from the next round onwards, Forbidden Walls around Aurorians expand to 3 surrounding clusters again.",
  str_skill_desc_8004040 = "Stepping on an Exorcism Trap will summon Forbidden Walls around enemies.",
  str_skill_desc_8004050 = "Stepping on an Exorcism Trap will remove all Forbidden Walls within 2 surrounding clusters.",
  str_skill_name_290640101 = "Trample",
  str_skill_name_290640102 = "Efficient Output",
  str_skill_name_290640103 = "Component Replacement",
  str_skill_desc_290640101 = "Consumes a certain percentage of its own HP and all stacks of Mechanical Armor after moving to attack targets within 2 tiles in front of itself. If the target is next to Blaugm, it knocks the target back by 1 tile. After attacking, it restores its own HP based on the number of Mechanical Armor stacks consumed.",
  str_skill_desc_290640102 = "Deals damage to all targets within a fan shape. The closer the target, the greater the damage dealt.",
  str_skill_desc_290640103 = "Blaugm powers up, permanently increasing its ATK, DEF, and Max HP, and gains a certain number of Mechanical Armor stacks.",
  str_skill_name_29063011 = "Oppressive Wind Speed",
  str_skill_name_29063012 = "Aims at the location of the Aurorians and charges to the edge of the board, dealing damage to all enemies within range along the way.",
  str_skill_name_29063013 = "Body Modification",
  str_skill_desc_29063011 = "Moves towards Aurorians and deals damage to enemies within 2 tiles in front of itself.",
  str_skill_desc_29063012 = "Data Strike",
  str_skill_desc_29063013 = "Ulysses uses Guardian Prototype to deal damage to Aurorians anywhere on the battlefield.",
