  str_skill_desc_2002212 = "Bool deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>16 tiles in a radial shape</color>.",
  str_skill_desc_2002213 = "Bool deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>24 tiles in a radial shape</color>.",
