  str_skill_desc_300221 = "Chooses any 1 tile, then selects 3 tiles within <color=#00F6FF>1 surrounding cluster</color> around it to turn them into <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>. Bool deals <color=#00F6FF>{1}%</color> damage to this area.",
  str_skill_desc_306221 = "Chooses any 1 tile, then selects 4 tiles within <color=#00F6FF>12 tiles in a diamond shape</color> around it to turn them into <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>. Bool deals <color=#00F6FF>{1}%</color> damage to this area.",
  str_skill_desc_320221 = "Chooses any 1 tile, then selects 3 tiles within <color=#00F6FF>1 surrounding cluster</color> around it to turn them into <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>. Bool deals <color=#00F6FF>{1}%</color> damage to this area. Gains 1 computation point each time damage is dealt.",
  str_skill_desc_326221 = "Chooses any 1 tile, then selects 4 tiles within <color=#00F6FF>12 tiles in a diamond shape</color> around it to turn them into <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>. Bool deals <color=#00F6FF>{1}%</color> damage to this area. Gains 1 computation point each time damage is dealt.",
  str_skill_desc_340221 = "Chooses any 1 tile, then selects 3 tiles within <color=#00F6FF>1 surrounding cluster</color> around it to turn them into <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>. Bool deals <color=#00F6FF>250%</color> damage to this area. Gains 1 computation point each time damage is dealt.",
  str_skill_desc_346221 = "Chooses any 1 tile, then selects 4 tiles within <color=#00F6FF>12 tiles in a diamond shape</color> around it to turn them into <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link>. Bool deals <color=#00F6FF>250%</color> damage to this area. Gains 1 computation point each time damage is dealt.",
  str_skill_passive_name_410221 = "Nanometric Magic Numbers",
  str_skill_passive_name_430221 = "Nanometric Magic Numbers",
  str_skill_passive_name_440221 = "Nanometric Magic Numbers",
  str_skill_passive_name_443221 = "Nanometric Magic Numbers",
  str_skill_passive_desc_410221 = "Gains 1 computation point each time passing through a <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. Each computation point increases Bool's damage by <color=#00F6FF>{1}</color>, and half of the computation points will be retained at the end of the round.",
  str_skill_passive_desc_430221 = "Gains 1 computation point each time passing through a <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. Each computation point increases Bool's damage by <color=#00F6FF>{1}</color>, and half of the computation points will be retained at the end of the round. If there are no less than <color=#00F6FF>3</color> computation points after Bool's action ends, Bool deals an additional <color=#00F6FF>100%</color> damage to the enemy who has received damage the most times from it.",
  str_skill_passive_desc_440221 = "Gains 1 computation point each time passing through a <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. Each computation point increases Bool's damage by <color=#00F6FF>6%</color>, and half of the computation points will be retained at the end of the round. If there are no less than <color=#00F6FF>3</color> computation points after Bool's action ends, Bool deals an additional <color=#00F6FF>100%</color> damage to the enemy who has received damage the most times from it.",
  str_skill_passive_desc_443221 = "Gains 1 computation point each time passing through a <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. Each computation point increases Bool's damage by <color=#00F6FF>6%</color>, and half of the computation points will be retained at the end of the round. If there are no less than <color=#00F6FF>3</color> computation points after Bool's action ends, Bool deals an additional <color=#00F6FF>120%</color> damage to the enemy who has received the most damage from it.",
  str_skill_upgrade_refine_desc_16022111 = "Equipment Skill Enhancement: Each computation point increases Bool's damage by <color=#00F6FF>6%</color>.",
  str_skill_upgrade_refine_desc_16022112 = "Active Skill Enhancement: Increases the damage factor by <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16022113 = "Equipment Skill Enhancement: Increases the additional damage dealt by Bool to <color=#00F6FF>120%</color>.",
  str_skill_upgrade_desc_16022113 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat.",
  str_skill_upgrade_desc_16022116 = "Active Skill Enhancement: The range expands to 13 tiles in a diamond shape, and the number of tiles that can be selected increases to 4.",
