  str_skill_desc_2002231 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_2002232 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>12 tiles in a diamond shape</color>.",
  str_skill_desc_2002233 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>24 tiles in a diamond shape</color>.",
  str_skill_desc_3002231 = "Selects 1 of 8 directions and converts <color=#00F6FF>all tiles</color> in that line to Yellow, prioritizing creating <color=#00F6FF>3</color> <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link> in the chosen direction.",
  str_skill_desc_3062231 = "Selects 1 of 8 directions and converts <color=#00F6FF>all tiles</color> in that line to Yellow, prioritizing creating <color=#00F6FF>5</color> <link=\"30093\"><#FFAE07><u>Dark Tiles</u></color></link> in the chosen direction.",
  str_skill_passive_desc_410223 = "Chen'ni's normal attacks target the enemy with the greatest difference in HP percentage from the team, dealing damage equal to <color=#00F6FF>{1}</color> of the team's average ATK.",
  str_skill_passive_desc_420223 = "Chen'ni's normal attacks target the enemy with the greatest difference in HP percentage from the team, dealing damage equal to <color=#00F6FF>{1}</color> of the team's average ATK. Triggers <color=#00F6FF>1.5×</color> damage every time passing through a <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>.",
  str_skill_passive_desc_430223 = "Chen'ni's normal attacks target the enemy with the greatest difference in HP percentage from the team, dealing damage equal to <color=#00F6FF>{1}</color> of the team's average ATK. Triggers <color=#00F6FF>1.5×</color> damage every time passing through a <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. The greater the HP percentage difference between the target and the team, the higher the damage, with a maximum increase of <color=#00F6FF>50%</color>.",
