  str_skill_desc_2002242 = "Throws Ah Ding, dealing <color=#00F6FF>{1}%</color> damage to the nearest tile of the closest enemy and 30% splash damage to <color=#00F6FF>4 surrounding tiles in a cross shape</color>.",
  str_skill_desc_2002243 = "Throws Ah Ding, dealing <color=#00F6FF>{1}%</color> damage to the nearest tile of the closest enemy and 30% splash damage to <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_300224 = "Selects a tile for the Chain Combo to be centered on and reduces the Chain Combo's trigger requirement by 3, applicable to this round only.",
  str_skill_desc_3002241 = "<color=#FFFF00>After casting, reduces skill cooldown by 1</color>, and if no Chain Combo is unleashed this round, normal attacks can be launched diagonally. Gains 2 Fiendling Guardian Flames with each normal attack.",
  str_skill_desc_3002242 = "<color=#FFFF00>After casting, increases skill cooldown by 1</color>. Selects a tile for the Chain Combo this round to be centered on, then deals <color=#00F6FF>100%</color> damage. Each Fiendling Guardian Flame increases the damage by 10%. Reduces the Chain Combo's trigger requirement by 3 for this round and gains an additional knockback effect.",
  str_skill_passive_desc_410224 = "Gains 1 Fiendling Guardian Flame for every Red tile traversed. Each Flame increases the damage of the next Chain Combo by <color=#00F6FF>{1}</color>, which resets after the Chain Combo is released.",
  str_skill_passive_desc_412224 = "Gains 1 Fiendling Guardian Flame for every Red tile traversed. Each Flame increases the damage of the next Chain Combo by <color=#00F6FF>{1}</color>, which resets after the Chain Combo is released. Obtain 10 Fiendling Guardian Flames at the start of battle.",
  str_skill_passive_desc_415224 = "Gains 1 Fiendling Guardian Flame for every tile traversed. Each Flame increases the damage of the next Chain Combo by <color=#00F6FF>{1}</color>, which resets after the Chain Combo is released. Obtain 10 Fiendling Guardian Flames at the start of battle.",
  str_skill_desc_9997040 = "Converts any 2 selected tiles into chromatic tiles, gaining 1 energy for each tile removed. Obtains 1 usage chance after accumulating 60 energy; up to 2 chances can be stored.",
  str_skill_desc_9997041 = "Selects a 3×3 area and removes all Blue tiles within it, gaining 1 energy for each tile removed. Obtains 1 usage chance after accumulating 50 energy; up to 3 chances can be stored.",
