  str_skill_name_3302312 = "Seal of Ardor",
  str_skill_desc_2002311 = "Deals <color=#00F6FF>130%</color> damage 3 times, assigned randomly to enemies within <color=#00F6FF>2 surrounding clusters</color> of this unit. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_2002312 = "Deals <color=#00F6FF>140%</color> damage 4 times, assigned randomly to enemies within <color=#00F6FF>2 surrounding clusters</color> of this unit. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_2002313 = "Deals <color=#00F6FF>150%</color> damage 5 times, assigned randomly to enemies within <color=#00F6FF>3 surrounding clusters</color> of this unit. When a target takes damage more than once, the damage from the second time forth is halved.",
  str_skill_desc_3002311 = "Wilhelm joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Choose any tile and then select another tile within <color=#00F6FF>2 surrounding clusters</color> to generate a rectangular area. Converts the selected tiles to Blue Dark Tiles. Each tile in the area uses <color=#00F6FF>2</color> Sanity.",
  str_skill_desc_3032311 = "Wilhelm joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Choose any tile and then select another tile within <color=#00F6FF>3 surrounding clusters</color> to generate a rectangular area. Converts the selected tiles to Blue Dark Tiles. Each tile in the area uses <color=#00F6FF>2</color> Sanity.",
  str_skill_desc_3202311 = "Wilhelm joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Choose any tile and then select another tile within <color=#00F6FF>2 surrounding clusters</color> to generate a rectangular area. Converts the selected tiles to Blue Dark Tiles. Each tile in the area uses <color=#00F6FF>2</color> Sanity, and <color=#00F6FF>1</color> stack of Blood Daze is inflicted on all enemies in the area. An additional stack is inflicted if Sanity drops below <color=#00F6FF>50</color> after casting.",
  str_skill_desc_3232311 = "Wilhelm joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Choose any tile and then select another tile within <color=#00F6FF>3 surrounding clusters</color> to generate a rectangular area. Converts the selected tiles to Blue Dark Tiles. Each tile in the area uses <color=#00F6FF>2</color> Sanity, and <color=#00F6FF>1</color> stack of Blood Daze is inflicted on all enemies in the area. An additional stack is inflicted if Sanity drops below <color=#00F6FF>50</color> after casting.",
  str_skill_desc_3302312 = "Restores 20 Sanity, but reduces Max Sanity by 20 after casting. Can be cast in succession until Max Sanity drops to 0.",
  str_skill_passive_name_4002311 = "Nocturnal Burial",
  str_skill_passive_name_4062311 = "Nocturnal Burial",
  str_skill_passive_desc_4002311 = "Replaces the Fear debuff inflicted by the team on the target with <color=#00F6FF>Blood Daze</color>. Each stack reduces the target's DEF by <color=#00F6FF>{1}</color>, up to 3 stacks, lasting 2 rounds. Each time a stack is removed (including when the target dies) or exceeds the limit, restores 1 Sanity. Wilhelm's Chain Combo applies 1 stack of <color=#00F6FF>Blood Daze</color> whenever dealing damage.",
  str_skill_passive_desc_4062311 = "Replaces the Fear debuff inflicted by the team on the target with <color=#00F6FF>Blood Daze</color>. Each stack reduces the target's DEF by <color=#00F6FF>{1}</color>, up to 3 stacks, lasting 2 rounds. Each time a stack is removed (including when the target dies) or exceeds the limit, restores 2 Sanity. Wilhelm's Chain Combo applies 1 stack of <color=#00F6FF>Blood Daze</color> whenever dealing damage.",
  str_skill_upgrade_desc_16023113 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat. Expands the selection range of the second tile to 3 surrounding clusters.",
  str_skill_upgrade_desc_16023116 = "Equipment Skill Enhancement: Restores 2 Sanity for each stack of Blood Daze that vanishes or exceeds the limit.",
