  str_skill_desc_2002322 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>16 tiles in a radial shape</color> and inflicts 1 stack of <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> for 2 rounds.",
  str_skill_desc_2002323 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color> and inflicts 1 stack of <link=\"10000\"><#FFAE07><u>Bleeding</u></color></link> for 2 rounds.",
  str_skill_desc_3002321 = "Consumes <color=#00F6FF>10%</color> of the team's Max HP to convert <color=#00F6FF>1</color> tile selected to dark tiles. Cannot be cast if HP is insufficient.",
