  str_skill_desc_3302321 = "Consumes <color=#00F6FF>10%</color> of the team's Max HP to convert <color=#00F6FF>1</color> tile selected to dark tiles. Cannot be cast if HP is insufficient. If the team's HP is below <color=#00F6FF>30%</color> after casting, converts the first selected tile to a red dark tile.",
  str_skill_desc_3302322 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Consumes <color=#00F6FF>25%</color> of the team's Max HP to convert <color=#00F6FF>2</color> tiles selected to dark tiles. Cannot be cast if HP is insufficient. If the team's HP is below <color=#00F6FF>30%</color> after casting, converts the first selected tile to a red dark tile.",
  str_skill_desc_3322321 = "Consumes <color=#00F6FF>10%</color> of the team's Max HP to convert <color=#00F6FF>1</color> tile selected to dark tiles. Cannot be cast if HP is insufficient. If the team's HP is below <color=#00F6FF>30%</color> after casting, converts the first selected tile to a red dark tile.",
  str_skill_desc_3322322 = "<color=#FFFF00>Skill cooldown +1 after casting</color>. Consumes <color=#00F6FF>25%</color> of the team's Max HP to convert <color=#00F6FF>2</color> tiles selected to dark tiles. Cannot be cast if HP is insufficient. If the team's HP is below <color=#00F6FF>30%</color> after casting, converts the first selected tile to a red dark tile.",
  str_skill_passive_desc_4002321 = "When the current HP percentage falls below <color=#00F6FF>50%</color>, generates a Crimson Blessing on the nearest traversable red tile. When passing through it, restores HP equal to <color=#00F6FF>{1}</color> of the ATK of Nails: Sacred Rite.",
  str_skill_passive_desc_4052321 = "When the current HP percentage falls below <color=#00F6FF>50%</color>, generates a Crimson Blessing on the nearest traversable red tile. When passing through it, restores HP equal to <color=#00F6FF>{1}</color> of the ATK of Nails: Sacred Rite. Deems Crimson Blessing as a dark tile when moving through it.",
  str_skill_passive_desc_4402321 = "When the current HP percentage falls below <color=#00F6FF>50%</color>, generates a Crimson Blessing on the nearest traversable red tile. When passing through it, restores HP equal to <color=#00F6FF>110%</color> of the ATK of Nails: Sacred Rite.",
  str_skill_passive_desc_4452321 = "When the current HP percentage falls below <color=#00F6FF>50%</color>, generates a Crimson Blessing on the nearest traversable red tile. When passing through it, restores HP equal to <color=#00F6FF>110%</color> of the ATK of Nails: Sacred Rite. Deems Crimson Blessing as a dark tile when moving through it.",
  str_skill_passive_desc_4502321 = "When the current HP percentage falls below <color=#00F6FF>50%</color>, generates a Crimson Blessing on the nearest traversable red tile. When passing through it, restores HP equal to <color=#00F6FF>110%</color> of the ATK of Nails: Sacred Rite and <color=#00F6FF>5%</color> of lost HP.",
  str_skill_passive_desc_4552321 = "When the current HP percentage falls below <color=#00F6FF>50%</color>, generates a Crimson Blessing on the nearest traversable red tile. When passing through it, restores HP equal to <color=#00F6FF>110%</color> of the ATK of Nails: Sacred Rite and <color=#00F6FF>5%</color> of lost HP. Deems Crimson Blessing as a dark tile when moving through it.",
  str_skill_passive_desc_4602321 = "When the current HP percentage falls below <color=#00F6FF>50%</color> and <color=#00F6FF>30%</color>, generates a Crimson Blessing on the nearest traversable red tile. When passing through it, restores HP equal to <color=#00F6FF>110%</color> of the ATK of Nails: Sacred Rite and <color=#00F6FF>5%</color> of lost HP.",
  str_skill_passive_desc_4652321 = "When the current HP percentage falls below <color=#00F6FF>50%</color> and <color=#00F6FF>30%</color>, generates a Crimson Blessing on the nearest traversable red tile. When passing through it, restores HP equal to <color=#00F6FF>110%</color> of the ATK of Nails: Sacred Rite and <color=#00F6FF>5%</color> of lost HP. Deems Crimson Blessing as a dark tile when moving through it.",
  str_skill_upgrade_desc_15023212 = "Active Skill Enhancement: Reduces skill cooldown by <color=#FFFF00>1</color> round.",
  str_skill_upgrade_desc_15023215 = "Equipment Skill Enhancement: Deems Crimson Blessing as a Dark Tile when moving through it.",
  str_skill_upgrade_refine_desc_15023211 = "Equipment Skill Enhancement: Restores HP equal to <color=#00F6FF>110%</color> of the ATK of Nails: Sacred Rite when passing through the Crimson Blessing.",
  str_skill_upgrade_refine_desc_15023212 = "Equipment Skill Enhancement: Additionally restores HP equal to <color=#00F6FF>5%</color> of lost HP.",
