  str_skill_desc_2302372 = "Deals <color=#00F6FF>170%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color> centered on the nearest enemy within <color=#00F6FF>12 tiles in a diamond shape</color>. Summons a Radiant Bubble at the target's location.",
