  str_skill_desc_3002371 = "Select a traversable tile from <color=#00F6FF>12 tiles in a diamond shape</color> as the starting point, then connect any number of <color=#00F6FF>Blue tiles</color> while ignoring all obstacles. Teleports instantly to the end of the connection. If there is an enemy on the last tile, deals <color=#00F6FF>200%</color> damage to the target before moving to an adjacent tile.",
  str_skill_desc_3032371 = "Select a traversable tile from <color=#00F6FF>12 tiles in a diamond shape</color> as the starting point, then connect any number of <color=#00F6FF>Blue tiles</color> while ignoring all obstacles. Teleports instantly to the end of the connection. If there is an enemy on the last tile, deals <color=#00F6FF>300%</color> damage to the target before moving to an adjacent tile.",
  str_skill_desc_3202371 = "Select a traversable tile from <color=#00F6FF>12 tiles in a diamond shape</color> as the starting point, then connect any number of <color=#00F6FF>Blue tiles, Dark tiles, or Radiant Bubble tiles</color> while ignoring all obstacles. Teleports to the end of the connection. If there is an enemy on the last tile, deals <color=#00F6FF>200%</color> damage to the target before moving to an adjacent tile.",
  str_skill_desc_3232371 = "Select a traversable tile from <color=#00F6FF>12 tiles in a diamond shape</color> as the starting point, then connect any number of <color=#00F6FF>Blue tiles, Dark tiles, or Radiant Bubble tiles</color> while ignoring all obstacles. Teleports to the end of the connection. If there is an enemy on the last tile, deals <color=#00F6FF>300%</color> damage to the target before moving to an adjacent tile.",
  str_skill_passive_name_4102371 = "Unreal",
  str_skill_passive_desc_4102371 = "At the start of each round, generates Radiant Bubbles on <color=#00F6FF>2</color> random traversable tiles that last for 3 rounds. When passing through a Radiant Bubble via connecting tiles or Active Skills, it deals <color=#00F6FF>{1}</color> damage to 3 enemies within <color=#00F6FF>3 surrounding clusters</color>.",
  str_skill_passive_name_4402371 = "Unreal",
  str_skill_passive_desc_4402371 = "At the start of each round, generates Radiant Bubbles on <color=#00F6FF>2</color> random traversable tiles that last for 3 rounds. When passing through a Radiant Bubble via connecting tiles or Active Skills, it deals <color=#00F6FF>140%</color> damage to 3 enemies within <color=#00F6FF>3 surrounding clusters</color>.",
  str_skill_passive_name_4502371 = "Unreal",
  str_skill_passive_desc_4502371 = "At the start of each round, generates Radiant Bubbles on <color=#00F6FF>2</color> random traversable tiles that last for 3 rounds. When passing through a Radiant Bubble via connecting tiles or Active Skills, it deals <color=#00F6FF>140%</color> damage to 4 enemies within <color=#00F6FF>3 surrounding clusters</color>.",
  str_skill_passive_name_4602371 = "Unreal",
  str_skill_passive_desc_4602371 = "At the start of each round, generates Radiant Bubbles on <color=#00F6FF>2</color> random traversable tiles that last for 3 rounds. When passing through a Radiant Bubble via connecting tiles or Active Skills, it deals <color=#00F6FF>140%</color> damage to 4 enemies within <color=#00F6FF>3 surrounding clusters</color>. Gain 1 Illusion Source when passing through Dark Tiles or Radiant Bubbles. Each point of Illusion Source increases Chain Combo damage by <color=#00F6FF>1%</color>.",
