  str_skill_desc_291020105 = "Deals increasing damage to Aurorians 3 times and knocks them back to the edge of the field.",
  str_skill_desc_291020113 = "Deals damage to Aurorians and summons Salvo Guns around them.",
  str_skill_passive_desc_443173 = "Immediately deals <color=#00F6FF>85%</color> damage to <color=#00F6FF>1</color> random target on the field whenever the team obtains <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including <link=\"30065\"><#FFAE07><u>absorption</u></color></link>). Starts the battle with <color=#00F6FF>33</color> Mortal Mark stacks and reduces <color=#00F6FF>1</color> stack for every enhanced tile obtained. Minos enters Minotaur State when all Marks have been removed, increasing his basic ATK by <color=#00F6FF>25%</color>, allowing his normal attacks to hit diagonal tiles, increasing Equipment Skill damage to <color=#00F6FF>2.5</color> times, and allowing his Chain Combo to deal normal damage when hitting the same target again.",
  str_skill_passive_desc_453173 = "Immediately deals <color=#00F6FF>85%</color> damage to <color=#00F6FF>1</color> random target on the field whenever the team obtains <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including <link=\"30065\"><#FFAE07><u>absorption</u></color></link>). Starts the battle with <color=#00F6FF>33</color> Mortal Mark stacks and reduces <color=#00F6FF>1</color> stack for every enhanced tile obtained. Minos enters Minotaur State when all Marks have been removed, increasing his basic ATK by <color=#00F6FF>25%</color>, allowing his normal attacks to hit diagonal tiles, and increasing Equipment Skill damage to <color=#00F6FF>2.5</color> times. Reduces the Chain Combo's trigger requirement by <color=#00F6FF>1/2/3</color> and its damage no longer decreases when hitting the same target.",
  str_skill_passive_desc_463173 = "Immediately deals <color=#00F6FF>85%</color> damage to <color=#00F6FF>1</color> random target on the field whenever the team obtains <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including <link=\"30065\"><#FFAE07><u>absorption</u></color></link>). Starts the battle with <color=#00F6FF>33</color> Mortal Mark stacks and reduces <color=#00F6FF>1</color> stack for every enhanced tile obtained. Minos enters Minotaur State when all Marks have been removed, increasing his basic ATK by <color=#00F6FF>25%</color>, allowing his normal attacks to hit diagonal tiles, and increasing Equipment Skill damage to <color=#00F6FF>2.5</color> times. Reduces the Chain Combo's trigger requirement by <color=#00F6FF>1/2/3</color> and its damage no longer decreases when hitting the same target. Increases Active Skill's damage factor to <color=#00F6FF>200%</color>.",
  str_skill_passive_desc_440173 = "Immediately deals <color=#00F6FF>85%</color> damage to <color=#00F6FF>1</color> random target on the field whenever the team obtains <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including <link=\"30065\"><#FFAE07><u>absorption</u></color></link>). Starts the battle with <color=#00F6FF>33</color> Mortal Mark stacks and reduces <color=#00F6FF>1</color> stack for every enhanced tile obtained. Minos enters Minotaur State when all Marks have been removed, increasing his basic ATK by <color=#00F6FF>20%</color>, allowing his normal attacks to hit diagonal tiles, increasing Equipment Skill damage to <color=#00F6FF>2.5</color> times, and Chain Combo damage no longer decreases when hitting the same target.",
  str_skill_passive_desc_450173 = "Immediately deals <color=#00F6FF>85%</color> damage to <color=#00F6FF>1</color> random target on the field whenever the team obtains <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including <link=\"30065\"><#FFAE07><u>absorption</u></color></link>). Starts the battle with <color=#00F6FF>33</color> Mortal Mark stacks and reduces <color=#00F6FF>1</color> stack for every enhanced tile obtained. Minos enters Minotaur State when all Marks have been removed, increasing his basic ATK by <color=#00F6FF>20%</color>, allowing his normal attacks to hit diagonal tiles, and increasing Equipment Skill damage to <color=#00F6FF>2.5</color> times. Reduces the Chain Combo's trigger requirement by <color=#00F6FF>1/2/3</color> and its damage no longer decreases when hitting the same target.",
  str_skill_passive_desc_460173 = "Immediately deals <color=#00F6FF>85%</color> damage to <color=#00F6FF>1</color> random target on the field whenever the team obtains <link=\"20001\"><#FFAE07><u>enhanced tiles</u></color></link> (including <link=\"30065\"><#FFAE07><u>absorption</u></color></link>). Starts the battle with <color=#00F6FF>33</color> Mortal Mark stacks and reduces <color=#00F6FF>1</color> stack for every enhanced tile obtained. Minos enters Minotaur State when all Marks have been removed, increasing his basic ATK by <color=#00F6FF>20%</color>, allowing his normal attacks to hit diagonal tiles, and increasing Equipment Skill damage to <color=#00F6FF>2.5</color> times. Reduces the Chain Combo's trigger requirement by <color=#00F6FF>1/2/3</color> and its damage no longer decreases when hitting the same target. Increases Active Skill's damage factor to <color=#00F6FF>200%</color>.",
  str_skill_upgrade_refine_desc_16017311 = "Equipment Skill Enhancement: Increases the damage factor to 85%.",
  str_skill_upgrade_refine_desc_16017312 = "Equipment Skill Enhancement: Reduces the Chain Combo's trigger requirement by 1/2/3 in the Minotaur State.",
  str_skill_upgrade_refine_desc_16017313 = "Equipment Skill Enhancement: Increases the Active Skill's damage factor to 200% in the Minotaur State.",
  str_skill_upgrade_refine_desc_14016911 = "Equipment Skill Enhancement: Increases Sadie's basic ATK by <color=#00F6FF>33%</color>. Each Crash Point increases the Active Skill damage factor by <color=#00F6FF>22%</color>.",
  str_skill_upgrade_refine_desc_14016912 = "Equipment Skill Enhancement: Gain 1 <color=#00F6FF>Crash Point</color> when passing through a Dark Tile.",
  str_skill_upgrade_refine_desc_14016913 = "Active Skill Enhancement: Expands the range of selectable tiles to <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_passive_desc_440169 = "Increases Sadie's basic ATK by <color=#00F6FF>33%</color>. Sadie deals up to <color=#00F6FF>3</color> Normal Attacks when connecting tiles, and the third Normal Attack deals double damage. After 3 attacks, gain 1 <color=#00F6FF>Crash Point</color> with the next Normal Attack. Each Crash Point increases the Active Skill damage factor by <color=#00F6FF>22%</color>. All Crash Points are cleared after using the Active Skill.",
  str_skill_passive_desc_450169 = "Increases Sadie's basic ATK by <color=#00F6FF>33%</color>. Sadie deals up to <color=#00F6FF>3</color> Normal Attacks when connecting tiles, and the third Normal Attack deals double damage. After 3 attacks, gain 1 <color=#00F6FF>Crash Point</color> with the next Normal Attack. Each Crash Point increases the Active Skill damage factor by <color=#00F6FF>22%</color>. All Crash Points are cleared after using the Active Skill. Gain 1 additional <color=#00F6FF>Crash Point</color> for each Dark Tile traversed.",
  str_skill_name_360169 = "Fly Ball",
  str_skill_name_365169 = "Fly Ball",
  str_skill_desc_360169 = "Deals <color=#00F6FF>300%</color> damage to 1 enemy within <color=#00F6FF>1 surrounding cluster</color> and knocks them back 2 tiles. Enemies blocked by <color=#00F6FF>obstacles</color> while getting knocked back take an additional <color=#00F6FF>200%</color> damage and are <color=#00F6FF>stunned</color> for 1 round. If blocked by another enemy instead, both are dealt damage and stunned.",
  str_skill_desc_365169 = "Deals <color=#00F6FF>300%</color> damage to 1 enemy within <color=#00F6FF>1 surrounding cluster</color> and knocks them back 3 tiles. Enemies blocked by <color=#00F6FF>obstacles</color> while getting knocked back take an additional <color=#00F6FF>200%</color> damage and are <color=#00F6FF>stunned</color> for 1 round. If blocked by another enemy instead, both are dealt damage and stunned.",
  str_skill_name_20053011 = "Whispers of the Deep Sea",
  str_skill_desc_20053011 = "Deals damage to enemy units within 1 surrounding cluster.",
  str_skill_name_20054011 = "Touch",
  str_skill_desc_20054011 = "When there is an Aurorian within 2 clusters of itself, it summons an Eclipsite near the target to assist itself.",
  str_skill_upgrade_desc_17023613 = "Active Skill Enhancement: Gain 5 Vis at the start of each round.",
  str_skill_upgrade_desc_17023616 = "New Active Skill: Can be cast to return to the team while in the off-team state, dealing <color=#00F6FF>550%</color> damage to tiles along the way.",
  str_skill_passive_name_4102361 = "Agitato",
  str_skill_name_2002361 = "Czerny's Miracle",
  str_skill_name_2002362 = "Czerny's Miracle",
  str_skill_name_2002363 = "Czerny's Miracle",
  str_skill_name_2002364 = "Czerny's Miracle",
  str_skill_name_3302361 = "Con Brio",
  str_skill_name_3302362 = "Returning Stars",
  str_skill_desc_3302361 = "Gains <link=\"30125\"><#FFAE07><u>Vis</u></color></link> during combat. Upon activating the skill, Claymore enters a unique combat mode, allowing independent <link=\"30127\"><#FFAE07><u>tile connections</u></color></link>. After the connection, Claymore enters the <link=\"30128\"><#FFAE07><u>off-team state</u></color></link>, leaving an <link=\"30129\"><#FFAE07><u>afterimage</u></color></link> on the final tile connected, which will serve as the starting point for the next Active Skill.",
  str_skill_desc_3332361 = "Gains <link=\"30126\"><#FFAE07><u>Vis</u></color></link> during combat. Upon activating the skill, Claymore enters a unique combat mode, allowing independent <link=\"30127\"><#FFAE07><u>tile connections</u></color></link>. After the connection, Claymore enters the <link=\"30128\"><#FFAE07><u>off-team state</u></color></link>, leaving an <link=\"30129\"><#FFAE07><u>afterimage</u></color></link> on the final tile connected, which will serve as the starting point for the next Active Skill.",
  str_skill_desc_3302362 = "Can be cast to return to the team while in the off-team state, dealing <color=#00F6FF>550%</color> damage to tiles along the way.",
  str_skill_desc_2002361 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>4 surrounding tiles</color>.",
  str_skill_desc_2002362 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. Gains 3 Vis if not in the off-team state.",
  str_skill_desc_2002363 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>12 tiles in a diamond shape</color>. Gains 4 Vis if not in the off-team state.",
  str_skill_desc_2002364 = "Deals <color=#00F6FF>175%</color> damage to <color=#00F6FF>2 surrounding clusters</color>. Gains 5 Vis if not in the off-team state.",
  str_skill_passive_desc_4102361 = "Claymore is a <color=#00F6FF>non-elemental</color> Aurorian and has a <color=#00F6FF>100%</color> Element Counter when attacking or being attacked. <color=#00F6FF>Claymore takes action during battle when he is Captain, but only engages as a team member when all tiles connected are chromatic tiles.</color> Each use of an Active Skill consumes 1 Vis, granting Claymore 1 stack of Star Power. Star Power increases damage by <color=#00F6FF>{1}</color>, up to 99 stacks.",
  str_skill_passive_desc_4402361 = "Claymore is a <color=#00F6FF>non-elemental</color> Aurorian and has a <color=#00F6FF>100%</color> Element Counter when attacking or being attacked. <color=#00F6FF>Claymore takes action during battle when he is Captain, but only engages as a team member when all tiles connected are chromatic tiles.</color> Each use of an Active Skill consumes 1 Vis, granting Claymore 1 stack of Star Power. Star Power increases damage by <color=#00F6FF>1.1%</color>, up to 99 stacks.",
  str_skill_passive_desc_4602361 = "Claymore is a <color=#00F6FF>non-elemental</color> Aurorian and has a <color=#00F6FF>100%</color> Element Counter when attacking or being attacked. <color=#00F6FF>Claymore takes action during battle when he is Captain, but only engages as a team member when all tiles connected are chromatic tiles.</color> Each use of an Active Skill consumes 1 Vis, granting Claymore 2 stacks of Star Power. Star Power increases damage by <color=#00F6FF>1.1%</color>, up to 99 stacks.",
  str_skill_upgrade_refine_desc_17023611 = "Equipment Skill Enhancement: Increases the factor to <color=#00F6FF>1.1%</color>.",
  str_skill_upgrade_refine_desc_17023612 = "New Tier <color=#00F6FF>4</color> Chain Combo: Requires 12 connected tiles. Deals 175% damage to 2 surrounding clusters. Gains 5 Vis if not in the off-team state.",
  str_skill_upgrade_refine_desc_17023613 = "Equipment Skill Enhancement: <color=#00F6FF>Doubles</color> the Star Power stacks gained.",
  str_skill_upgrade_desc_16023813 = "Active Skill Enhancement: Changes Active Skill to <color=#FFFF00>Preemptive Strike</color>. Available upon entering combat.",
  str_skill_upgrade_desc_16023816 = "Active Skill Enhancement: Increases the number of tiles you can select by <color=#00F6FF>1</color>.",
  str_skill_name_2002381 = "Celestial Edge",
  str_skill_desc_2002381 = "Throws a feather blade at the <color=#00F6FF>nearest enemy</color>, dealing 170% damage, which then bounces to the next <color=#00F6FF>closest enemy</color>. For each cluster between targets, the final damage increases by 10%, up to 50%. Damage is further boosted based on Chain Combo count.",
  str_skill_name_3002381 = "Revelatory Message",
  str_skill_name_3062381 = "Revelatory Message",
  str_skill_name_3302381 = "Revelatory Message Variant I",
  str_skill_name_3362381 = "Revelatory Message Variant I",
  str_skill_desc_3002381 = "Converts any <color=#00F6FF>5</color> selected tiles into enhanced tiles.",
  str_skill_desc_3062381 = "Converts any <color=#00F6FF>6</color> selected tiles into enhanced tiles.",
  str_skill_desc_3302381 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Converts any <color=#00F6FF>3</color> selected tiles into enhanced tiles.",
  str_skill_desc_3362381 = "<color=#FFFF00>Skill cooldown -1 after casting</color>. Converts any <color=#00F6FF>4</color> selected tiles into enhanced tiles.",
  str_skill_passive_name_4102381 = "Inherited Starlight",
  str_skill_passive_name_4162381 = "Inherited Starlight",
  str_skill_passive_desc_4102381 = "Gain <color=#00F6FF>1 Starlight Mark</color> for <color=#00F6FF>each enhanced tile</color> obtained. Chain Combos consume <color=#00F6FF>a third</color> of the Starlight Marks, adding <color=#00F6FF>{1}%</color> of the team's average ATK as extra damage per stack.",
  str_skill_passive_desc_4162381 = "Gain <color=#00F6FF>1 Starlight Mark</color> for <color=#00F6FF>each enhanced tile</color> obtained. Chain Combos consume <color=#00F6FF>a third</color> of the Starlight Marks, adding <color=#00F6FF>{1}</color> of the team's average ATK as extra damage per stack. Every enhanced tile obtained in a single round reduces the Chain Combo trigger requirement by 1.",
  str_skill_upgrade_refine_desc_15017611 = "Equipment Skill Enhancement: Every <color=#00F6FF>4</color> normal attacks, Beretta pierces her current target with 1 Australis Spear.",
  str_skill_upgrade_refine_desc_15017612 = "Active Skill Enhancement: Each Australis Spear deals <color=#00F6FF>100%</color> damage to the target.",
  str_skill_upgrade_refine_desc_15017613 = "Active Skill Enhancement: Each Australis Spear recovers <color=#00F6FF>15%–22.5%</color> of the damage dealt as HP when it deals damage to the target.",
  str_skill_passive_desc_4401761 = "Every <color=#00F6FF>4</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_passive_desc_4451761 = "Every <color=#00F6FF>4</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_desc_3501761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>2 surrounding clusters</color>. Deals <color=#00F6FF>100%</color> damage and recovers HP by <color=#00F6FF>10%–15%</color> of the damage dealt in this way for each Australis Spear pulled out. The lower the team's HP, the higher the recovery factor.",
  str_skill_desc_3521761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>100%</color> damage and recovers HP by <color=#00F6FF>10%–15%</color> of the damage dealt in this way for each Australis Spear pulled out. The lower the team's HP, the higher the recovery factor.",
  str_skill_desc_3551761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>100%–120%</color> damage and recovers HP by <color=#00F6FF>10%–15% of</color> the damage dealt in this way for each <color=#00F6FF>Australis Spear</color> pulled out. The lower the target's current HP, the higher the damage factor. The lower the team's HP, the higher the recovery factor.",
  str_skill_desc_3601761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>2 surrounding clusters</color>. Deals <color=#00F6FF>100%</color> damage and recovers HP by <color=#00F6FF>15%–22.5%</color> of the damage dealt in this way for each Australis Spear pulled out. The lower the team's HP, the higher the recovery factor.",
  str_skill_desc_3621761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>100%</color> damage and recovers HP by <color=#00F6FF>15%–22.5%</color> of the damage dealt in this way for each Australis Spear pulled out. The lower the team's HP, the higher the recovery factor.",
  str_skill_desc_3651761 = "Pulls out <color=#00F6FF>Australis Spears</color> from all enemies within <color=#00F6FF>3 surrounding clusters</color>. Deals <color=#00F6FF>100%–120%</color> damage and recovers HP by <color=#00F6FF>15%–22.5% of</color> the damage dealt in this way for each <color=#00F6FF>Australis Spear</color> pulled out. The lower the target's current HP, the higher the damage factor. The lower the team's HP, the higher the recovery factor.",
  str_skill_name_3501821 = "Serpent's Constriction Variant I",
  str_skill_name_3601821 = "Serpent's Constriction Variant II",
  str_skill_desc_3501821 = "Active Skill can be unleashed when <color=#00F6FF>2</color> <link=\"30074\"><#FFAE07><u>Serpent Flares</u></color></link> are lit, and <color=#FFFF00>2 Serpent Flares will be extinguished upon its cast</color>. Selects 1 tile and deals <color=#00F6FF>400%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color>. This does not trigger the Equipment Skill: Moonglow Relict Arts.",
  str_skill_desc_3601821 = "Active Skill can be unleashed when <color=#00F6FF>2</color> <link=\"30074\"><#FFAE07><u>Serpent Flares</u></color></link> are lit, and <color=#FFFF00>2 Serpent Flares will be extinguished upon its cast</color>. Triggers the Equipment Skill: Moonglow Relict Arts, dealing <color=#00F6FF>300%</color> damage to <color=#00F6FF>all</color> enemies.",
  str_skill_upgrade_refine_desc_16018211 = "Active Skill Enhancement: Increases the damage factor to 400%.",
  str_skill_upgrade_refine_desc_16018212 = "<color=#00F6FF>New Active Skill Variant I</color>: Active Skill can be unleashed when 2 Serpent Flares are lit, and 2 Serpent Flares will be extinguished upon its cast. Selects 1 tile and deals 400% damage to 13 tiles in a diamond shape. This does not trigger the Equipment Skill: Moonglow Relict Arts.",
  str_skill_upgrade_refine_desc_16018213 = "<color=#00F6FF>New Active Skill Variant II</color>: Active Skill can be unleashed when 2 Serpent Flares are lit, and 2 Serpent Flares will be extinguished upon its cast. Triggers the Equipment Skill: Moonglow Relict Arts, dealing 300% damage to all enemies.",
  str_skill_desc_3401821 = "Active Skill can be unleashed when <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Serpent Flares</u></color></link> are lit. Selects 1 tile and deals <color=#00F6FF>400%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color>. All Serpent Flares will be extinguished after using the Active Skill.",
  str_skill_upgrade_desc_16024113 = "Active Skill Enhancement: Reduces Active Skill cooldown by <color=#00F6FF>1</color> round and increases the damage factor by <color=#00F6FF>50%</color>.",
  str_skill_upgrade_desc_16024116 = "New Active Skill Variant: <color=#00F6FF>Doubles</color> Sanity consumption and damage dealt. Generate up to <color=#00F6FF>3</color> Dark Tiles.",
