  str_skill_desc_2002411 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color>.",
  str_skill_desc_2002412 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>12 tiles in a diamond shape</color>.",
  str_skill_desc_2002413 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color>.",
  str_skill_desc_2302411 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>1 surrounding cluster</color>. <link=\"30124\"><#FFAE07><u>Absorbs</u></color></link> the dark tiles within the surrounding 4 tiles.",
  str_skill_desc_2302412 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>12 tiles in a diamond shape</color>. <link=\"30124\"><#FFAE07><u>Absorbs</u></color></link> the dark tiles within 1 surrounding cluster.",
  str_skill_desc_2302413 = "Deals <color=#00F6FF>{1}%</color> damage to <color=#00F6FF>2 surrounding clusters</color>. <link=\"30124\"><#FFAE07><u>Absorbs</u></color></link> the dark tiles within the surrounding 12 tiles in a diamond shape.",
  str_skill_desc_3002411 = "Pepita joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Consumes <color=#00F6FF>15</color> sanity points to deal 150% DMG to a selected enemy, generating 1 dark tile beneath the target.",
  str_skill_desc_3032411 = "Pepita joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Consumes <color=#00F6FF>15</color> sanity points to deal 200% DMG to a selected enemy, generating 1 dark tile beneath the target.",
  str_skill_desc_3062411 = "Pepita joins the battle with the <link=\"30039\"><#FFAE07><u>Sanity System</u></color></link>. Consumes <color=#00F6FF>30</color> sanity points to deal 400% DMG to a selected enemy, generating up to 3 dark tiles randomly beneath the target.",
  str_skill_passive_name_4102411 = "Flames Ablaze",
  str_skill_passive_name_4202411 = "Flames Ablaze",
  str_skill_passive_desc_4102411 = "Each time Pepita acquires a dark tile, she gains <color=#00F6FF>1</color> stack of Heart's Flame, up to <color=#00F6FF>7</color> stacks. The current Captain consumes 1 stack of Heart's Flame with each normal attack, increasing its final damage by <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_4202411 = "Each time Pepita acquires a Dark Tile, she gains <color=#00F6FF>1</color> Heart's Flame, up to <color=#00F6FF>7</color>. The current Captain consumes 1 Heart's Flame with each normal attack, increasing its final damage by <color=#00F6FF>{1}</color>. At the start of each round, <color=#00F6FF>2</color> Dark Tiles are randomly generated beneath enemies on the field.",
